'use server'

/**
 * @fileoverview Server Actions para Gestión de Citas (Appointments)
 * @description CRUD y operaciones críticas en el flujo de citas médicas
 * @author SOFIA - Builder
 * @version 1.0.0
 * @id IMPL-20260225-05
 * 
 * Implementa:
 * - Creación de citas
 * - Listado con filtros
 * - Actualización de estado
 * - Check-in que genera MedicalEvent
 * - Integración con auditoría
 */

import { getServerSession } from 'next-auth/next'
import { authOptions } from '@/auth'
import prisma from '@/lib/prisma'
import { revalidatePath } from 'next/cache'
import { isCompanyOperativa } from '@/services/company.service'
import { logAudit } from '@/actions/audit.actions'
import { generateExpedientId } from '@/lib/id.utils'
import {
  type CorroborationResult,
  type IdentityDocumentType,
  type IdentityEvidenceMode,
  type IdentityExceptionReason,
} from '@/lib/reception-corroboration'
import QRCode from 'qrcode'

/**
 * Crea una nueva cita y registra en auditoría
 * @param data - Datos de la cita (workerId, companyId, branchId, scheduledAt, notes, source)
 * @returns Cita creada o error
 */
export async function createAppointment(data: {
  workerId: string
  companyId: string
  branchId: string
  scheduledAt: Date | string
  notes?: string
  source?: string
  serviceProfileId?: string | null
}) {
  try {
    const session = await getServerSession(authOptions)

    if (!session?.user) {
      throw new Error('Usuario no autenticado')
    }

    // IMPL-20260623-03 (GAP-4): Bloquear creación de citas para clientes
    // DESHABILITADOS o PENDIENTE_REVISION. Citas previas persisten.
    if (data.companyId) {
      const operativa = await isCompanyOperativa(data.companyId)
      if (!operativa) {
        return {
          success: false,
          error: 'CLIENTE_DESHABILITADO',
        }
      }
    }

    // Convertir scheduledAt a Date si es string
    const scheduledDate = typeof data.scheduledAt === 'string'
      ? new Date(data.scheduledAt)
      : data.scheduledAt

    // Generar ID de Papeleta automático (EXP-YYYYNNN)
    const expedientId = await generateExpedientId(prisma)

    // Generar QR Real usando librería 'qrcode'
    // Almacenamos DataURL (Base64) directamente en DB para evitar hosting externo
    const qrData = JSON.stringify({
       exp: expedientId,
       uid: data.workerId,
       date: scheduledDate.toISOString()
    });

    const qrCode = await QRCode.toDataURL(qrData, {
      errorCorrectionLevel: 'H',
      margin: 2,
      scale: 8,
      color: {
        dark: '#000000',
        light: '#ffffff'
      }
    });

    // IMPL-20260519-10: QR operativo mínimo — payload AMI|NOMBRE=...|FN=YYYY-MM-DD
    // Independiente del QR de check-in; orientado a recaptura en estaciones
    const workerForQr = await prisma.worker.findUnique({
      where: { id: data.workerId },
      select: { firstName: true, lastName: true, dob: true }
    })
    const qrOperativoPayload = workerForQr
      ? `AMI|NOMBRE=${(workerForQr.firstName + ' ' + workerForQr.lastName).toUpperCase()}|FN=${workerForQr.dob ? workerForQr.dob.toISOString().slice(0, 10) : ''}`
      : `AMI|NOMBRE=SIN_NOMBRE|FN=`
    const qrOperativo = await QRCode.toDataURL(qrOperativoPayload, {
      errorCorrectionLevel: 'M',
      margin: 2,
      scale: 6,
      color: { dark: '#1e293b', light: '#ffffff' }
    })

    const appointment = await prisma.appointment.create({
      data: {
        workerId: data.workerId,
        companyId: data.companyId,
        branchId: data.branchId,
        scheduledAt: scheduledDate,
        notes: data.notes || null,
        source: data.source || 'SUCURSAL',
        status: 'SCHEDULED',
        expedientId,
        qrCode,
        qrOperativo,  // IMPL-20260519-10
        serviceProfileId: data.serviceProfileId || null,
      },
      include: {
        worker: {
          select: { id: true, firstName: true, lastName: true, universalId: true, phone: true },
        },
        company: {
          select: { id: true, name: true },
        },
        branch: {
          select: { id: true, name: true, address: true },
        },
      },
    })

    // Registrar en auditoría
    await logAudit('CREATE', 'Appointment', appointment.id, {
      workerId: data.workerId,
      companyId: data.companyId,
      branchId: data.branchId,
      scheduledAt: scheduledDate,
      source: data.source || 'SUCURSAL'
    })

    revalidatePath('/appointments')
    revalidatePath('/dashboard')

    return {
      success: true,
      appointment,
    }
  } catch (error) {
    console.error('[CREATE APPOINTMENT ERROR]:', error)
    return {
      success: false,
      error: error instanceof Error ? error.message : 'Error al crear cita',
    }
  }
}

/**
 * Obtiene listado de citas con filtros opcionales
 * @param date - Filtrar por fecha (YYYY-MM-DD)
 * @param branchId - Filtrar por sucursal
 * @returns Listado de citas o error
 */
export async function getAppointments(date?: string, branchId?: string) {
  try {
    const session = await getServerSession(authOptions)

    if (!session?.user) {
      throw new Error('Usuario no autenticado')
    }

    const filters: Record<string, unknown> = {}

    // Filtro por fecha (Fix: manejar range ampliado para cubrir timezones)
    if (date) {
      // date viene como "2023-10-25"
      // Buscamos con holgura de +/- 1 día para capturar citas que por timezone caen en día anterior/siguiente UTC
      const targetDate = new Date(`${date}T12:00:00.000Z`)
      const startRange = new Date(targetDate)
      startRange.setDate(startRange.getDate() - 1) // Día anterior
      const endRange = new Date(targetDate)
      endRange.setDate(endRange.getDate() + 1) // Día siguiente

      filters.scheduledAt = {
        gte: startRange,
        lte: endRange,
      }

      // NOTA: El frontend deberá filtrar visualmente las que no correspondan al día seleccionado localmente
    }

    // Filtro por sucursal
    if (branchId) {
      filters.branchId = branchId
    }

    const appointments = await prisma.appointment.findMany({
      where: filters,
      include: {
        worker: {
          select: {
            id: true,
            firstName: true,
            lastName: true,
            universalId: true,
            email: true,
          },
        },
        company: {
          select: { id: true, name: true },
        },
        branch: {
          select: { id: true, name: true, hourlyCapacity: true, openingTime: true, closingTime: true },
        },
      },
      orderBy: {
        scheduledAt: 'asc',
      },
    })

    return {
      success: true,
      appointments,
    }
  } catch (error) {
    console.error('[GET APPOINTMENTS ERROR]:', error)
    return {
      success: false,
      error: error instanceof Error ? error.message : 'Error al obtener citas',
    }
  }
}

/**
 * Actualiza el estado de una cita
 * @param appointmentId - ID de la cita
 * @param status - Nuevo estado (SCHEDULED, CONFIRMED, CANCELLED, NO_SHOW, COMPLETED)
 * @returns Cita actualizada o error
 */

export async function updateAppointmentStatus(
  appointmentId: string,
  status: string // Usar string en la firma para compatibilidad con Enum de Prisma
) {
  try {
    const session = await getServerSession(authOptions)

    if (!session?.user) {
      throw new Error('Usuario no autenticado')
    }

    // Fix: Obtener el estado anterior para auditoría correcta
    const currentAppointment = await prisma.appointment.findUnique({
      where: { id: appointmentId },
      select: { status: true }
    })

    if (!currentAppointment) {
      throw new Error('Cita no encontrada')
    }

    const previousStatus = currentAppointment.status

    const appointment = await prisma.appointment.update({
      where: { id: appointmentId },
      // @ts-ignore - Prisma genera tipos estrictos para status enum
      data: { status },
      include: {
        worker: {
          select: { id: true, firstName: true, lastName: true },
        },
        company: {
          select: { id: true, name: true },
        },
      },
    })

    // Registrar cambio en auditoría
    await logAudit('UPDATE', 'Appointment', appointmentId, {
      previousStatus: previousStatus,
      newStatus: status,
    })

    revalidatePath('/appointments')

    return {
      success: true,
      appointment,
    }
  } catch (error) {
    console.error('[UPDATE APPOINTMENT STATUS ERROR]:', error)
    return {
      success: false,
      error: error instanceof Error ? error.message : 'Error al actualizar cita',
    }
  }
}

/**
 * OPERACIÓN CRÍTICA: Check-in de una cita
 * 1. Cambia el estado de Appointment a COMPLETED
 * 2. Crea un MedicalEvent asociado
 * 3. Enlaza appointmentId al evento médico
 * 4. Registra en auditoría
 * 
 * @param appointmentId - ID de la cita
 * @returns MedicalEvent creado o error
 */

export async function checkInAppointment(appointmentId: string) {
  try {
    const session = await getServerSession(authOptions)

    if (!session?.user) {
      throw new Error('Usuario no autenticado')
    }

    /**
     * FIX-20260318-01
     * @see context/checkpoints/CHK_ARCH-20260318-09-VALIDACION-FINAL.md
     * Cargamos el perfil y sus pruebas fuera de la transacción para reducir el tiempo
     * del bloque interactivo y evitar expiraciones al instanciar EventTests.
     */
    const appointmentSnapshot = await prisma.appointment.findUnique({
      where: { id: appointmentId },
      include: {
        worker: true,
        company: true,
        branch: true,
        medicalEvents: true,
        serviceProfile: {
          include: {
            tests: {
              include: {
                test: { select: { id: true, name: true } },
              },
            },
          },
        },
      },
    })

    if (!appointmentSnapshot) {
      throw new Error('Cita no encontrada')
    }

    if (appointmentSnapshot.medicalEvents) {
      throw new Error('Esta cita ya tiene un evento médico asociado')
    }

    if (appointmentSnapshot.status === 'COMPLETED' || appointmentSnapshot.status === 'CANCELLED') {
      throw new Error(`La cita ya está en estado ${appointmentSnapshot.status}`)
    }

    if (!appointmentSnapshot.serviceProfile) {
      throw new Error('No se puede hacer Check-in: la cita no tiene un perfil clínico (serviceProfileId) asignado.')
    }

    const eventTestsData = appointmentSnapshot.serviceProfile.tests.map((profileTest) => ({
      testId: profileTest.test.id,
      testNameSnapshot: profileTest.test.name,
      status: 'PENDING' as const,
    }))

    // Fix: Uso de transacción para garantizar atomicidad (Cita COMPLETADA + Evento Creado + Auditoría)
    const result = await prisma.$transaction(async (tx) => {
      const currentAppointment = await tx.appointment.findUnique({
        where: { id: appointmentId },
        select: {
          id: true,
          status: true,
          workerId: true,
          branchId: true,
          companyId: true,
          medicalEvents: { select: { id: true } },
        },
      })

      if (!currentAppointment) {
        throw new Error('Cita no encontrada')
      }

      if (currentAppointment.medicalEvents) {
        throw new Error('Esta cita ya tiene un evento médico asociado')
      }

      if (currentAppointment.status === 'COMPLETED' || currentAppointment.status === 'CANCELLED') {
        throw new Error(`La cita ya está en estado ${currentAppointment.status}`)
      }

      // 2. Actualizar estado de Cita a COMPLETED
      const updatedAppointment = await tx.appointment.update({
        where: { id: appointmentId },
        data: { status: 'COMPLETED' },
      })

      // 3. Crear MedicalEvent vinculado
      const newMedicalEvent = await tx.medicalEvent.create({
        data: {
          workerId: currentAppointment.workerId,
          branchId: currentAppointment.branchId,
          status: 'CHECKED_IN',
          checkInDate: new Date(),
          appointmentId: appointmentId, // Usar ID directo si el connect falla, es más seguro y simple
          // IMPL-20260313-04: Ligar empresa facturadora desde la cita
          billingCompanyId: currentAppointment.companyId || null,
        },
        include: {
          worker: {
            select: { id: true, firstName: true, lastName: true, universalId: true },
          },
          branch: {
            select: { id: true, name: true },
          },
        },
      })

      // IMPL-20260313-04: Instanciar pruebas del perfil médico como EventTest (PENDING)
      if (eventTestsData.length > 0) {
        await tx.eventTest.createMany({
          data: eventTestsData.map((eventTest) => ({
            eventId: newMedicalEvent.id,
            ...eventTest,
          })),
        })
      }

      // 4. Registrar en auditoría DENTRO de la transacción (Critical Path)
      // FIX-20260313-02: Garantizar atomidad ACID reemplazando `logAudit` (que engullía errores) 
      // por una inserción manual transaccional `tx.auditLog.create`
      await tx.auditLog.create({
        data: {
          action: 'CHECK_IN',
          entity: 'Appointment',
          entityId: appointmentId,
          userId: session.user.id,
          details: {
            medicalEventId: newMedicalEvent.id,
            workerId: newMedicalEvent.workerId,
            branchId: newMedicalEvent.branchId,
            timestamp: new Date().toISOString()
          }
        }
      })

      return { appointment: updatedAppointment, medicalEvent: newMedicalEvent }
    }, {
      maxWait: 10000,
      timeout: 15000,
    })

    // Comentamos la auditoría externa antigua
    /* await logAudit('CHECK_IN', 'Appointment', appointmentId, { ... }) */

    revalidatePath('/appointments')
    revalidatePath('/reception') // Importante actualizar tablero
    revalidatePath('/dashboard')

    return {
      success: true,
      medicalEvent: result.medicalEvent,
      appointment: result.appointment,
    }
  } catch (error) {
    console.error('[CHECK-IN APPOINTMENT ERROR]:', error)
    return {
      success: false,
      error: error instanceof Error ? error.message : 'Error al procesar check-in',
    }
  }
}

/**
 * Procesa el Check-in mediante escaneo de QR
 * Decodifica el JSON del QR, busca la cita por expediente y ejecuta el check-in.
 * @param qrContent - String JSON escaneado del código QR
 */
export async function processQRCheckIn(qrContent: string) {
  try {
    // 🛡️ SECURITY: Validación de sesión obligatoria
    // Previene enumeración de datos sensibles de trabajadores a externos
    const session = await getServerSession(authOptions)
    if (!session?.user) {
      return { success: false, error: 'Sesión expirada o no autorizada.' }
    }

    let data;
    try {
      data = JSON.parse(qrContent);
    } catch (e) {
      return { success: false, error: 'Código QR inválido o corrupto.' }
    }

    if (!data.exp) {
      return { success: false, error: 'El QR no contiene un ID de expediente válido.' }
    }

    // Buscar cita por Expedient ID
    const appointment = await prisma.appointment.findUnique({
      where: { expedientId: data.exp },
      select: { 
        id: true, 
        status: true, 
        scheduledAt: true,
        worker: { select: { firstName: true, lastName: true } } 
    }
    });

    if (!appointment) {
      return { success: false, error: 'No se encontró ninguna cita asociada a este QR.' }
    }

    if (appointment.status === 'COMPLETED') {
      return { success: false, error: `El trabajador ${appointment.worker.firstName} ya realizó su Check-in.` }
    }

    if (appointment.status === 'CANCELLED') {
      return { success: false, error: 'Esta cita fue cancelada.' }
    }

    // Validación de horario
    const now = new Date();
    const scheduledDate = new Date(appointment.scheduledAt);

    // Margen de tolerancia: permitir Check-in desde 1 hora antes hasta 2 horas después
    // Usamos diferencia absoluta en horas para manejar correctamente el salto de día (ej. 23:30 -> 00:15)
    // Sin depender de "mismo día calendario", que rompe en la medianoche.

    // Cálculo de diferencia en minutos para mayor precisión
    const diffMs = now.getTime() - scheduledDate.getTime();
    const diffMinutes = Math.floor(diffMs / 60000); // positivo = tarde, negativo = temprano

    // Si llega mas de 60 minutos TEMPRANO (-60)
    if (diffMinutes < -60) {
        return { 
            success: false, 
            error: `Cita programada para las ${scheduledDate.toLocaleTimeString('es-MX', {hour: '2-digit', minute:'2-digit'})}. Llegaste demasiado temprano.` 
        }
    }

    // Si llega mas de 2 horas (120 min) TARDE
    if (diffMinutes > 120) {
         return { 
            success: false, 
            error: `Tu cita expiró (Máx. 2 hrs de tolerancia). Es necesario reagendar.` 
        }
    }

    // Ejecutar check-in estándar
    return await checkInAppointment(appointment.id);

  } catch (error) {
    console.error('[QR CHECK-IN ERROR]:', error)
    return { success: false, error: 'Error interno al procesar QR.' }
  }
}

/**
 * Obtiene los datos necesarios para el paso de corroboración previo al check-in.
 * Devuelve datos del trabajador y la cita sin alterar ningún estado.
 * Incluye última identidad válida del trabajador para reutilización.
 * @id IMPL-20260318-08
 * @updated IMPL-20260519-10 — campos de identidad del trabajador
 */
export async function getAppointmentForCorroboration(appointmentId: string) {
  try {
    const session = await getServerSession(authOptions)
    if (!session?.user) {
      return { success: false, error: 'No autenticado' }
    }

    const appointment = await prisma.appointment.findUnique({
      where: { id: appointmentId },
      select: {
        id: true,
        status: true,
        scheduledAt: true,
        expedientId: true,
        worker: {
          select: {
            id: true,
            firstName: true,
            lastName: true,
            universalId: true,
            phone: true,
            email: true,
            dob: true,
            companyId: true,
            jobPositionId: true,
            company: { select: { id: true, name: true } },
            jobPosition: { select: { id: true, name: true } },
            // IMPL-20260519-10: Última identificación válida para reutilización
            lastIdentityDocumentType: true,
            lastIdentityFrontFileUrl: true,
            lastIdentityBackFileUrl: true,
            lastIdentityVerifiedAt: true,
          }
        },
        company: { select: { id: true, name: true } },
        branch: { select: { id: true, name: true } },
      }
    })

    if (!appointment) {
      return { success: false, error: 'Cita no encontrada' }
    }

    return { success: true, appointment }
  } catch (error) {
    return { success: false, error: error instanceof Error ? error.message : 'Error' }
  }
}

/**
 * Obtiene todas las citas del día para todas las sucursales (vista de monitoreo multi-sucursal).
 * @id IMPL-20260318-08
 */
export async function getAppointmentsForOverview(date: string) {
  try {
    const session = await getServerSession(authOptions)
    if (!session?.user) {
      return { success: false, error: 'No autenticado' }
    }

    const targetDate = new Date(`${date}T12:00:00.000Z`)
    const startRange = new Date(targetDate)
    startRange.setDate(startRange.getDate() - 1)
    const endRange = new Date(targetDate)
    endRange.setDate(endRange.getDate() + 1)

    const appointments = await prisma.appointment.findMany({
      where: {
        scheduledAt: { gte: startRange, lte: endRange },
      },
      include: {
        worker: { select: { firstName: true, lastName: true } },
        company: { select: { name: true } },
        branch: { select: { id: true, name: true, hourlyCapacity: true, openingTime: true, closingTime: true } },
      },
      orderBy: { scheduledAt: 'asc' },
    })

    return { success: true, appointments }
  } catch (error) {
    return { success: false, error: error instanceof Error ? error.message : 'Error' }
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// IMPL-20260519-10 — Cierre orquestado de recepción (ARCH-20260519-10)
// Integra: evidencia de identidad + corrección de nombre + auditoría + check-in
// ─────────────────────────────────────────────────────────────────────────────

export interface CloseReceptionInput {
  appointmentId: string
  workerId: string
  // Corrección de nombre (opcional)
  correctedFirstName?: string
  correctedLastName?: string
  // Evidencia de identidad
  evidenceMode: IdentityEvidenceMode
  documentType?: IdentityDocumentType
  frontFileDataUrl?: string   // base64 dataURL de captura nueva
  backFileDataUrl?: string    // base64 dataURL de reverso (opcional)
  // Reutilización de evidencia previa
  reuseLastEvidence?: boolean
  // Excepción / comentario operativo (obligatorio cuando no hay captura normal)
  exceptionReason?: IdentityExceptionReason
  exceptionComment?: string
}

/**
 * Orquestador de cierre de recepción.
 * En un solo flujo transaccional:
 * 1. Valida el input
 * 2. Corrige nombre si aplica
 * 3. Persiste evidencia en la cita
 * 4. Actualiza referencia de última identidad válida en trabajador
 * 5. Registra auditoría estructurada
 * 6. Cierra el check-in (crea MedicalEvent)
 * @id IMPL-20260519-10
 * @spec context/SPECs/SPEC_ARCH-20260519-10-SPRINT1-RECEPCION-OPERATIVA.md
 */
export async function closeReceptionCorroboration(input: CloseReceptionInput) {
  try {
    const session = await getServerSession(authOptions)
    if (!session?.user) {
      return { success: false, error: 'No autenticado' }
    }

    const {
      appointmentId,
      workerId,
      correctedFirstName,
      correctedLastName,
      evidenceMode,
      documentType,
      frontFileDataUrl,
      backFileDataUrl,
      reuseLastEvidence,
      exceptionReason,
      exceptionComment,
    } = input

    // ── Validaciones de frontera ─────────────────────────────────────────────
    if (evidenceMode === 'EXCEPTION_WITHOUT_CAPTURE') {
      if (!exceptionReason) {
        return { success: false, error: 'El motivo de excepción es obligatorio cuando no hay captura normal.' }
      }
      if (!exceptionComment || exceptionComment.trim().length < 5) {
        return { success: false, error: 'El comentario operativo es obligatorio y debe tener al menos 5 caracteres.' }
      }
    }

    if (evidenceMode === 'NEW_CAPTURE' && !frontFileDataUrl) {
      return { success: false, error: 'Se requiere la evidencia frontal del documento para captura nueva.' }
    }

    if (evidenceMode === 'REUSED_PREVIOUS' && !reuseLastEvidence) {
      return { success: false, error: 'Debes confirmar la reutilización de la última evidencia válida.' }
    }

    // ── Cargar snapshot del trabajador (última identidad) ─────────────────────
    const worker = await prisma.worker.findUnique({
      where: { id: workerId },
      select: {
        firstName: true,
        lastName: true,
        lastIdentityDocumentType: true,
        lastIdentityFrontFileUrl: true,
        lastIdentityBackFileUrl: true,
      }
    })
    if (!worker) {
      return { success: false, error: 'Trabajador no encontrado.' }
    }

    // ── Determinar resultado de corroboración ────────────────────────────────
    const nameWillChange =
      (correctedFirstName && correctedFirstName.trim() !== worker.firstName) ||
      (correctedLastName && correctedLastName.trim() !== worker.lastName)

    let corroborationResult: CorroborationResult
    if (evidenceMode === 'EXCEPTION_WITHOUT_CAPTURE') {
      corroborationResult = 'VERIFIED_WITH_COMMENT'
    } else if (evidenceMode === 'REUSED_PREVIOUS') {
      corroborationResult = nameWillChange ? 'VERIFIED_WITH_NAME_CORRECTION' : 'VERIFIED_WITH_REUSED_EVIDENCE'
    } else {
      corroborationResult = nameWillChange ? 'VERIFIED_WITH_NAME_CORRECTION' : 'VERIFIED_WITHOUT_CHANGES'
    }

    // ── Resolver campos de evidencia a persistir en la cita ──────────────────
    const resolvedFront = evidenceMode === 'REUSED_PREVIOUS'
      ? (worker.lastIdentityFrontFileUrl ?? null)
      : (frontFileDataUrl ?? null)

    const resolvedBack = evidenceMode === 'REUSED_PREVIOUS'
      ? (worker.lastIdentityBackFileUrl ?? null)
      : (backFileDataUrl ?? null)

    const resolvedDocType = evidenceMode === 'REUSED_PREVIOUS'
      ? (worker.lastIdentityDocumentType ?? documentType ?? null)
      : (documentType ?? null)

    const previousName = `${worker.firstName} ${worker.lastName}`
    const newFirstName = correctedFirstName?.trim() || worker.firstName
    const newLastName = correctedLastName?.trim() || worker.lastName

    // ── Transacción principal ────────────────────────────────────────────────
    const result = await prisma.$transaction(async (tx) => {
      // 1. Corregir nombre si aplica
      if (nameWillChange) {
        await tx.worker.update({
          where: { id: workerId },
          data: { firstName: newFirstName, lastName: newLastName },
        })
      }

      // 2. Actualizar referencia de última identidad válida en trabajador
      //    Solo si hay captura nueva o reutilización (no en excepción sin captura)
      if (evidenceMode !== 'EXCEPTION_WITHOUT_CAPTURE') {
        await tx.worker.update({
          where: { id: workerId },
          data: {
            lastIdentityDocumentType: resolvedDocType,
            lastIdentityFrontFileUrl: resolvedFront,
            lastIdentityBackFileUrl: resolvedBack,
            lastIdentityVerifiedAt: new Date(),
          }
        })
      }

      // 3. Persistir evidencia en la cita
      await tx.appointment.update({
        where: { id: appointmentId },
        data: {
          identityDocumentType:     resolvedDocType,
          identityFrontFileUrl:     resolvedFront,
          identityBackFileUrl:      resolvedBack,
          identityVerifiedAt:       new Date(),
          identityVerifiedByUserId: session.user.id,
          identityExceptionReason:  exceptionReason ?? null,
          identityExceptionComment: exceptionComment ?? null,
          identityEvidenceMode:     evidenceMode,
          corroborationResult:      corroborationResult,
        }
      })

      // 4. Auditoría estructurada del cierre de recepción
      await tx.auditLog.create({
        data: {
          action: 'RECEPTION_CORROBORATION_CLOSED',
          entity: 'Appointment',
          entityId: appointmentId,
          userId: session.user.id,
          details: {
            workerId,
            evidenceMode,
            documentType: resolvedDocType,
            corroborationResult,
            hasFront: !!resolvedFront,
            hasBack: !!resolvedBack,
            nameChanged: !!nameWillChange,
            previousName: nameWillChange ? previousName : undefined,
            newName: nameWillChange ? `${newFirstName} ${newLastName}` : undefined,
            hasException: evidenceMode === 'EXCEPTION_WITHOUT_CAPTURE',
            exceptionReason: exceptionReason ?? null,
            timestamp: new Date().toISOString(),
          }
        }
      })

      return { ok: true }
    }, { maxWait: 10000, timeout: 15000 })

    if (!result.ok) {
      return { success: false, error: 'Error en la transacción de corroboración.' }
    }

    // 5. Ejecutar check-in (crea MedicalEvent) — fuera de la transacción de identidad
    const checkInResult = await checkInAppointment(appointmentId)
    if (!checkInResult.success) {
      return { success: false, error: checkInResult.error || 'Corroboración guardada, pero el check-in falló.' }
    }

    revalidatePath('/appointments')
    revalidatePath('/dashboard')

    return {
      success: true,
      medicalEvent: checkInResult.medicalEvent,
      corroborationResult,
    }
  } catch (error) {
    console.error('[CLOSE_RECEPTION_CORROBORATION ERROR]:', error)
    return {
      success: false,
      error: error instanceof Error ? error.message : 'Error al cerrar la recepción.',
    }
  }
}

'use server'

import prisma from "@/lib/prisma"
import { ClinicalHistoryDataSchema } from "@/schemas/clinical/history.schema"
import { revalidatePath } from "next/cache"
import { z } from "zod"

/**
 * IMPL-20260305-01: Obtiene el historial clínico de un trabajador
 * @param workerId - ID del trabajador
 * @returns Objeto con el historial clínico o null si no existe
 */
export async function getWorkerClinicalHistory(workerId: string) {
  try {
    if (!workerId) {
      return { success: false, error: 'ID del trabajador es obligatorio' }
    }

    const clinicalHistory = await prisma.clinicalHistory.findUnique({
      where: { workerId },
      include: {
        worker: {
          select: { id: true, firstName: true, lastName: true, universalId: true }
        }
      }
    })

    if (!clinicalHistory) {
      return { success: true, data: null, message: 'Sin historial previo' }
    }

    return {
      success: true,
      data: {
        id: clinicalHistory.id,
        workerId: clinicalHistory.workerId,
        worker: clinicalHistory.worker,
        data: clinicalHistory.data as Record<string, any>,
        lastUpdated: clinicalHistory.lastUpdated,
        updatedAt: clinicalHistory.updatedAt
      }
    }
  } catch (error) {
    console.error('Error fetching clinical history:', error)
    return { success: false, error: 'Error al obtener historial clínico' }
  }
}

/**
 * IMPL-20260305-01: Crea o actualiza el historial clínico de un trabajador
 * @param workerId - ID del trabajador
 * @param data - Datos del historial clínico (validados con Zod)
 * @returns Objeto con el historial creado/actualizado o error
 */
export async function upsertWorkerClinicalHistory(
  workerId: string,
  data: any
) {
  try {
    if (!workerId) {
      return { success: false, error: 'ID del trabajador es obligatorio' }
    }

    // Validar que el trabajador existe
    const worker = await prisma.worker.findUnique({
      where: { id: workerId }
    })

    if (!worker) {
      return { success: false, error: 'Trabajador no encontrado' }
    }

    // Validar data con esquema Zod
    const validatedData = ClinicalHistoryDataSchema.parse(data)

    // ARCH-20260326-06: Merge defensivo — no borrar secciones longitudinales no editadas
    const existingHistory = await prisma.clinicalHistory.findUnique({
      where: { workerId },
      select: { data: true },
    })
    const existingData = (existingHistory?.data as Record<string, unknown>) ?? {}
    const mergedData = { ...existingData, ...validatedData }

    // Upsert: Crear si no existe, actualizar si existe
    const clinicalHistory = await prisma.clinicalHistory.upsert({
      where: { workerId },
      create: {
        workerId,
        data: mergedData,
        lastUpdated: new Date()
      },
      update: {
        data: mergedData,
        lastUpdated: new Date()
      },
      include: {
        worker: {
          select: { id: true, firstName: true, lastName: true, universalId: true }
        }
      }
    })

    revalidatePath(`/history/${workerId}`)
    revalidatePath(`/workers/${workerId}`)

    return {
      success: true,
      data: {
        id: clinicalHistory.id,
        workerId: clinicalHistory.workerId,
        worker: clinicalHistory.worker,
        data: clinicalHistory.data,
        message: 'Historial clínico guardado exitosamente'
      }
    }
  } catch (error) {
    console.error('Error upserting clinical history:', error)

    if (error instanceof z.ZodError) {
      const messages = Object.values(error.flatten().fieldErrors)
        .flat()
        .join(', ')
      return {
        success: false,
        error: `Validación fallida: ${messages || 'Datos inválidos'}`
      }
    }

    return { success: false, error: 'Error al guardar historial clínico' }
  }
}

/**
 * @fileoverview Server Actions para gestión atómica de estudios en papeleta
 * @id IMPL-20260324-06 / IMPL-20260326-16
 * @backup context/checkpoints/CHK_IMPL-20260324-06-PAPELETA-WORKSPACE.md
 * IMPL-20260326-16: uploadEventTestFile ahora delega al flujo V2 (extracción + prediagnóstico IA)
 *   cuando el backend está disponible. Fallback a V1 si no hay conectividad.
 */
'use server'

import prisma from "@/lib/prisma"
import { revalidatePath } from "next/cache"
import { EventTestStatus } from "@prisma/client"
import { triggerStudyAIAnalysis } from "./ai-prediagnosis.actions"
import { isAIEligibleEventTest, getCanonicalAIStudyType } from "@/lib/study-ai"
// IMPL-20260507-08: Cronograma operativo persistente (ARCH-20260507-08)
import { writeTimelineEntry } from "@/lib/timeline.service"
import { TimelineEntryType } from "@prisma/client"

/**
 * @id ARCH-20260326-01
 * @backup context/checkpoints/CHK_ARCH-20260326-01.md
 */
function buildAIResultNote(input: { success: boolean; summary?: string | null; clinicalState?: string | null; error?: string | null }) {
  if (input.success) {
    const summary = input.summary?.trim()
    return summary
      ? `IA generada (${input.clinicalState ?? 'AI_PENDING_REVIEW'}): ${summary}`
      : `IA generada (${input.clinicalState ?? 'AI_PENDING_REVIEW'}).`
  }

  return `Archivo cargado, pero la IA no generó prediagnóstico: ${input.error ?? 'sin detalle'}`
}

/**
 * ARCH-20260507-06: Resuelve el grupo de muestra de un EventTest.
 * Fuente principal: test.options.sampleType (campo JSON en MedicalTest).
 * Fallback heurístico: palabras clave en testNameSnapshot.
 * Devuelve 'otro' cuando no hay grupo definido (no propagar entre estudios sin grupo).
 */
function resolveSampleGroupFromSnapshot(testNameSnapshot: string, options: unknown): string {
  if (options && typeof options === 'object' && !Array.isArray(options)) {
    const sampleType = (options as Record<string, unknown>).sampleType
    if (typeof sampleType === 'string' && sampleType.trim()) {
      return sampleType.trim().toLowerCase()
    }
  }
  const name = testNameSnapshot.toLowerCase()
  if (
    name.includes('sangre') || name.includes('sanguín') || name.includes('sanguinea') ||
    name.includes('biometría') || name.includes('biometria') ||
    name.includes('química') || name.includes('quimica') ||
    name.includes('glucosa') || name.includes('colesterol') ||
    name.includes('hemograma')
  ) return 'sangre'
  if (name.includes('orina') || name.includes('ego') || name.includes('urin')) return 'orina'
  if (name.includes('heces') || name.includes('copro')) return 'heces'
  return 'otro'
}

/**
 * IMPL-20260729-01 — Trigger automático: cuando un EventTest de categoría
 * Laboratorio pasa a SAMPLE_TAKEN, se materializa una LabOrder DRAFT con su
 * LabOrderItem, si aún no existe LabOrder para el MedicalEvent.
 *
 * Política:
 *  - Idempotente: si ya hay LabOrder para el medicalEvent, solo agrega un
 *    LabOrderItem si no existe ya ese eventTestId registrado.
 *  - Folio: max(folio) + 1 (compatible con la generación existente en
 *    lab-order.actions.ts → createLabOrderAction).
 *  - createdById: primer usuario ADMIN encontrado. Fallback: cualquier User.
 *  - doctorName: 'Dr. Sistema' como placeholder; el médico real se asigna en
 *    la admisión posterior (Slice B NOVA, ARCH-20260701-03).
 */
async function ensureLabOrderForSampledLabTest(
  eventTestId: string,
  eventId: string,
): Promise<void> {
  try {
    const eventTest = await prisma.eventTest.findUnique({
      where: { id: eventTestId },
      select: {
        testId: true,
        event: {
          select: {
            id: true,
            workerId: true,
            billingCompanyId: true,
          },
        },
        test: {
          select: {
            id: true,
            category: { select: { name: true } },
          },
        },
      },
    })

    if (!eventTest?.test?.category) return
    if (eventTest.test.category.name !== 'Laboratorio') return
    if (!eventTest.testId) return

    // Buscar o crear LabOrder para el MedicalEvent
    let labOrder = await prisma.labOrder.findFirst({
      where: { medicalEventId: eventId },
      select: { id: true },
    })

    if (!labOrder) {
      // Resolver createdById: ADMIN preferido, fallback a cualquier User
      const adminUser =
        (await prisma.user.findFirst({
          where: { role: 'ADMIN' },
          select: { id: true },
          orderBy: { createdAt: 'asc' },
        })) ??
        (await prisma.user.findFirst({
          select: { id: true },
          orderBy: { createdAt: 'asc' },
        }))

      if (!adminUser) {
        console.warn(
          '[IMPL-20260729-01] No hay usuarios en BD; no se pudo crear LabOrder automática.',
        )
        return
      }

      // Folio: max + 1
      const lastFolio = await prisma.labOrder.findFirst({
        orderBy: { folio: 'desc' },
        select: { folio: true },
      })
      const nextFolio = (lastFolio?.folio ?? 0) + 1

      const workerCompany = await prisma.worker.findUnique({
        where: { id: eventTest.event.workerId },
        select: { companyId: true },
      })

      labOrder = await prisma.labOrder.create({
        data: {
          folio: nextFolio,
          workerId: eventTest.event.workerId,
          companyId:
            eventTest.event.billingCompanyId ??
            workerCompany?.companyId ??
            null,
          medicalEventId: eventTest.event.id,
          doctorName: 'Dr. Sistema',
          createdById: adminUser.id,
          status: 'DRAFT',
        },
        select: { id: true },
      })
    }

    // Idempotencia: no duplicar LabOrderItem para el mismo eventTest
    const existingItem = await prisma.labOrderItem.findFirst({
      where: { labOrderId: labOrder.id, eventTestId },
      select: { id: true },
    })
    if (existingItem) return

    await prisma.labOrderItem.create({
      data: {
        labOrderId: labOrder.id,
        medicalTestId: eventTest.testId,
        eventTestId,
      },
    })
  } catch (err) {
    // No interrumpir el flujo clínico ante un fallo de la auto-creación.
    console.error('[IMPL-20260729-01] ensureLabOrderForSampledLabTest failed:', err)
  }
}

/**
 * Actualiza el estado operativo de un estudio en la papeleta.
 * Soporta los estados V1: PENDING, IN_PROGRESS, SAMPLE_TAKEN, RESULT_REGISTERED, COMPLETED.
 * ARCH-20260507-06: Si status === SAMPLE_TAKEN, propaga a todos los EventTest hermanos
 * del mismo grupo de muestra dentro del mismo eventId.
 */
export async function updateEventTestStatus(
  eventTestId: string,
  status: EventTestStatus,
  eventId: string
) {
  if (!eventTestId || !status || !eventId) {
    return { success: false, error: 'Parámetros incompletos' }
  }

  try {
    // IMPL-20260507-08: Leer estado previo para evitar duplicar entradas en timeline
    // cuando no hubo transición real de estado.
    const prevTest = await prisma.eventTest.findUnique({
      where: { id: eventTestId },
      select: { status: true },
    })
    const oldStatus = prevTest?.status

    await prisma.eventTest.update({
      where: { id: eventTestId },
      data: { status }
    })

    // ARCH-20260507-06: Propagar SAMPLE_TAKEN a hermanos del mismo grupo de muestra.
    // No se propaga RESULT_REGISTERED ni COMPLETED.
    if (status === 'SAMPLE_TAKEN') {
      const currentTest = await prisma.eventTest.findUnique({
        where: { id: eventTestId },
        select: {
          testNameSnapshot: true,
          test: { select: { options: true } },
        },
      })
      if (currentTest) {
        const currentGroup = resolveSampleGroupFromSnapshot(
          currentTest.testNameSnapshot,
          currentTest.test?.options,
        )
        if (currentGroup !== 'otro') {
          const siblings = await prisma.eventTest.findMany({
            where: {
              eventId,
              id: { not: eventTestId },
              status: { in: ['PENDING', 'IN_PROGRESS'] },
            },
            select: {
              id: true,
              testNameSnapshot: true,
              test: { select: { options: true } },
            },
          })
          const siblingIdsToUpdate = siblings
            .filter(
              s => resolveSampleGroupFromSnapshot(s.testNameSnapshot, s.test?.options) === currentGroup,
            )
            .map(s => s.id)
          if (siblingIdsToUpdate.length > 0) {
            await prisma.eventTest.updateMany({
              where: { id: { in: siblingIdsToUpdate } },
              data: { status: 'SAMPLE_TAKEN' },
            })
            // IMPL-20260729-01: cada hermano promovido también debe
            // materializar su LabOrderItem si es de categoría Laboratorio.
            for (const sibId of siblingIdsToUpdate) {
              await ensureLabOrderForSampledLabTest(sibId, eventId)
            }
          }
        }
      }
    }

    // IMPL-20260729-01: Si el estudio en sí es de Laboratorio, dispara la
    // materialización de LabOrder DRAFT + LabOrderItem.
    if (status === 'SAMPLE_TAKEN') {
      await ensureLabOrderForSampledLabTest(eventTestId, eventId)
    }

    // IMPL-20260507-08: Escritura automática en cronograma operativo (ARCH-20260507-08)
    // No bloqueante — nunca interrumpe el flujo clínico ante un error de timeline.
    const statusToTimelineType: Partial<Record<EventTestStatus, TimelineEntryType>> = {
      IN_PROGRESS:       'STUDY_STARTED',
      SAMPLE_TAKEN:      'SAMPLE_TAKEN',
      RESULT_REGISTERED: 'RESULT_REGISTERED',
      COMPLETED:         'STUDY_COMPLETED',
    }
    const timelineType = statusToTimelineType[status]
    if (timelineType && oldStatus !== status) {
      const testInfo = await prisma.eventTest.findUnique({
        where: { id: eventTestId },
        select: {
          testNameSnapshot: true,
          test: { select: { category: { select: { name: true } } } },
        },
      })
      const testName = testInfo?.testNameSnapshot ?? 'Estudio'
      const area = testInfo?.test?.category?.name ?? 'general'
      const titleMap: Record<TimelineEntryType, string> = {
        STUDY_STARTED:      `Estudio iniciado: ${testName}`,
        SAMPLE_TAKEN:       `Muestra tomada: ${testName}`,
        RESULT_REGISTERED:  `Resultado registrado: ${testName}`,
        STUDY_COMPLETED:    `Estudio completado: ${testName}`,
        MEDICAL_EXAM_SAVED: `Examen médico guardado`,
        ADMIN_INCIDENCE:    testName,
      }
      await writeTimelineEntry({
        eventId,
        eventTestId,
        entryType: timelineType,
        area,
        title: titleMap[timelineType],
      })
    }

    revalidatePath(`/events/${eventId}`)
    return { success: true }
  } catch (error) {
    console.error("Error updating event test status:", error)
    return { success: false, error: "Error al actualizar estado del estudio" }
  }
}

/**
 * Sube un archivo al backend Python (pipeline IA V2) y lo vincula atómicamente
 * al estudio correspondiente en la papeleta.
 * IMPL-20260326-16: Ahora usa V2 (extracción estructurada + prediagnóstico IA separado)
 * con persistencia de snapshots inmutables. Si el backend no está disponible,
 * el fallback V1 guarda el nombre del archivo como referencia.
 */
export async function uploadEventTestFile(formData: FormData) {
  const eventTestId = formData.get('eventTestId') as string
  const eventId = formData.get('eventId') as string
  const file = formData.get('file') as File
  const triggeredByUserId = (formData.get('triggeredByUserId') as string) || 'system'

  if (!eventTestId || !eventId || !file) {
    return { success: false, error: 'Faltan parámetros obligatorios' }
  }

  // IMPL-20260326-18: Verificar elegibilidad IA usando la matriz central.
  // Carga el EventTest con test/categoría desde Prisma para decisión precisa.
  let isAIEligible = false
  try {
    const eventTest = await prisma.eventTest.findUnique({
      where: { id: eventTestId },
      select: {
        testNameSnapshot: true,
        test: { select: { code: true, category: { select: { name: true } } } },
      },
    })
    if (eventTest) {
      isAIEligible = isAIEligibleEventTest(eventTest)
      if (isAIEligible) {
        const canonicalType = getCanonicalAIStudyType(eventTest)
        if (canonicalType) {
          formData.set('study_type', canonicalType)
        }
      }
    }
  } catch (eligibilityErr) {
    console.warn('[IMPL-20260326-18] No se pudo verificar elegibilidad IA, fallback V1:', eligibilityErr)
  }

  // Intentar flujo V2 con prediagnóstico IA estructurado (IMPL-20260326-16/18)
  // Solo si el estudio es elegible según la matriz canónica.
  if (isAIEligible) {
    try {
      const v2Result = await triggerStudyAIAnalysis(formData)
      if (v2Result.success) {
        await prisma.eventTest.update({
          where: { id: eventTestId },
          data: {
            resultNotes: buildAIResultNote({
              success: true,
              summary: v2Result.summary ?? null,
              clinicalState: v2Result.clinicalState ?? null,
            }),
          },
        })
        const extractionSnapshotData = v2Result.extractionSnapshotId
          ? {
              id: v2Result.extractionSnapshotId,
              version: v2Result.extractionSnapshotVersion ?? 1,
              extractedData: v2Result.extractedData ?? null,
              missingFields: v2Result.missingFields ?? null,
              rawPayload: v2Result.rawPayload ?? null,
            }
          : null
        return {
          success: true,
          fileUrl: v2Result.fileUrl ?? `/uploads/${file.name}`,
          extractionSnapshotData,
          aiAnalysis: {
            extractionSnapshotId: v2Result.extractionSnapshotId,
            prediagnosisSnapshotId: v2Result.prediagnosisSnapshotId,
            clinicalState: v2Result.clinicalState,
            summary: v2Result.summary,
            confidence: v2Result.confidence,
          },
        }
      }
      console.warn('[IMPL-20260326-16] V2 falló para estudio IA elegible; se cancela fallback V1:', v2Result.error)
      return {
        success: false,
        error: v2Result.error || 'La IA no pudo procesar el estudio en el pipeline V2.',
      }
    } catch (v2Error) {
      console.warn('[IMPL-20260326-16] Error en V2 para estudio IA elegible; se cancela fallback V1:', v2Error)
      return {
        success: false,
        error: v2Error instanceof Error ? v2Error.message : 'Error al procesar el estudio con IA.',
      }
    }
  }

  // FALLBACK V1 — FIX ARCH-20260326-04: subir físicamente al backend antes de guardar fileUrl.
  // No se genera una ruta inventada; si el upload falla, fileUrl queda null y se informa al usuario.
  try {
    const apiBase = process.env.NEXT_PUBLIC_API_URL || 'http://localhost:8000'
    const uploadForm = new FormData()
    uploadForm.append('file', file)

    let fileUrl: string | null = null
    try {
      const uploadResponse = await fetch(`${apiBase}/api/v1/upload-only`, {
        method: 'POST',
        body: uploadForm,
      })
      if (uploadResponse.ok) {
        const uploadResult = await uploadResponse.json()
        if (uploadResult?.status === 'success' && uploadResult?.file_url) {
          fileUrl = uploadResult.file_url as string
        }
      }
    } catch (uploadErr) {
      console.warn('[FIX ARCH-20260326-04] upload-only falló:', uploadErr)
    }

    const resultNotes = fileUrl
      ? buildAIResultNote({ success: false, error: 'Archivo guardado. Prediagnóstico IA no disponible; se requiere análisis manual.' })
      : buildAIResultNote({ success: false, error: 'Pipeline IA y almacenamiento no disponibles. Suba el archivo nuevamente para regenerar el análisis.' })

    await prisma.eventTest.update({
      where: { id: eventTestId },
      data: {
        ...(fileUrl ? { fileUrl } : {}),
        status: 'RESULT_REGISTERED',
        resultNotes,
      }
    })
    revalidatePath(`/events/${eventId}`)
    return fileUrl
      ? { success: true, fileUrl, aiAnalysis: null }
      : { success: false, error: 'No se pudo persistir el archivo físicamente. El pipeline IA tampoco está disponible. Intente subir el archivo nuevamente.' }
  } catch (error) {
    console.error('[FIX ARCH-20260326-04] Error en fallback V1:', error)
    return { success: false, error: 'Error al intentar guardar el archivo. Intente nuevamente.' }
  }
}


/**
 * Regenera el análisis IA de un estudio que ya tiene fileUrl pero carece de snapshots.
 * Descarga el archivo desde NEXT_PUBLIC_API_URL + fileUrl, reconstruye un File/Blob
 * y reutiliza triggerStudyAIAnalysis para persistir los snapshots de forma inmutable.
 * Si la regeneración falla, persiste el error en resultNotes.
 *
 * @id IMPL-20260326-03
 * @backup context/checkpoints/CHK_IMPL-20260326-03.md
 */
export async function regenerateStudyAI(
  eventTestId: string,
  eventId: string,
  triggeredByUserId: string = 'system'
): Promise<{ success: boolean; error?: string }> {
  if (!eventTestId || !eventId) {
    return { success: false, error: 'Parámetros incompletos' }
  }

  try {
    const eventTest = await prisma.eventTest.findUnique({
      where: { id: eventTestId },
      select: {
        fileUrl: true,
        testNameSnapshot: true,
        test: { select: { code: true, category: { select: { name: true } } } },
      },
    })

    if (!eventTest?.fileUrl) {
      return { success: false, error: 'El estudio no tiene archivo vinculado' }
    }

    // Descargar el archivo desde el storage del backend
    const apiBase = process.env.NEXT_PUBLIC_API_URL || 'http://localhost:8000'
    const fileResponse = await fetch(`${apiBase}${eventTest.fileUrl}`)
    if (!fileResponse.ok) {
      // FIX ARCH-20260326-04: 404 ocurre cuando fileUrl fue inventada en el fallback anterior.
      // Dar mensaje claro al usuario en lugar de exponer HTTP 404 internamente.
      const errMsg = fileResponse.status === 404
        ? 'El archivo del estudio ya no está disponible en el servidor. Vuelva a subir el archivo para regenerar el análisis IA.'
        : `No se pudo descargar el archivo para regenerar IA: HTTP ${fileResponse.status}`
      await prisma.eventTest.update({
        where: { id: eventTestId },
        data: { resultNotes: `Error al regenerar IA: ${errMsg}` },
      })
      revalidatePath(`/events/${eventId}`)
      return { success: false, error: errMsg }
    }

    const blob = await fileResponse.blob()
    const fileName = eventTest.fileUrl.split('/').pop() || 'study-file.pdf'
    const file = new File([blob], fileName, { type: blob.type || 'application/pdf' })

    // Determinar tipo canónico para el backend V2
    const canonicalType = getCanonicalAIStudyType(eventTest)

    const formData = new FormData()
    formData.set('eventTestId', eventTestId)
    formData.set('eventId', eventId)
    formData.set('file', file)
    formData.set('triggeredByUserId', triggeredByUserId)
    if (canonicalType) {
      formData.set('study_type', canonicalType)
    }

    const aiResult = await triggerStudyAIAnalysis(formData)

    // ARCH-20260326-05: Si IA no está disponible, consultar /api/v2/ai/status para causa raíz exacta.
    let enrichedError = aiResult.error ?? null
    if (!aiResult.success && aiResult.error?.includes('Servicios de IA no están disponibles')) {
      try {
        const statusResp = await fetch(`${apiBase}/api/v2/ai/status`)
        if (statusResp.ok) {
          const aiStatus = await statusResp.json() as {
            api_key_present: boolean
            last_init_error?: string | null
            classifier: boolean
            extractor: boolean
            prediagnostic: boolean
          }
          const parts: string[] = []
          if (!aiStatus.api_key_present) parts.push('GEMINI_API_KEY ausente')
          if (aiStatus.last_init_error) parts.push(aiStatus.last_init_error)
          if (!aiStatus.classifier) parts.push('classifier no inicializado')
          else if (!aiStatus.extractor) parts.push('extractor no inicializado')
          else if (!aiStatus.prediagnostic) parts.push('prediagnostic no inicializado')
          if (parts.length > 0) {
            enrichedError = `Servicios de IA no están disponibles: ${parts.join('; ')}`
          }
        }
      } catch {
        // Mantener error original si /api/v2/ai/status no está accesible
      }
    }

    // Persistir resultNotes según el resultado de la regeneración
    const resultNotes = buildAIResultNote({
      success: aiResult.success,
      summary: aiResult.summary ?? null,
      clinicalState: aiResult.clinicalState ?? null,
      error: enrichedError,
    })
    await prisma.eventTest.update({
      where: { id: eventTestId },
      data: { resultNotes },
    })

    revalidatePath(`/events/${eventId}`)
    return { success: aiResult.success, error: enrichedError ?? undefined }
  } catch (error) {
    const msg = error instanceof Error ? error.message : 'Error interno al regenerar IA'
    console.error('[IMPL-20260326-03] Error en regenerateStudyAI:', error)
    try {
      await prisma.eventTest.update({
        where: { id: eventTestId },
        data: { resultNotes: `Error al regenerar IA: ${msg}` },
      })
      revalidatePath(`/events/${eventId}`)
    } catch (_persistErr) {
      // No interrumpir si falla la persistencia del error
    }
    return { success: false, error: msg }
  }
}

/**
 * ARCH-20260518-04: Limpia el archivo activo y los snapshots vigentes de un estudio,
 * dejándolo en estado PENDING listo para nueva captura.
 *
 * Política de auditoría:
 *   - Los StudyExtractionSnapshot y AIPrediagnosisSnapshot previos se marcan isSuperseded=true.
 *   - NO se hace hard delete. El historial queda trazable internamente.
 *   - El EventTest queda con fileUrl=null, status=PENDING y resultNotes de auditoría.
 *
 * @id ARCH-20260518-04
 * @backup context/checkpoints/CHK_IMPL-20260518-04-DOBLE-FLUJO-ARCHIVO-IA.md
 */
export async function clearEventTestFile(
  eventTestId: string,
  eventId: string,
  clearedByUserId: string = 'system'
): Promise<{ success: boolean; error?: string }> {
  if (!eventTestId || !eventId) {
    return { success: false, error: 'Parámetros incompletos' }
  }

  try {
    // 1. Buscar snapshots activos (no superseded) para marcarlos históricos
    const activeExtractions = await prisma.studyExtractionSnapshot.findMany({
      where: { eventTestId, isSuperseded: false },
      select: { id: true },
    })

    if (activeExtractions.length > 0) {
      const extractionIds = activeExtractions.map((s) => s.id)

      // Marcar extracciones como superseded (semántica de "vigente eliminado")
      await prisma.studyExtractionSnapshot.updateMany({
        where: { id: { in: extractionIds } },
        data: { isSuperseded: true },
      })

      // Marcar prediagnósticos asociados como superseded
      await prisma.aIPrediagnosisSnapshot.updateMany({
        where: { extractionSnapshotId: { in: extractionIds } },
        data: { isSuperseded: true },
      })
    }

    // 2. Limpiar el EventTest operativo
    const auditNote = `[ARCH-20260518-04] Estudio limpiado para nueva captura por ${clearedByUserId} el ${new Date().toISOString()}. Historial previo conservado con isSuperseded=true (${activeExtractions.length} snapshots).`
    await prisma.eventTest.update({
      where: { id: eventTestId },
      data: {
        fileUrl: null,
        status: 'PENDING',
        resultNotes: auditNote,
      },
    })

    revalidatePath(`/events/${eventId}`)
    return { success: true }
  } catch (error) {
    console.error('[ARCH-20260518-04] Error en clearEventTestFile:', error)
    return {
      success: false,
      error: error instanceof Error ? error.message : 'Error interno al limpiar el estudio',
    }
  }
}

/**
 * @file Server Actions para Fase 3 NOVA — G Caja, Cortesías y corte de caja.
 * @id IMPL-20260708-19
 * @backup context/SPECs/SPEC_IMPL-20260707-SLICES-D-G-FINAL.md §2 (FASE 3)
 *
 * Mismo patrón que lab-trace.actions.ts:
 *  - Validación Zod server-side
 *  - Rol permitido: ADMIN, RECEPTIONIST, CAPTURIST
 *  - revalidatePath tras mutaciones
 *  - Prisma directo (no fetch al backend FastAPI)
 */
"use server";

import { revalidatePath } from "next/cache";
import { getServerSession } from "next-auth/next";
import { authOptions } from "@/auth";
import prisma from "@/lib/prisma";
import {
  markCourtesySchema,
  registerPaymentSchema,
  cashClosingQuerySchema,
  type RegisterPaymentInput,
  type MarkCourtesyInput,
  type PaymentMethod,
} from "@/lib/validations/lab-cash";

// ---------------------------------------------------------------------------
// Tipos
// ---------------------------------------------------------------------------
type ActionResult<T> =
  | { ok: true; data: T }
  | { ok: false; error: string; code?: string };

export interface CashPaymentRow {
  id: string;
  labOrderId: string;
  amount: number;
  method: PaymentMethod | string;
  reference: string | null;
  currency: string;
  userId: string;
  userFullName: string | null;
  createdAt: string;
}

export interface CashPaymentsSummary {
  labOrderId: string;
  total: number;
  rows: CashPaymentRow[];
  paidTotal: number;
  orderTotal: number;
  balance: number;
}

export interface CourtesyRow {
  id: string;
  labOrderId: string;
  reason: string;
  approvedById: string;
  approvedByFullName: string | null;
  createdAt: string;
}

export interface CashClosingMethodTotal {
  method: PaymentMethod;
  count: number;
  total: number;
}

export interface CashClosingReport {
  dateFrom: string;
  dateTo: string;
  totalOrders: number;
  courtesyOrders: number;
  billedOrders: number;
  totalBilled: number;
  totalCollected: number;
  balancePending: number;
  byMethod: CashClosingMethodTotal[];
  paymentsCount: number;
  generatedAt: string;
}

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------
async function _requireStaff(): Promise<{ userId: string } | null> {
  try {
    const session = await getServerSession(authOptions);
    if (!session?.user?.id) return null;
    const role = session.user.role;
    if (!["ADMIN", "RECEPTIONIST", "CAPTURIST"].includes(role)) return null;
    return { userId: session.user.id };
  } catch (err) {
    // eslint-disable-next-line no-console
    console.error("[lab-cash actions] session error:", err);
    return null;
  }
}

function _err(error: unknown): ActionResult<never> {
  return {
    ok: false,
    error: error instanceof Error ? error.message : "Error desconocido",
  };
}

// ---------------------------------------------------------------------------
// 1) Registrar pago (POST /lab/orders/{id}/payments)
// ---------------------------------------------------------------------------
export async function registerLabPaymentAction(
  orderId: string,
  input: RegisterPaymentInput
): Promise<ActionResult<CashPaymentRow>> {
  const guard = await _requireStaff();
  if (!guard) return { ok: false, error: "UNAUTHORIZED", code: "AUTH" };
  if (!orderId) return { ok: false, error: "orderId obligatorio", code: "VALIDATION" };

  const parsed = registerPaymentSchema.safeParse(input);
  if (!parsed.success) {
    return {
      ok: false,
      error: `Validación Zod: ${parsed.error.issues.map((i) => `${i.path.join(".")}: ${i.message}`).join("; ")}`,
      code: "VALIDATION",
    };
  }

  try {
    const order = await prisma.labOrder.findUnique({ where: { id: orderId }, select: { id: true } });
    if (!order) return { ok: false, error: `LabOrder ${orderId} no existe`, code: "NOT_FOUND" };

    const created = await prisma.labCashMovement.create({
      data: {
        labOrderId: orderId,
        amount: parsed.data.amount,
        method: parsed.data.method,
        reference: parsed.data.reference ?? null,
        currency: parsed.data.currency ?? "MXN",
        userId: guard.userId,
      },
      include: { user: { select: { fullName: true } } },
    });

    revalidatePath(`/lab/results/${orderId}`);
    revalidatePath("/lab/cash");
    revalidatePath("/lab/cash-closing");

    return {
      ok: true,
      data: {
        id: created.id,
        labOrderId: created.labOrderId,
        amount: Number(created.amount),
        method: created.method as PaymentMethod,
        reference: created.reference,
        currency: created.currency,
        userId: created.userId,
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        userFullName: (created as any).user?.fullName ?? null,
        createdAt:
          created.createdAt instanceof Date
            ? created.createdAt.toISOString()
            : String(created.createdAt),
      },
    };
  } catch (err) {
    return _err(err);
  }
}

// ---------------------------------------------------------------------------
// 2) Listar pagos de una orden (GET /lab/orders/{id}/payments)
// ---------------------------------------------------------------------------
export async function getLabPaymentsAction(
  orderId: string
): Promise<ActionResult<CashPaymentsSummary>> {
  const guard = await _requireStaff();
  if (!guard) return { ok: false, error: "UNAUTHORIZED", code: "AUTH" };
  if (!orderId) return { ok: false, error: "orderId obligatorio", code: "VALIDATION" };

  try {
    const order = await prisma.labOrder.findUnique({
      where: { id: orderId },
      select: { id: true, total: true },
    });
    if (!order) return { ok: false, error: `LabOrder ${orderId} no existe`, code: "NOT_FOUND" };

    const rows = await prisma.labCashMovement.findMany({
      where: { labOrderId: orderId },
      include: { user: { select: { fullName: true } } },
      orderBy: { createdAt: "asc" },
    });

    const cashRows: CashPaymentRow[] = rows.map((r) => ({
      id: r.id,
      labOrderId: r.labOrderId,
      amount: Number(r.amount),
      method: r.method as PaymentMethod,
      reference: r.reference,
      currency: r.currency,
      userId: r.userId,
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      userFullName: (r as any).user?.fullName ?? null,
      createdAt: r.createdAt instanceof Date ? r.createdAt.toISOString() : String(r.createdAt),
    }));
    const paidTotal = cashRows.reduce((sum, r) => sum + r.amount, 0);
    const orderTotal = Number(order.total);
    return {
      ok: true,
      data: {
        labOrderId: orderId,
        total: cashRows.length,
        rows: cashRows,
        paidTotal: Math.round(paidTotal * 100) / 100,
        orderTotal: Math.round(orderTotal * 100) / 100,
        balance: Math.round(Math.max(0, orderTotal - paidTotal) * 100) / 100,
      },
    };
  } catch (err) {
    return _err(err);
  }
}

// ---------------------------------------------------------------------------
// 3) Marcar como cortesía (POST /lab/orders/{id}/courtesy)
// ---------------------------------------------------------------------------
export async function markLabCourtesyAction(
  orderId: string,
  input: MarkCourtesyInput
): Promise<ActionResult<CourtesyRow>> {
  const guard = await _requireStaff();
  if (!guard) return { ok: false, error: "UNAUTHORIZED", code: "AUTH" };
  if (!orderId) return { ok: false, error: "orderId obligatorio", code: "VALIDATION" };

  const parsed = markCourtesySchema.safeParse(input);
  if (!parsed.success) {
    return {
      ok: false,
      error: `Validación Zod: ${parsed.error.issues.map((i) => `${i.path.join(".")}: ${i.message}`).join("; ")}`,
      code: "VALIDATION",
    };
  }

  try {
    const order = await prisma.labOrder.findUnique({ where: { id: orderId }, select: { id: true } });
    if (!order) return { ok: false, error: `LabOrder ${orderId} no existe`, code: "NOT_FOUND" };

    // Idempotente
    const existing = await prisma.courtesy.findUnique({ where: { labOrderId: orderId } });
    if (existing) {
      return {
        ok: true,
        data: {
          id: existing.id,
          labOrderId: existing.labOrderId,
          reason: existing.reason,
          approvedById: existing.approvedById,
          approvedByFullName: null,
          createdAt:
            existing.createdAt instanceof Date
              ? existing.createdAt.toISOString()
              : String(existing.createdAt),
        },
      };
    }

    const created = await prisma.courtesy.create({
      data: {
        labOrderId: orderId,
        reason: parsed.data.reason,
        approvedById: guard.userId,
      },
      include: { approvedBy: { select: { fullName: true } } },
    });

    // Marcar la LabOrder como cortesía (no borramos cashMovements)
    try {
      await prisma.labOrder.update({
        where: { id: orderId },
        data: { isCourtesy: true, courtesyType: parsed.data.reason.slice(0, 200) },
      });
    } catch {
      // No romper el flujo principal
    }

    revalidatePath(`/lab/results/${orderId}`);
    revalidatePath("/lab/cash");
    revalidatePath("/lab/cash-closing");

    return {
      ok: true,
      data: {
        id: created.id,
        labOrderId: created.labOrderId,
        reason: created.reason,
        approvedById: created.approvedById,
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        approvedByFullName: (created as any).approvedBy?.fullName ?? null,
        createdAt:
          created.createdAt instanceof Date
            ? created.createdAt.toISOString()
            : String(created.createdAt),
      },
    };
  } catch (err) {
    return _err(err);
  }
}

// ---------------------------------------------------------------------------
