    if (searchValue.trim()) {
      where.OR = [
        { folio: { equals: isNaN(Number(searchValue)) ? -1 : Number(searchValue) } },
        { doctorName: { contains: searchValue, mode: "insensitive" } },
        { novaFolio: { contains: searchValue, mode: "insensitive" } },
