// ---------------------------------------------------------------------------
// 8) getLabResultsForEventTestAction — Fase 2 — C-update
// Lista todos los LabResults vinculados a un EventTest específico
// (vía LabResult.eventTestId). Usado por el componente LabResultsSummary
// en /events/[id] para mostrar el valor del analito capturado por cada
// EventTest de categoría Laboratorio.
// ---------------------------------------------------------------------------
export interface LabResultForEventTest {
  id: string;
  labOrderItemId: string;
  labOrderId: string | null;
  labOrderFolio: number | null;
  analyteCode: string;
  analyteName: string;
  valueText: string | null;
  valueNumber: number | null;
  unitSymbol: string | null;
  status: string;
  isOutOfRange: boolean;
  isCritical: boolean;
  createdAt: string;
}

export async function getLabResultsForEventTestAction(
  eventTestId: string
): Promise<ActionResult<{ rows: LabResultForEventTest[]; total: number }>> {
  const guard = await _requireAdmin();
  if (!guard) return { ok: false, error: "UNAUTHORIZED", code: "AUTH" };
  if (!eventTestId) {
    return { ok: false, error: "eventTestId obligatorio", code: "VALIDATION" };
  }
  try {
    const et = await prisma.eventTest.findUnique({
      where: { id: eventTestId },
      select: { id: true },
    });
    if (!et) {
      return { ok: false, error: `EventTest ${eventTestId} no existe`, code: "NOT_FOUND" };
    }
    const rows = await prisma.labResult.findMany({
      where: { eventTestId },
      orderBy: { createdAt: "desc" },
      include: {
        analyte: { select: { code: true, name: true } },
        unit: { select: { symbol: true } },
        labOrderItem: {
          select: {
            id: true,
            labOrder: { select: { id: true, folio: true } },
          },
        },
      },
    });
    const mapped: LabResultForEventTest[] = rows.map((r) => ({
      id: r.id,
      labOrderItemId: r.labOrderItemId,
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      labOrderId: (r as any).labOrderItem?.labOrder?.id ?? null,
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      labOrderFolio: (r as any).labOrderItem?.labOrder?.folio ?? null,
      analyteCode: r.analyte?.code ?? "—",
      analyteName: r.analyte?.name ?? "",
      valueText: r.valueText,
      valueNumber: r.valueNumber,
      unitSymbol: r.unit?.symbol ?? null,
      status: String(r.status),
      isOutOfRange: r.isOutOfRange,
      isCritical: r.isCritical,
      createdAt: r.createdAt instanceof Date ? r.createdAt.toISOString() : String(r.createdAt),
    }));
    return { ok: true, data: { rows: mapped, total: mapped.length } };
  } catch (err) {
    return _err(err);
  }
}

/**
 * @file Server Actions para LabTraceEvent (Fase 2 NOVA absorción — D Trazabilidad).
 * @id IMPL-20260707-18
 * @backup context/SPECs/SPEC_IMPL-20260707-SLICES-D-G-FINAL.md §2 (FASE 2)
 *
 * Mismo patrón que el resto de la familia lab_*:
 *  - Validación Zod server-side
 *  - Rol permitido: ADMIN
 *  - revalidatePath tras mutaciones
 *  - Prisma directo (no fetch al backend FastAPI)
 */
"use server";

import { revalidatePath } from "next/cache";
import { getServerSession } from "next-auth/next";
import { authOptions } from "@/auth";
import prisma from "@/lib/prisma";
import { recordTraceEventSchema, type RecordTraceEventInput, type LabTraceEventType } from "@/lib/validations/lab-trace";

// ---------------------------------------------------------------------------
// Tipos
// ---------------------------------------------------------------------------
type ActionResult<T> =
  | { ok: true; data: T }
  | { ok: false; error: string; code?: string };

export interface LabTraceEventRow {
  id: string;
  labOrderId: string;
  event: LabTraceEventType | string;
  timestamp: string;
  userId: string | null;
  userFullName: string | null;
  notes: string | null;
  location: string | null;
}

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------
async function _requireAdmin(): Promise<{ userId: string } | null> {
  try {
    const session = await getServerSession(authOptions);
    if (!session?.user?.id) return null;
    if (session.user.role !== "ADMIN") return null;
    return { userId: session.user.id };
  } catch (err) {
    // eslint-disable-next-line no-console
    console.error("[lab-trace actions] session error:", err);
    return null;
  }
}

function _err(error: unknown): ActionResult<never> {
  return {
    ok: false,
    error: error instanceof Error ? error.message : "Error desconocido",
  };
}

// ---------------------------------------------------------------------------
// 1) GET timeline de una LabOrder
// ---------------------------------------------------------------------------
export async function getLabTraceAction(
  orderId: string
): Promise<ActionResult<{ labOrderId: string; total: number; rows: LabTraceEventRow[] }>> {
  const guard = await _requireAdmin();
  if (!guard) return { ok: false, error: "UNAUTHORIZED", code: "AUTH" };
  if (!orderId) return { ok: false, error: "orderId obligatorio", code: "VALIDATION" };

  try {
    const order = await prisma.labOrder.findUnique({ where: { id: orderId }, select: { id: true } });
    if (!order) return { ok: false, error: `LabOrder ${orderId} no existe`, code: "NOT_FOUND" };

    const events = await prisma.labTraceEvent.findMany({
      where: { labOrderId: orderId },
      include: { user: { select: { fullName: true } } },
      orderBy: { timestamp: "asc" },
    });

    const rows: LabTraceEventRow[] = events.map((e) => ({
      id: e.id,
      labOrderId: e.labOrderId,
      event: e.event,
      timestamp: (e.timestamp instanceof Date ? e.timestamp.toISOString() : String(e.timestamp)),
      userId: e.userId,
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      userFullName: (e as any).user?.fullName ?? null,
      notes: e.notes,
      location: e.location,
    }));
    return { ok: true, data: { labOrderId: orderId, total: rows.length, rows } };
  } catch (err) {
    return _err(err);
  }
}

// ---------------------------------------------------------------------------
// 2) POST evento manual
// ---------------------------------------------------------------------------
export async function recordLabTraceEventAction(
  orderId: string,
  input: RecordTraceEventInput
): Promise<ActionResult<LabTraceEventRow>> {
  const guard = await _requireAdmin();
  if (!guard) return { ok: false, error: "UNAUTHORIZED", code: "AUTH" };
  if (!orderId) return { ok: false, error: "orderId obligatorio", code: "VALIDATION" };

  const parsed = recordTraceEventSchema.safeParse(input);
  if (!parsed.success) {
    return {
      ok: false,
      error: `Validación Zod: ${parsed.error.issues.map((i) => `${i.path.join(".")}: ${i.message}`).join("; ")}`,
      code: "VALIDATION",
    };
  }

  try {
    const order = await prisma.labOrder.findUnique({ where: { id: orderId }, select: { id: true } });
    if (!order) return { ok: false, error: `LabOrder ${orderId} no existe`, code: "NOT_FOUND" };

    const created = await prisma.labTraceEvent.create({
      data: {
        labOrderId: orderId,
        event: parsed.data.event,
        notes: parsed.data.notes ?? null,
        location: parsed.data.location ?? null,
        userId: guard.userId,
      },
      include: { user: { select: { fullName: true } } },
    });

    revalidatePath(`/lab/results/${orderId}`);
    revalidatePath("/lab/results");

    return {
      ok: true,
      data: {
        id: created.id,
        labOrderId: created.labOrderId,
        event: created.event,
        timestamp:
          created.timestamp instanceof Date
            ? created.timestamp.toISOString()
            : String(created.timestamp),
        userId: created.userId,
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        userFullName: (created as any).user?.fullName ?? null,
        notes: created.notes,
        location: created.location,
      },
    };
  } catch (err) {
    return _err(err);
  }
}

// ---------------------------------------------------------------------------
// 3) Auto-record lifecycle (idempotente, helper interno)
//    - SAMPLE_RECEIVED al confirmar LabOrder (DRAFT → SAVED)
//    - VALIDATED al pasar un LabResult a VALIDATED
//    No falla si ya existe un evento del mismo tipo (idempotente).
// ---------------------------------------------------------------------------
export async function autoRecordLabTraceEventAction(
  orderId: string,
  event: LabTraceEventType,
  notes?: string | null
): Promise<{ ok: boolean; created: boolean; reason?: string }> {
  if (!orderId || !event) return { ok: false, created: false, reason: "missing_args" };
  try {
    const order = await prisma.labOrder.findUnique({ where: { id: orderId }, select: { id: true } });
    if (!order) return { ok: false, created: false, reason: "order_not_found" };

    // Idempotencia: si ya hay un evento del mismo tipo para esta orden, no duplicar.
    const existing = await prisma.labTraceEvent.findFirst({
      where: { labOrderId: orderId, event },
    });
    if (existing) return { ok: true, created: false };

    // El userId lo dejamos null en auto-record para no asumir sesión; el caller
    // (server action que confirma la orden o valida un resultado) ya pasó por
    // la guarda de ADMIN y registra el userId explícito en el endpoint manual
    // cuando aplica. Aquí priorizamos robustez: que NUNCA rompa el flujo.
    await prisma.labTraceEvent.create({
      data: {
        labOrderId: orderId,
        event,
        notes: notes ?? null,
        location: null,
        userId: null,
      },
    });
    revalidatePath(`/lab/results/${orderId}`);
    return { ok: true, created: true };
  } catch (err) {
    // Nunca romper el flujo principal por un fallo en el trace
    // eslint-disable-next-line no-console
    console.error("[autoRecordLabTraceEventAction] error:", err);
    return { ok: false, created: false, reason: err instanceof Error ? err.message : "unknown" };
  }
}

/**
 * Server Actions para MaintenanceRecord — IMPL-20260711-01
 * @id IMPL-20260711-01
 * @spec context/SPECs/SPEC_ARCH-20260711-01-MODULO-UNIDADES-MOVILES.md
 * @backup context/interconsultas/HANDOFF_ARCH-20260711-01_SOFIA_UNIDADES-MOVILES.md
 *
 * Reglas de negocio:
 *   - §3.1: una unidad no puede tener proyecto + mantenimiento PROGRAMADO en la misma fecha.
 *   - §3.2: reprogramar mantiene original + crea nuevo registro (status REPROGRAMADO).
 *   - §3.2: al completar, nextDueDate auto-calculado por tipo: PREVENTIVO +90d, VERIFICACION +365d,
 *           LIMPIEZA +30d, CORRECTIVO none.
 *   - §3.5: solo ADMIN crea/edita. Lectura a todos los autenticados.
 */
'use server'

import { z } from 'zod'
import { revalidatePath } from 'next/cache'
import { getServerSession } from 'next-auth/next'
import { Prisma } from '@prisma/client'
import { authOptions } from '@/auth'
import prisma from '@/lib/prisma'

// ─── Schemas ──────────────────────────────────────────────────────────────────

const TYPE_VALUES = ['PREVENTIVO', 'CORRECTIVO', 'VERIFICACION', 'LIMPIEZA'] as const
const STATUS_VALUES = ['PROGRAMADO', 'COMPLETADO', 'CANCELADO', 'REPROGRAMADO'] as const

const CreateMaintenanceSchema = z.object({
  mobileUnitId: z.string().min(1),
  type: z.enum(TYPE_VALUES),
  scheduledDate: z.string().datetime(),
  description: z.string().min(1).max(2000),
  technician: z.string().max(200).optional(),
  cost: z.number().min(0).optional(),
  nextDueDate: z.string().datetime().optional(),
  attachments: z.array(z.object({
    url: z.string(),
    type: z.string(),
    uploadedAt: z.string().datetime(),
  })).optional(),
})

const UpdateMaintenanceSchema = z.object({
  type: z.enum(TYPE_VALUES).optional(),
  scheduledDate: z.string().datetime().optional(),
  description: z.string().min(1).max(2000).optional(),
  technician: z.string().max(200).optional(),
  cost: z.number().min(0).optional(),
  nextDueDate: z.string().datetime().optional().nullable(),
})

const CompleteMaintenanceSchema = z.object({
  completedDate: z.string().datetime(),
  cost: z.number().min(0),
  attachments: z.array(z.object({
    url: z.string(),
    type: z.string(),
    uploadedAt: z.string().datetime(),
  })).optional(),
  notes: z.string().max(2000).optional(),
})

// ─── Helpers de auth ─────────────────────────────────────────────────────────

async function requireAdmin() {
  const session = await getServerSession(authOptions)
  if (!session || session.user.role !== 'ADMIN') return null
  return session
}

async function requireAnyAuth() {
  const session = await getServerSession(authOptions)
  if (!session) return null
  return session
}

// SPEC §3.2 — auto nextDueDate por tipo (helper síncrono, NO es server action)
function calculateNextDueDate(
  completedDate: Date,
  type: (typeof TYPE_VALUES)[number],
  override?: Date | null
): Date | null {
  // override explícito (no undefined) gana incluso cuando es null (significa
  // "sé que no aplica, no quiero auto").
  if (override !== undefined) return override
  switch (type) {
    case 'PREVENTIVO':
      return new Date(completedDate.getTime() + 90 * 86400_000)
    case 'VERIFICACION':
      return new Date(completedDate.getTime() + 365 * 86400_000)
    case 'LIMPIEZA':
      return new Date(completedDate.getTime() + 30 * 86400_000)
    case 'CORRECTIVO':
      return null
  }
}

// ─── Queries ──────────────────────────────────────────────────────────────────

export async function getMaintenanceRecords(
  mobileUnitId: string,
  status?: (typeof STATUS_VALUES)[number]
) {
  const session = await requireAnyAuth()
  if (!session) return []

  return prisma.maintenanceRecord.findMany({
    where: {
      mobileUnitId,
      ...(status ? { status } : {}),
    },
    orderBy: { scheduledDate: 'desc' },
  })
}

// ─── Mutaciones ───────────────────────────────────────────────────────────────

export async function createMaintenanceRecord(
  data: z.infer<typeof CreateMaintenanceSchema>
) {
  const session = await requireAdmin()
  if (!session) return { success: false as const, error: 'No autorizado' }

  const parsed = CreateMaintenanceSchema.safeParse(data)
  if (!parsed.success) {
    return { success: false as const, error: parsed.error.issues[0]?.message ?? 'Datos inválidos' }
  }

  const unit = await prisma.mobileUnit.findUnique({ where: { id: parsed.data.mobileUnitId } })
  if (!unit) return { success: false as const, error: 'Unidad no encontrada' }

  // SPEC §3.1 — validar disponibilidad
  const scheduled = new Date(parsed.data.scheduledDate)
  const conflict = await checkMaintenanceConflicts(parsed.data.mobileUnitId, scheduled)
  if (!conflict.available) {
    const suggestions = conflict.suggestions.map((s) => s.label).join(', ')
    return {
      success: false as const,
      error: `La unidad tiene proyecto el ${scheduled.toISOString().slice(0, 10)}. Alternativas: ${suggestions || ' ninguna en 21 días'}`,
    }
  }

  try {
    const record = await prisma.maintenanceRecord.create({
      data: {
        mobileUnitId: parsed.data.mobileUnitId,
        type: parsed.data.type,
        status: 'PROGRAMADO',
        scheduledDate: scheduled,
        description: parsed.data.description,
        technician: parsed.data.technician ?? null,
        cost: parsed.data.cost ?? null,
        nextDueDate: parsed.data.nextDueDate ? new Date(parsed.data.nextDueDate) : null,
        attachments: parsed.data.attachments
          ? (parsed.data.attachments as unknown as Prisma.InputJsonValue)
          : Prisma.JsonNull,
        createdBy: session.user.id,
      },
    })
    revalidatePath(`/admin/mobile-units/${parsed.data.mobileUnitId}/maintenance`)
    revalidatePath('/admin/mobile-units')
    return { success: true as const, record }
  } catch (e: unknown) {
    const err = e as Error
    console.error('[createMaintenanceRecord]', err.message)
    return { success: false as const, error: 'Error al crear el mantenimiento' }
  }
}

export async function updateMaintenanceRecord(
  recordId: string,
  data: z.infer<typeof UpdateMaintenanceSchema>
) {
  const session = await requireAdmin()
  if (!session) return { success: false as const, error: 'No autorizado' }

  const parsed = UpdateMaintenanceSchema.safeParse(data)
  if (!parsed.success) {
    return { success: false as const, error: parsed.error.issues[0]?.message ?? 'Datos inválidos' }
  }

  try {
    const existing = await prisma.maintenanceRecord.findUnique({ where: { id: recordId } })
    if (!existing) return { success: false as const, error: 'Mantenimiento no encontrado' }

    const updateData: Prisma.MaintenanceRecordUpdateInput = {}
    if (parsed.data.type !== undefined) updateData.type = parsed.data.type
    if (parsed.data.description !== undefined) updateData.description = parsed.data.description
    if (parsed.data.technician !== undefined) updateData.technician = parsed.data.technician
    if (parsed.data.cost !== undefined) updateData.cost = parsed.data.cost
    if (parsed.data.scheduledDate !== undefined) {
      updateData.scheduledDate = new Date(parsed.data.scheduledDate)
    }
    if (parsed.data.nextDueDate !== undefined) {
      updateData.nextDueDate = parsed.data.nextDueDate ? new Date(parsed.data.nextDueDate) : null
    }

    await prisma.maintenanceRecord.update({ where: { id: recordId }, data: updateData })
    revalidatePath(`/admin/mobile-units/${existing.mobileUnitId}/maintenance`)
    return { success: true as const }
  } catch (e: unknown) {
    const err = e as Error
    console.error('[updateMaintenanceRecord]', err.message)
    return { success: false as const, error: 'Error al actualizar el mantenimiento' }
  }
}

/**
 * SPEC §3.2 / §4.2 — reprograma un mantenimiento:
 *   1. Marca el original como REPROGRAMADO (con rescheduledTo).
 *   2. Crea un NUEVO MaintenanceRecord con la nueva fecha (linked al original vía description).
 *   3. Si la nueva fecha también tiene conflicto, rechaza y devuelve alternativas.
 */
export async function reprogramMaintenance(
  recordId: string,
  newDate: string,
  reason?: string
) {
  const session = await requireAdmin()
  if (!session) return { success: false as const, error: 'No autorizado' }

  const newDateObj = new Date(newDate)
  if (Number.isNaN(newDateObj.getTime())) {
    return { success: false as const, error: 'Fecha inválida' }
  }

  try {
    const original = await prisma.maintenanceRecord.findUnique({ where: { id: recordId } })
    if (!original) return { success: false as const, error: 'Mantenimiento no encontrado' }

    // Validar la nueva fecha
    const conflict = await checkMaintenanceConflicts(original.mobileUnitId, newDateObj)
    if (!conflict.available) {
      return {
        success: false as const,
        error: `La nueva fecha (${newDateObj.toISOString().slice(0, 10)}) también tiene conflicto. Alternativas: ${conflict.suggestions.map((s) => s.label).join(', ') || ' ninguna'}`,
      }
    }

    const suffix = `\n[REPROGRAMADO ${new Date().toISOString().slice(0, 10)} → ${newDateObj.toISOString().slice(0, 10)}]` +
      (reason ? ` — ${reason}` : '')

    await prisma.$transaction([
      prisma.maintenanceRecord.update({
        where: { id: recordId },
        data: {
          status: 'REPROGRAMADO',
          rescheduledTo: newDateObj,
          description: (original.description ?? '') + suffix,
        },
      }),
      prisma.maintenanceRecord.create({
        data: {
          mobileUnitId: original.mobileUnitId,
          type: original.type,
          status: 'PROGRAMADO',
          scheduledDate: newDateObj,
          description: (original.description ?? '') + suffix,
          technician: original.technician,
          cost: original.cost,
          nextDueDate: original.nextDueDate,
          createdBy: original.createdBy,
        },
      }),
    ])

    revalidatePath(`/admin/mobile-units/${original.mobileUnitId}/maintenance`)
    return { success: true as const }
  } catch (e: unknown) {
    const err = e as Error
    console.error('[reprogramMaintenance]', err.message)
    return { success: false as const, error: 'Error al reprogramar el mantenimiento' }
  }
}

/**
 * SPEC §3.2 / §4.2 — completa el mantenimiento:
 *   - status = COMPLETADO
 *   - completedDate y completedBy se guardan
 *   - nextDueDate auto-calculado (PREVENTIVO +90d, VERIFICACION +365d, LIMPIEZA +30d, CORRECTIVO null)
 */
export async function completeMaintenance(
  recordId: string,
  data: z.infer<typeof CompleteMaintenanceSchema>
) {
  const session = await requireAdmin()
  if (!session) return { success: false as const, error: 'No autorizado' }

  const parsed = CompleteMaintenanceSchema.safeParse(data)
  if (!parsed.success) {
    return { success: false as const, error: parsed.error.issues[0]?.message ?? 'Datos inválidos' }
  }

  try {
    const existing = await prisma.maintenanceRecord.findUnique({ where: { id: recordId } })
    if (!existing) return { success: false as const, error: 'Mantenimiento no encontrado' }

    const completedDate = new Date(parsed.data.completedDate)
    const nextDue = calculateNextDueDate(completedDate, existing.type, null)

    await prisma.maintenanceRecord.update({
      where: { id: recordId },
      data: {
        status: 'COMPLETADO',
        completedDate,
        completedBy: session.user.id,
        cost: parsed.data.cost,
        attachments: parsed.data.attachments
          ? (parsed.data.attachments as unknown as Prisma.InputJsonValue)
          : Prisma.JsonNull,
        description: parsed.data.notes
          ? `${existing.description}\n[NOTAS] ${parsed.data.notes}`
          : existing.description,
        nextDueDate: nextDue,
      },
    })

    revalidatePath(`/admin/mobile-units/${existing.mobileUnitId}/maintenance`)
    return { success: true as const, nextDueDate: nextDue }
  } catch (e: unknown) {
    const err = e as Error
    console.error('[completeMaintenance]', err.message)
    return { success: false as const, error: 'Error al completar el mantenimiento' }
  }
}

