/**
 * @file Tabla semántica HTML para los 8 mods LIS (sin jQuery DataTables).
 * @id IMPL-20260630-06 — Slice A NOVA absorción (ARCH-20260630-02).
 */
"use client";

import { useCallback, useEffect, useState } from "react";
import {
  listLabCatalogActionV2,
  deleteLabCatalogAction,
} from "@/actions/lab-catalog.actions";
import { type LabCatalogMod } from "@/lib/validations/lab-catalog";
import type { CatalogDef } from "../_lib/catalog-defs";

type Item = Record<string, unknown>;

export default function CatalogTable({
  mod,
  def,
  onEdit,
}: {
  mod: LabCatalogMod;
  def: CatalogDef;
  onEdit: (item: Item) => void;
}) {
  const [items, setItems] = useState<Item[]>([]);
  const [recordsTotal, setRecordsTotal] = useState(0);
  const [recordsFiltered, setRecordsFiltered] = useState(0);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [search, setSearch] = useState("");
  const [page, setPage] = useState(0); // 0-based
  const [pageSize] = useState(10);
  const [orderDir, setOrderDir] = useState<"asc" | "desc">("asc");
  const [orderColumn, setOrderColumn] = useState(0);
  const [pendingDelete, setPendingDelete] = useState<Item | null>(null);
  const [actionInProgress, setActionInProgress] = useState(false);

  const fetchData = useCallback(async () => {
    setLoading(true);
    setError(null);
    const result = await listLabCatalogActionV2({
      mod,
      draw: page + 1,
      start: page * pageSize,
      length: pageSize,
      search,
      orderColumn,
      orderDir,
    });
    if (result.ok) {
      setItems(result.data.data as Item[]);
      setRecordsTotal(result.data.recordsTotal);
      setRecordsFiltered(result.data.recordsFiltered);
    } else {
      setError(result.error);
      setItems([]);
    }
    setLoading(false);
  }, [mod, page, pageSize, search, orderColumn, orderDir]);

  useEffect(() => {
    void fetchData();
  }, [fetchData]);

  // Reset a página 0 cuando cambia el mod o búsqueda
  useEffect(() => {
    setPage(0);
  }, [mod, search]);

  const totalPages = Math.max(1, Math.ceil(recordsFiltered / pageSize));

  function handleSort(colIdx: number) {
    if (colIdx === orderColumn) {
      setOrderDir((d) => (d === "asc" ? "desc" : "asc"));
    } else {
      setOrderColumn(colIdx);
      setOrderDir("asc");
    }
  }

  async function confirmDelete() {
    if (!pendingDelete) return;
    const id = String(pendingDelete.id);
    setActionInProgress(true);
    const result = await deleteLabCatalogAction({ mod, id });
    setActionInProgress(false);
    if (result.ok) {
      setPendingDelete(null);
      await fetchData();
    } else {
      setError(result.error);
      setPendingDelete(null);
    }
  }

  return (
    <div className="bg-white rounded-lg border border-slate-200 shadow-sm">
      {/* Buscador */}
      <div className="flex flex-col md:flex-row md:items-center md:justify-between gap-3 p-4 border-b border-slate-200">
        <div>
          <h3 className="text-base font-semibold text-slate-800">{def.label}</h3>
          <p className="text-xs text-slate-500">
            {recordsFiltered} resultado{recordsFiltered === 1 ? "" : "s"}
            {recordsTotal !== recordsFiltered && ` (de ${recordsTotal} totales)`}
          </p>
        </div>
        <input
          type="search"
          value={search}
          onChange={(e) => setSearch(e.target.value)}
          placeholder={`Buscar en ${def.label.toLowerCase()}…`}
          className="border border-slate-300 rounded-lg px-3 py-2 text-sm w-full md:w-64 focus:outline-none focus:ring-2 focus:ring-blue-500"
        />
      </div>

      {/* Tabla */}
      <div className="overflow-x-auto">
        <table className="min-w-full divide-y divide-slate-200">
          <thead className="bg-slate-50">
            <tr>
              {def.tableColumns.map((col, idx) => (
                <th
                  key={col.key}
                  scope="col"
                  className="px-4 py-2 text-left text-xs font-medium text-slate-600 uppercase tracking-wider cursor-pointer select-none"
                  onClick={() => col.sortable !== false && handleSort(idx)}
                >
                  <span className="inline-flex items-center gap-1">
                    {col.label}
                    {orderColumn === idx && (
                      <span className="text-blue-600">{orderDir === "asc" ? "▲" : "▼"}</span>
                    )}
                  </span>
                </th>
              ))}
              <th scope="col" className="px-4 py-2 text-right text-xs font-medium text-slate-600 uppercase tracking-wider">
                Acciones
              </th>
            </tr>
          </thead>
          <tbody className="bg-white divide-y divide-slate-100">
            {loading && (
              <tr>
                <td colSpan={def.tableColumns.length + 1} className="px-4 py-8 text-center text-sm text-slate-500">
                  Cargando…
                </td>
              </tr>
            )}
            {!loading && error && (
              <tr>
                <td colSpan={def.tableColumns.length + 1} className="px-4 py-8 text-center text-sm text-red-600">
                  Error: {error}
                </td>
              </tr>
            )}
            {!loading && !error && items.length === 0 && (
              <tr>
                <td colSpan={def.tableColumns.length + 1} className="px-4 py-12 text-center text-sm text-slate-500">
                  Sin resultados. Use "+ Nuevo" para crear el primer registro.
                </td>
              </tr>
            )}
            {!loading &&
              !error &&
              items.map((item, rowIdx) => (
                <tr key={String(item.id) || rowIdx} className="hover:bg-slate-50">
                  {def.tableColumns.map((col) => {
                    const raw = item[col.key];
                    return (
                      <td key={col.key} className="px-4 py-2 text-sm text-slate-700 whitespace-nowrap">
                        {col.render ? col.render(raw) : raw === null || raw === undefined ? "—" : String(raw)}
                      </td>
                    );
                  })}
                  <td className="px-4 py-2 text-sm text-right whitespace-nowrap">
                    <button
                      type="button"
                      onClick={() => onEdit(item)}
                      className="text-blue-600 hover:text-blue-800 font-medium mr-3"
                    >
                      Editar
                    </button>
                    <button
                      type="button"
                      onClick={() => setPendingDelete(item)}
                      className="text-red-600 hover:text-red-800 font-medium"
                    >
                      Eliminar
                    </button>
                  </td>
                </tr>
              ))}
          </tbody>
        </table>
      </div>

      {/* Paginación */}
      <div className="flex items-center justify-between p-3 border-t border-slate-200 text-sm">
        <span className="text-slate-500">
          Página {page + 1} de {totalPages}
        </span>
        <div className="flex items-center gap-1">
          <button
            type="button"
            onClick={() => setPage((p) => Math.max(0, p - 1))}
            disabled={page === 0}
            className="px-3 py-1 rounded-lg border border-slate-300 bg-white text-slate-700 disabled:opacity-50 hover:bg-slate-50"
          >
            ← Anterior
          </button>
          {Array.from({ length: totalPages }, (_, i) => i)
            .filter((i) => Math.abs(i - page) <= 2)
            .map((i) => (
              <button
                key={i}
                type="button"
                onClick={() => setPage(i)}
                className={`px-3 py-1 rounded-lg border ${
                  i === page
                    ? "bg-blue-600 text-white border-blue-600"
                    : "bg-white text-slate-700 border-slate-300 hover:bg-slate-50"
                }`}
              >
                {i + 1}
              </button>
            ))}
          <button
            type="button"
            onClick={() => setPage((p) => Math.min(totalPages - 1, p + 1))}
            disabled={page >= totalPages - 1}
            className="px-3 py-1 rounded-lg border border-slate-300 bg-white text-slate-700 disabled:opacity-50 hover:bg-slate-50"
          >
            Siguiente →
          </button>
        </div>
      </div>

      {/* Modal de confirmación de borrado */}
      {pendingDelete && (
        <div className="fixed inset-0 z-50 bg-black/50 flex items-center justify-center p-4">
          <div className="bg-white rounded-lg shadow-xl max-w-md w-full p-6">
            <h3 className="text-lg font-semibold text-slate-800">¿Eliminar registro?</h3>
            <p className="mt-2 text-sm text-slate-600">
              Vas a desactivar el elemento{" "}
              <span className="font-medium">
                {String(pendingDelete[def.idDisplayKey] ?? pendingDelete.id)}
              </span>{" "}
              del catálogo <strong>{def.label}</strong>. Esta acción es un soft delete
              (active=false) y es reversible por un administrador.
            </p>
            <div className="mt-6 flex justify-end gap-2">
              <button
                type="button"
                onClick={() => setPendingDelete(null)}
                disabled={actionInProgress}
                className="px-4 py-2 rounded-lg border border-slate-300 bg-white text-slate-700 text-sm hover:bg-slate-50"
              >
                Cancelar
              </button>
              <button
                type="button"
                onClick={confirmDelete}
                disabled={actionInProgress}
                className="bg-red-600 hover:bg-red-700 text-white px-4 py-2 rounded-lg text-sm font-medium transition-colors disabled:opacity-50"
              >
                {actionInProgress ? "Eliminando…" : "Eliminar"}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

/**
 * @file API routes para los 8 catálogos LIS (Slice A NOVA absorción).
 * @id IMPL-20260701-07 — Bypass FastAPI por bug Prisma JS→Python naming.
 * @backup context/SPECs/SPEC_ARCH-20260630-02-DEMO-NOVA-ABSORBIDO.md
 *
 * Hotfix: el backend FastAPI retorna 500 porque los routers usan
 * `prisma.labUnit.find_*()` (camelCase JS) pero Prisma Python espera
 * snake_case. Bypass: Next.js API routes usan Prisma JS directo.
 *
 * Cuatro métodos en este único archivo:
 *   GET    /api/lab/catalogs/[mod]   → list paginado DataTables
 *   POST   /api/lab/catalogs/[mod]   → create
 *   PATCH  /api/lab/catalogs/[mod]   → update por id en body
 *   DELETE /api/lab/catalogs/[mod]   → soft delete (active=false) por id en body
 *
 * Autenticación: requiere sesión ADMIN (mismo gate que los server actions).
 *
 * IMPORTANTE: usa `lib/prisma.ts` (cliente Prisma JS ya configurado para
 * User, Worker, Company, etc.). NUNCA importar nada del backend FastAPI.
 *
 * IMPL-20260701-07 (hotfix): cada handler se envuelve en `withApiErrors`
 * para garantizar que cualquier excepción (auth, Prisma, params) retorne
 * JSON con `{ error, message }` en vez del HTML 500 de Next.js.
 */

import { NextRequest, NextResponse } from "next/server";
import { getServerSession } from "next-auth/next";
import { z } from "zod";

import { authOptions } from "@/auth";
import prisma from "@/lib/prisma";
import { withApiErrors } from "@/lib/api-handler";
import {
  LAB_CATALOG_MODS,
  LAB_SCHEMA_BY_MOD,
  type LabCatalogMod,
  isValidLabMod,
} from "@/lib/validations/lab-catalog";

// ---------------------------------------------------------------------------
// Mapa: mod (URL) → nombre del modelo Prisma JS
// ---------------------------------------------------------------------------
const MOD_TO_MODEL: Record<LabCatalogMod, string> = {
  unidades: "labUnit",
  muestras: "labSample",
  recipientes: "labContainer",
  metodologias: "labMethod",
  lugares_proceso: "labProcessArea",
  clasificaciones: "labClassification",
  indicaciones: "labIndication",
  departamentos: "labDepartment",
};

// Forzar runtime Node (Prisma no funciona en Edge).
export const runtime = "nodejs";
export const dynamic = "force-dynamic";

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

/** Gate de auth: solo ADMIN puede tocar catálogos. Envuelto en try/catch
 *  para que un fallo de NextAuth (ej. NEXTAUTH_SECRET faltante) NO
 *  derrote al handler completo con HTML 500. */
async function _requireAdmin(): Promise<{ userId: string } | null> {
  try {
    const session = await getServerSession(authOptions);
    const role = session?.user?.role;
    const id = session?.user?.id;
    if (!session?.user || !id) return null;
    if (role !== "ADMIN") return null;
    return { userId: id };
  } catch (err) {

    console.error("[_requireAdmin] session error:", err);
    return null;
  }
}

function _pickModel(mod: LabCatalogMod): string {
  return MOD_TO_MODEL[mod];
}

/** Acceso dinámico al modelo Prisma (TS no lo expone). */

function _modelFor(modelName: string) {
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  return (prisma as any)[modelName];
}

// ---------------------------------------------------------------------------
// GET — list paginado server-side (DataTables-compatible)
// ---------------------------------------------------------------------------
export const GET = withApiErrors(
  "GET /api/lab/catalogs/[mod]",
  async (
    req: NextRequest,
    { params }: { params: Promise<{ mod: string }> }
  ) => {
    const guard = await _requireAdmin();
    if (!guard) {
      return NextResponse.json({ error: "UNAUTHORIZED" }, { status: 401 });
    }

    const { mod: rawMod } = await params;
    if (!isValidLabMod(rawMod)) {
      return NextResponse.json(
        {
          error: `mod inválido: ${rawMod}. Permitidos: ${LAB_CATALOG_MODS.join(", ")}`,
        },
        { status: 400 }
      );
    }
    const mod = rawMod as LabCatalogMod;

    const url = new URL(req.url);
    const draw = parseInt(url.searchParams.get("draw") || "1", 10);
    const start = parseInt(url.searchParams.get("start") || "0", 10);
    const length = parseInt(url.searchParams.get("length") || "25", 10);
    const searchValue =
      url.searchParams.get("search[value]") ||
      url.searchParams.get("search") ||
      "";
    const orderCol = parseInt(
      url.searchParams.get("order[0][column]") || "0",
      10
    );
    const orderDir =
      (url.searchParams.get("order[0][dir]") || "asc").toLowerCase() === "desc"
        ? "desc"
        : "asc";
    const onlyActive =
      (url.searchParams.get("onlyActive") || "false").toLowerCase() === "true";

    const modelName = _pickModel(mod);
    const model = _modelFor(modelName);
    if (!model) {
      return NextResponse.json(
        { error: `Modelo ${modelName} no disponible` },
        { status: 500 }
      );
    }

    // Search + onlyActive where clause
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const where: any = {};
    if (searchValue.trim()) {
      // Búsqueda case-insensitive por code + name (o text para indicaciones)
      const textField = mod === "indicaciones" ? "text" : "name";
      where.OR = [
        { code: { contains: searchValue, mode: "insensitive" } },
        { [textField]: { contains: searchValue, mode: "insensitive" } },
      ];
    }
    if (onlyActive) {
      where.active = true;
    }

    // IMPL-20260707-13: fix bug "Unknown argument symbol" para mod=muestras.
    // Usamos 'createdAt' fijo (válido en todos los modelos).
    const orderByCol = "createdAt";

    const [recordsTotal, recordsFiltered, data] = await Promise.all([
      model.count(),
      model.count({ where }),
      model.findMany({
        where,
        skip: start,
        take: length,
        orderBy: { [orderByCol]: orderDir },
      }),
    ]);

    return NextResponse.json({
      draw,
      recordsTotal,
      recordsFiltered,
      data: data as unknown[],
    });
  }
);

// ---------------------------------------------------------------------------
// POST — create
// ---------------------------------------------------------------------------
export const POST = withApiErrors(
  "POST /api/lab/catalogs/[mod]",
  async (
    req: NextRequest,
    { params }: { params: Promise<{ mod: string }> }
  ) => {
    const guard = await _requireAdmin();
    if (!guard) {
      return NextResponse.json({ error: "UNAUTHORIZED" }, { status: 401 });
    }

    const { mod: rawMod } = await params;
    if (!isValidLabMod(rawMod)) {
      return NextResponse.json(
        { error: `mod inválido: ${rawMod}` },
        { status: 400 }
      );
    }
    const mod = rawMod as LabCatalogMod;

    let body: unknown;
    try {
      body = await req.json();
    } catch {
      return NextResponse.json({ error: "JSON inválido" }, { status: 400 });
    }

    const schema: z.ZodTypeAny = LAB_SCHEMA_BY_MOD[mod];
    const parsed = schema.safeParse(body);
    if (!parsed.success) {
      return NextResponse.json(
        {
          error: "VALIDATION",
          details: parsed.error.format(),
        },
        { status: 400 }
      );
    }

    const modelName = _pickModel(mod);
    const model = _modelFor(modelName);
    if (!model) {
      return NextResponse.json(
        { error: `Modelo ${modelName} no disponible` },
        { status: 500 }
      );
    }


    const created = await model.create({
      data: {
        ...(parsed.data as Record<string, unknown>),
        createdById: guard.userId,
      },
    });
    return NextResponse.json(
      { id: (created as { id: string }).id, item: created },
      { status: 201 }
    );
  }
);

// ---------------------------------------------------------------------------
// PATCH — update por id (en body: { id, ...values })
// ---------------------------------------------------------------------------
const patchBodySchema = z.object({ id: z.string().min(1) }).passthrough();

export const PATCH = withApiErrors(
  "PATCH /api/lab/catalogs/[mod]",
  async (
    req: NextRequest,
    { params }: { params: Promise<{ mod: string }> }
  ) => {
    const guard = await _requireAdmin();
    if (!guard) {
      return NextResponse.json({ error: "UNAUTHORIZED" }, { status: 401 });
    }

    const { mod: rawMod } = await params;
    if (!isValidLabMod(rawMod)) {
      return NextResponse.json(
        { error: `mod inválido: ${rawMod}` },
        { status: 400 }
      );
    }
    const mod = rawMod as LabCatalogMod;

    let body: Record<string, unknown>;
    try {
      body = (await req.json()) as Record<string, unknown>;
    } catch {
      return NextResponse.json({ error: "JSON inválido" }, { status: 400 });
    }

    const id = body.id as string | undefined;
    if (!id) {
      return NextResponse.json({ error: "id obligatorio" }, { status: 400 });
    }


    const _idParsed = patchBodySchema.safeParse(body);
    if (!_idParsed.success) {
      return NextResponse.json({ error: "id obligatorio" }, { status: 400 });
    }

    const schema: z.ZodTypeAny = LAB_SCHEMA_BY_MOD[mod];
    const partialSchema =
      typeof (schema as unknown as { partial?: () => z.ZodTypeAny }).partial ===
      "function"
        ? (
            schema as unknown as { partial: () => z.ZodTypeAny }
          ).partial()
        : schema;
    const parsed = partialSchema.safeParse(body);
    if (!parsed.success) {
      return NextResponse.json(
        { error: "VALIDATION", details: parsed.error.format() },
        { status: 400 }
      );
    }

    const modelName = _pickModel(mod);
    const model = _modelFor(modelName);
    if (!model) {
      return NextResponse.json(
        { error: `Modelo ${modelName} no disponible` },
        { status: 500 }
      );
    }

    const updated = await model.update({
      where: { id },
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      data: parsed.data as any,
    });
    return NextResponse.json({ item: updated });
  }
);

// ---------------------------------------------------------------------------
// DELETE — soft delete (active=false) por id en body
// ---------------------------------------------------------------------------
export const DELETE = withApiErrors(
  "DELETE /api/lab/catalogs/[mod]",
  async (
    req: NextRequest,
    { params }: { params: Promise<{ mod: string }> }
  ) => {
    const guard = await _requireAdmin();
    if (!guard) {
      return NextResponse.json({ error: "UNAUTHORIZED" }, { status: 401 });
    }

    const { mod: rawMod } = await params;
    if (!isValidLabMod(rawMod)) {
      return NextResponse.json(
        { error: `mod inválido: ${rawMod}` },
        { status: 400 }
      );
    }
    const mod = rawMod as LabCatalogMod;

    let body: { id?: string };
    try {
      body = (await req.json()) as { id?: string };
    } catch {
      return NextResponse.json({ error: "JSON inválido" }, { status: 400 });
    }
    if (!body.id) {
      return NextResponse.json({ error: "id obligatorio" }, { status: 400 });
    }

    const modelName = _pickModel(mod);
    const model = _modelFor(modelName);
    if (!model) {
      return NextResponse.json(
        { error: `Modelo ${modelName} no disponible` },
        { status: 500 }
      );
    }

    const updated = await model.update({
      where: { id: body.id },
      data: { active: false },
    });
    return NextResponse.json({ item: updated });
  }
);

'use client'
/**
 * Vista de 3 Agendas Simultáneas — Monitoreo Operativo
 * @description Pantalla de lectura independiente con las 3 agendas del día por sucursal.
 *              Permite redistribución de personal entre sucursales.
 * @id IMPL-20260318-09
 */
import { useEffect, useState, useCallback } from 'react'
import { getAppointmentsForOverview } from '@/actions/appointment.actions'
import Link from 'next/link'

interface AppointmentOverview {
    id: string
    scheduledAt: Date | string
    status: string
    worker: { firstName: string; lastName: string }
    company: { name: string } | null
    branch: { id: string; name: string; hourlyCapacity: number; openingTime: string; closingTime: string } | null
}

interface BranchColumn {
    id: string
    name: string
    appointments: AppointmentOverview[]
}

const STATUS_MAP: Record<string, { label: string; bg: string; text: string }> = {
    SCHEDULED: { label: 'Pendiente', bg: 'bg-blue-100', text: 'text-blue-700' },
    CONFIRMED: { label: 'Llegó', bg: 'bg-indigo-100', text: 'text-indigo-700' },
    IN_PROGRESS: { label: 'En Curso', bg: 'bg-amber-100', text: 'text-amber-700' },
    COMPLETED: { label: 'Completada', bg: 'bg-emerald-100', text: 'text-emerald-700' },
    CANCELLED: { label: 'Cancelada', bg: 'bg-red-100', text: 'text-red-700' },
    NO_SHOW: { label: 'Ausente', bg: 'bg-slate-100', text: 'text-slate-600' },
}

export default function AppointmentsOverviewPage() {
    const [appointments, setAppointments] = useState<AppointmentOverview[]>([])
    const [loading, setLoading] = useState(true)
    const [error, setError] = useState<string | null>(null)
    const [selectedDate, setSelectedDate] = useState<string>(() => {
        const now = new Date()
        const y = now.getFullYear()
        const m = String(now.getMonth() + 1).padStart(2, '0')
        const d = String(now.getDate()).padStart(2, '0')
        return `${y}-${m}-${d}`
    })

    const loadData = useCallback(async () => {
        setLoading(true)
        setError(null)
        try {
            const res = await getAppointmentsForOverview(selectedDate)
            if (res.success) {
                setAppointments((res.appointments ?? []) as unknown as AppointmentOverview[])
            } else {
                setError(res.error || 'Error al cargar agendas')
            }
        } catch {
            setError('Error de conexión al cargar las agendas')
        } finally {
            setLoading(false)
        }
    }, [selectedDate])

    useEffect(() => {
        loadData()
    }, [loadData])

    /** Devuelve true si la cita pertenece al día seleccionado (comparación en hora local) */
    function isOnSelectedDate(scheduledAt: Date | string) {
        const d = new Date(scheduledAt)
        const local = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`
        return local === selectedDate
    }

    // Agrupar citas por sucursal
    const branchMap: Record<string, BranchColumn> = {}
    for (const apt of appointments) {
        if (!apt.branch) continue
        if (!branchMap[apt.branch.id]) {
            branchMap[apt.branch.id] = { id: apt.branch.id, name: apt.branch.name, appointments: [] }
        }
        branchMap[apt.branch.id].appointments.push(apt)
    }
    const columns = Object.values(branchMap)

    return (
        <div className="max-w-7xl mx-auto space-y-6 animate-in fade-in duration-500">
            {/* Header */}
            <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
                <div>
                    <h1 className="text-2xl font-black text-slate-800 tracking-tight">Vista 3 Agendas</h1>
                    <p className="text-slate-500 text-sm">Monitoreo operativo por sucursal — solo lectura</p>
                </div>
                <div className="flex items-center gap-3 flex-wrap">
                    <Link
                        href="/appointments"
                        className="text-slate-500 hover:text-slate-800 text-sm font-bold transition-colors flex items-center gap-1"
                    >
                        ← Volver a Agenda
                    </Link>
                    <div className="bg-white border border-slate-200 px-4 py-2 rounded-xl shadow-sm flex items-center gap-2">
                        <span className="text-slate-400">📅</span>
                        <input
                            type="date"
                            value={selectedDate}
                            onChange={(e) => setSelectedDate(e.target.value)}
                            className="bg-transparent border-none outline-none text-sm font-bold text-slate-600 cursor-pointer"
                        />
                    </div>
                    <button
                        onClick={loadData}
                        className="bg-violet-600 hover:bg-violet-700 text-white px-4 py-2 rounded-xl text-sm font-bold transition-all"
                    >
                        🔄 Actualizar
                    </button>
                </div>
            </div>

            {/* Cargando */}
            {loading && (
                <div className="flex items-center justify-center min-h-[300px] gap-3">
                    <div className="w-8 h-8 border-4 border-violet-600 border-t-transparent rounded-full animate-spin" />
                    <p className="text-slate-500 font-medium animate-pulse">Cargando agendas...</p>
                </div>
            )}

            {/* Error */}
            {!loading && error && (
                <div className="bg-red-50 border border-red-200 p-6 rounded-2xl text-center">
                    <p className="text-red-600 font-bold">⚠️ {error}</p>
                    <button onClick={loadData} className="mt-3 text-sm text-red-500 underline font-medium">
                        Reintentar
                    </button>
                </div>
            )}

            {/* Sin citas */}
            {!loading && !error && columns.length === 0 && (
                <div className="bg-slate-50 border border-slate-200 p-12 rounded-2xl text-center">
                    <p className="text-4xl mb-3">🗓️</p>
                    <p className="text-slate-600 font-bold text-lg">Sin citas para este día</p>
                    <p className="text-slate-400 text-sm mt-1">
                        No hay citas registradas en ninguna sucursal para la fecha seleccionada.
                    </p>
                </div>
            )}

            {/* Columnas por sucursal */}
            {!loading && !error && columns.length > 0 && (
                <>
                    {/* Resumen de totales */}
                    <div className="grid grid-cols-3 gap-4">
                        {columns.map(col => {
                            const dayApts = col.appointments.filter(a => isOnSelectedDate(a.scheduledAt))
                            const pending = dayApts.filter(a => a.status === 'SCHEDULED').length
                            const completed = dayApts.filter(a => a.status === 'COMPLETED').length
                            return (
                                <div key={col.id} className="bg-white rounded-2xl border border-slate-200 shadow-sm p-4 flex items-center gap-4">
                                    <div className="w-10 h-10 bg-violet-100 text-violet-600 rounded-xl flex items-center justify-center text-xl flex-shrink-0">
                                        🏥
                                    </div>
                                    <div>
                                        <p className="font-black text-slate-800 text-sm leading-tight">{col.name}</p>
                                        <p className="text-xs text-slate-500 mt-0.5">
                                            {dayApts.length} total · {pending} pend. · {completed} comp.
                                        </p>
                                    </div>
                                </div>
                            )
                        })}
                    </div>

                    {/* Columnas detalle */}
                    <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                        {columns.map(col => {
                            const dayApts = col.appointments
                                .filter(a => isOnSelectedDate(a.scheduledAt))
                                .sort((a, b) => new Date(a.scheduledAt).getTime() - new Date(b.scheduledAt).getTime())

                            return (
                                <div key={col.id} className="bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden flex flex-col">
                                    <div className="bg-violet-600 px-5 py-4 text-white flex items-center justify-between flex-shrink-0">
                                        <div>
                                            <p className="font-black text-base">{col.name}</p>
                                            <p className="text-violet-200 text-xs font-medium">
                                                {dayApts.length} cita{dayApts.length !== 1 ? 's' : ''} del día
                                            </p>
                                        </div>
                                        <div className="w-10 h-10 bg-white/20 rounded-xl flex items-center justify-center font-black text-lg">
                                            {dayApts.length}
                                        </div>
                                    </div>
                                    <div className="divide-y divide-slate-100 overflow-y-auto max-h-[55vh] flex-grow">
                                        {dayApts.length === 0 ? (
                                            <div className="p-8 text-center">
                                                <p className="text-slate-300 text-3xl mb-2">📭</p>
                                                <p className="text-slate-400 text-sm font-medium">Sin citas para este día</p>
                                            </div>
                                        ) : (
                                            dayApts.map(apt => {
                                                const scheduled = new Date(apt.scheduledAt)
                                                const statusInfo = STATUS_MAP[apt.status] ?? STATUS_MAP.SCHEDULED
                                                return (
                                                    <div key={apt.id} className="px-4 py-3 flex items-center gap-3 hover:bg-slate-50 transition-colors">
                                                        <div className="text-center w-12 flex-shrink-0">
                                                            <p className="text-xs font-black text-slate-700 font-mono">
                                                                {scheduled.getHours().toString().padStart(2, '0')}:
                                                                {scheduled.getMinutes().toString().padStart(2, '0')}
                                                            </p>
                                                        </div>
                                                        <div className="flex-grow min-w-0">
                                                            <p className="text-sm font-bold text-slate-800 truncate">
                                                                {apt.worker.firstName} {apt.worker.lastName}
                                                            </p>
                                                            <p className="text-xs text-slate-500 truncate">
                                                                {apt.company?.name || '—'}
                                                            </p>
                                                        </div>
                                                        <span className={`text-[10px] font-black px-2 py-1 rounded-lg flex-shrink-0 ${statusInfo.bg} ${statusInfo.text}`}>
                                                            {statusInfo.label}
                                                        </span>
                                                    </div>
                                                )
                                            })
                                        )}
                                    </div>
                                </div>
                            )
                        })}
                    </div>
                </>
            )}
        </div>
    )
}

