/**
 * @file Reporte de corte de caja — Fase 3 NOVA absorción (G).
 * @id IMPL-20260708-19
 * @backup context/SPECs/SPEC_IMPL-20260707-SLICES-D-G-FINAL.md §2 (FASE 3)
 */
"use client";

import { useCallback, useEffect, useState } from "react";
import { getCashClosingAction, type CashClosingReport } from "@/actions/lab-cash.actions";
import { PAYMENT_METHOD_LABEL, type PaymentMethod } from "@/lib/validations/lab-cash";

export function ClosingReport() {
  const [report, setReport] = useState<CashClosingReport | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [dateFrom, setDateFrom] = useState<string>("");
  const [dateTo, setDateTo] = useState<string>("");

  const load = useCallback(async (from?: string, to?: string) => {
    setLoading(true);
    setError(null);
    const res = await getCashClosingAction({
      dateFrom: from || null,
      dateTo: to || null,
    });
    setLoading(false);
    if (!res.ok) {
      setError(res.error);
      setReport(null);
      return;
    }
    setReport(res.data);
  }, []);

  useEffect(() => {
    load();
  }, [load]);

  function handleApplyFilter() {
    load(dateFrom || undefined, dateTo || undefined);
  }

  function handleToday() {
    const today = new Date().toISOString().slice(0, 10);
    setDateFrom(today);
    setDateTo(today);
    load(today, today);
  }

  return (
    <div className="space-y-3">
      <div className="bg-white rounded-lg shadow-sm border border-slate-200 p-3">
        <h2 className="text-base font-semibold text-slate-800 mb-2">Corte de caja</h2>
        <div className="flex flex-wrap items-end gap-2">
          <div>
            <label className="block text-[10px] uppercase tracking-wider text-slate-500 mb-1">
              Desde
            </label>
            <input
              type="date"
              value={dateFrom}
              onChange={(e) => setDateFrom(e.target.value)}
              className="px-2 py-1.5 text-xs border border-slate-300 rounded"
            />
          </div>
          <div>
            <label className="block text-[10px] uppercase tracking-wider text-slate-500 mb-1">
              Hasta
            </label>
            <input
              type="date"
              value={dateTo}
              onChange={(e) => setDateTo(e.target.value)}
              className="px-2 py-1.5 text-xs border border-slate-300 rounded"
            />
          </div>
          <button
            type="button"
            onClick={handleApplyFilter}
            disabled={loading}
            className="px-3 py-1.5 text-xs font-medium rounded bg-slate-800 text-white hover:bg-slate-900"
          >
            Aplicar
          </button>
          <button
            type="button"
            onClick={handleToday}
            disabled={loading}
            className="px-3 py-1.5 text-xs font-medium rounded border border-slate-300 text-slate-700 hover:bg-slate-50"
          >
            Hoy
          </button>
          <button
            type="button"
            onClick={() => {
              setDateFrom("");
              setDateTo("");
              load();
            }}
            disabled={loading}
            className="px-3 py-1.5 text-xs font-medium rounded border border-slate-300 text-slate-700 hover:bg-slate-50"
          >
            Últimas 24h
          </button>
        </div>
      </div>

      {error && (
        <div className="rounded-lg border border-red-200 bg-red-50 px-3 py-2 text-xs text-red-700">
          {error}
        </div>
      )}

      {loading && !report && (
        <p className="text-xs text-slate-500">Cargando reporte...</p>
      )}

      {report && (
        <>
          <div className="bg-white rounded-lg shadow-sm border border-slate-200 p-4">
            <div className="text-[10px] uppercase tracking-wider text-slate-500 mb-3">
              Rango: {new Date(report.dateFrom).toLocaleString()} →{" "}
              {new Date(report.dateTo).toLocaleString()}
            </div>

            <div className="grid grid-cols-2 md:grid-cols-4 gap-2 mb-3">
              <KpiCard label="Órdenes" value={report.totalOrders} color="slate" />
              <KpiCard label="Facturadas" value={report.billedOrders} color="blue" />
              <KpiCard label="Cortesías" value={report.courtesyOrders} color="amber" />
              <KpiCard label="Pagos" value={report.paymentsCount} color="emerald" />
            </div>

            <div className="grid grid-cols-1 md:grid-cols-3 gap-2 mb-3">
              <MoneyCard label="Total facturado" value={report.totalBilled} color="slate" />
              <MoneyCard label="Total cobrado" value={report.totalCollected} color="emerald" />
              <MoneyCard
                label="Saldo pendiente"
                value={report.balancePending}
                color={report.balancePending > 0 ? "red" : "emerald"}
              />
            </div>

            <div>
              <h3 className="text-sm font-semibold text-slate-700 mb-2">Por método de pago</h3>
              {report.byMethod.length === 0 ? (
                <p className="text-xs text-slate-500 italic">Sin pagos en el rango.</p>
              ) : (
                <table className="w-full text-xs">
                  <thead>
                    <tr className="text-left text-slate-500 border-b border-slate-200">
                      <th className="py-1.5 font-medium">Método</th>
                      <th className="py-1.5 font-medium text-right">Cantidad</th>
                      <th className="py-1.5 font-medium text-right">Total</th>
                    </tr>
                  </thead>
                  <tbody>
                    {report.byMethod.map((row) => (
                      <tr key={row.method} className="border-b border-slate-100">
                        <td className="py-1.5">
                          {PAYMENT_METHOD_LABEL[row.method as PaymentMethod] ?? row.method}
                        </td>
                        <td className="py-1.5 text-right font-mono">{row.count}</td>
                        <td className="py-1.5 text-right font-mono font-medium">
                          ${row.total.toFixed(2)}
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              )}
            </div>

            <div className="mt-3 pt-3 border-t border-slate-100 text-[10px] text-slate-400">
              Reporte generado el {new Date(report.generatedAt).toLocaleString()}
            </div>
          </div>
        </>
      )}
    </div>
  );
}

function KpiCard({
  label,
  value,
  color,
}: {
  label: string;
  value: number;
  color: "slate" | "blue" | "amber" | "emerald";
}) {
  const colorClass = {
    slate: "bg-slate-50 text-slate-800",
    blue: "bg-blue-50 text-blue-800",
    amber: "bg-amber-50 text-amber-800",
    emerald: "bg-emerald-50 text-emerald-800",
  }[color];
  return (
    <div className={`${colorClass} rounded p-2 text-center`}>
      <div className="text-[10px] uppercase tracking-wider opacity-70">{label}</div>
      <div className="text-lg font-bold">{value}</div>
    </div>
  );
}

function MoneyCard({
  label,
  value,
  color,
}: {
  label: string;
  value: number;
  color: "slate" | "emerald" | "red";
}) {
  const colorClass = {
    slate: "bg-slate-50 text-slate-800",
    emerald: "bg-emerald-50 text-emerald-800",
    red: "bg-red-50 text-red-800",
  }[color];
  return (
    <div className={`${colorClass} rounded p-3`}>
      <div className="text-[10px] uppercase tracking-wider opacity-70">{label}</div>
      <div className="text-xl font-bold font-mono">${value.toFixed(2)}</div>
    </div>
  );
}

/**
 * @file Lista de órdenes pendientes de pago — Caja de laboratorio.
 * @id IMPL-20260708-19 — Fase 3 NOVA absorción — G Caja.
 * @backup context/SPECs/SPEC_IMPL-20260707-SLICES-D-G-FINAL.md §2 (FASE 3)
 */
"use client";

import { useCallback, useEffect, useState } from "react";
import Link from "next/link";
import {
  getPendingCashOrdersAction,
  type CashPaymentsSummary,
} from "@/actions/lab-cash.actions";
import { registerLabPaymentAction } from "@/actions/lab-cash.actions";
import {
  PAYMENT_METHODS,
  PAYMENT_METHOD_LABEL,
  type PaymentMethod,
} from "@/lib/validations/lab-cash";

interface PendingOrder {
  id: string;
  folio: number | null;
  status: string;
  patientName: string;
  patientCode: string;
  companyName: string | null;
  total: number;
  paidTotal: number;
  balance: number;
  isCourtesy: boolean;
  createdAt: string;
}

export function CashList() {
  const [orders, setOrders] = useState<PendingOrder[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [activeOrder, setActiveOrder] = useState<PendingOrder | null>(null);

  const load = useCallback(async () => {
    setLoading(true);
    setError(null);
    const res = await getPendingCashOrdersAction();
    setLoading(false);
    if (!res.ok) {
      setError(res.error);
      setOrders([]);
      return;
    }
    setOrders(res.data);
  }, []);

  useEffect(() => {
    load();
  }, [load]);

  return (
    <div className="space-y-3">
      <div className="flex items-center justify-between">
        <h2 className="text-lg font-semibold text-slate-800">Órdenes pendientes de pago</h2>
        <button
          type="button"
          onClick={load}
          disabled={loading}
          className="px-3 py-1.5 text-xs font-medium rounded border border-slate-300 text-slate-700 hover:bg-slate-50"
        >
          {loading ? "Cargando..." : "🔄 Refrescar"}
        </button>
      </div>

      {error && (
        <div className="rounded-lg border border-red-200 bg-red-50 px-3 py-2 text-xs text-red-700">
          {error}
        </div>
      )}

      {loading && orders.length === 0 && (
        <p className="text-xs text-slate-500">Cargando órdenes...</p>
      )}

      {!loading && orders.length === 0 && !error && (
        <div className="bg-white rounded-lg shadow-sm border border-slate-200 p-6 text-center">
          <p className="text-sm text-slate-600">
            ✨ No hay órdenes pendientes de pago.
          </p>
        </div>
      )}

      <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-3">
        {orders.map((o) => (
          <div
            key={o.id}
            className="bg-white rounded-lg shadow-sm border border-slate-200 p-3"
          >
            <div className="flex items-start justify-between mb-2">
              <div>
                <div className="text-xs font-bold text-slate-800">
                  Folio {o.folio ?? "s/folio"}
                </div>
                <div className="text-xs text-slate-600">
                  {o.patientName}{" "}
                  <span className="text-slate-400 font-mono">[{o.patientCode}]</span>
                </div>
                {o.companyName && (
                  <div className="text-[10px] text-slate-500">{o.companyName}</div>
                )}
              </div>
              <span
                className={`px-2 py-0.5 text-[10px] font-medium rounded border ${
                  o.isCourtesy
                    ? "bg-amber-100 text-amber-800 border-amber-300"
                    : o.balance === 0
                    ? "bg-emerald-100 text-emerald-800 border-emerald-300"
                    : "bg-red-100 text-red-800 border-red-300"
                }`}
              >
                {o.isCourtesy ? "CORTESÍA" : o.balance === 0 ? "PAGADO" : "PENDIENTE"}
              </span>
            </div>

            <div className="grid grid-cols-3 gap-1 mb-2 text-center text-[10px]">
              <div className="bg-slate-50 rounded p-1">
                <div className="text-slate-500 uppercase">Total</div>
                <div className="font-bold text-slate-800">${o.total.toFixed(2)}</div>
              </div>
              <div className="bg-emerald-50 rounded p-1">
                <div className="text-emerald-700 uppercase">Cobrado</div>
                <div className="font-bold text-emerald-700">${o.paidTotal.toFixed(2)}</div>
              </div>
              <div className={`${o.balance > 0 ? "bg-red-50" : "bg-slate-50"} rounded p-1`}>
                <div className={`${o.balance > 0 ? "text-red-700" : "text-slate-500"} uppercase`}>
                  Pendiente
                </div>
                <div className={`font-bold ${o.balance > 0 ? "text-red-700" : "text-slate-800"}`}>
                  ${o.balance.toFixed(2)}
                </div>
              </div>
            </div>

            <div className="flex items-center justify-between gap-2">
              <Link
                href={`/lab/results/${o.id}`}
                className="text-[10px] text-blue-700 hover:underline"
              >
                Ver detalle →
              </Link>
              {o.balance > 0 && !o.isCourtesy && (
                <button
                  type="button"
                  onClick={() => setActiveOrder(o)}
                  className="px-2 py-1 text-[10px] font-medium rounded bg-emerald-600 text-white hover:bg-emerald-700"
                >
                  + Pago rápido
                </button>
              )}
            </div>
          </div>
        ))}
      </div>

      {activeOrder && (
        <QuickPayModal
          order={activeOrder}
          onClose={() => setActiveOrder(null)}
          onSaved={async () => {
            setActiveOrder(null);
            await load();
          }}
        />
      )}
    </div>
  );
}

// ---------------------------------------------------------------------------
// Modal: pago rápido desde /lab/cash
// ---------------------------------------------------------------------------
function QuickPayModal({
  order,
  onClose,
  onSaved,
}: {
  order: PendingOrder;
  onClose: () => void;
  onSaved: () => void | Promise<void>;
}) {
  const [amount, setAmount] = useState<string>(order.balance.toFixed(2));
  const [method, setMethod] = useState<PaymentMethod>("CASH");
  const [reference, setReference] = useState<string>("");
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    setError(null);
    const numAmount = Number(amount);
    if (!Number.isFinite(numAmount) || numAmount <= 0) {
      setError("El monto debe ser un número mayor a 0.");
      return;
    }
    setBusy(true);
    const res = await registerLabPaymentAction(order.id, {
      amount: numAmount,
      method,
      reference: reference.trim() || null,
    });
    setBusy(false);
    if (!res.ok) {
      setError(res.error);
      return;
    }
    await onSaved();
  }

  return (
    <div className="fixed inset-0 z-50 bg-black/40 flex items-center justify-center p-4">
      <div className="bg-white rounded-lg shadow-xl border border-slate-200 w-full max-w-md p-5">
        <div className="mb-3">
          <h3 className="text-base font-semibold text-slate-800">Pago rápido</h3>
          <p className="text-xs text-slate-500">
            Folio {order.folio} · {order.patientName} · Pendiente: ${order.balance.toFixed(2)}
          </p>
        </div>
        <form onSubmit={handleSubmit} className="space-y-3">
          <div>
            <label className="block text-xs font-medium text-slate-700 mb-1">Monto (MXN)</label>
            <input
              type="number"
              step="0.01"
              min="0"
              value={amount}
              onChange={(e) => setAmount(e.target.value)}
              required
              autoFocus
              className="w-full px-3 py-2 text-sm border border-slate-300 rounded focus:outline-none focus:ring-2 focus:ring-emerald-500"
            />
          </div>
          <div>
            <label className="block text-xs font-medium text-slate-700 mb-1">Forma de pago</label>
            <select
              value={method}
              onChange={(e) => setMethod(e.target.value as PaymentMethod)}
              className="w-full px-3 py-2 text-sm border border-slate-300 rounded focus:outline-none focus:ring-2 focus:ring-emerald-500"
            >
              {PAYMENT_METHODS.map((m) => (
                <option key={m} value={m}>
                  {PAYMENT_METHOD_LABEL[m]}
                </option>
              ))}
            </select>
          </div>
          <div>
            <label className="block text-xs font-medium text-slate-700 mb-1">
              Referencia (opcional)
            </label>
            <input
              type="text"
              value={reference}
              onChange={(e) => setReference(e.target.value)}
              placeholder="Ej. últimos 4 dígitos, SPEI ref, cheque #"
              maxLength={200}
              className="w-full px-3 py-2 text-sm border border-slate-300 rounded focus:outline-none focus:ring-2 focus:ring-emerald-500"
            />
          </div>
          {error && (
            <div className="rounded border border-red-200 bg-red-50 px-3 py-2 text-xs text-red-700">
              {error}
            </div>
          )}
          <div className="flex justify-end gap-2 pt-2">
            <button
              type="button"
              onClick={onClose}
              disabled={busy}
              className="px-3 py-1.5 text-xs font-medium rounded border border-slate-300 text-slate-700 hover:bg-slate-50"
            >
              Cancelar
            </button>
            <button
              type="submit"
              disabled={busy}
              className="px-3 py-1.5 text-xs font-medium rounded bg-emerald-600 text-white hover:bg-emerald-700 disabled:opacity-50"
            >
              {busy ? "Guardando..." : "Registrar"}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}

/**
 * @file Admisión de Laboratorio auto-llenada desde MedicalEvent.
 * @id IMPL-20260707-17 — Fase 1 NOVA absorción (ARCH-20260707-17) — B-v2.
 *
 * Server Component. Carga el MedicalEvent, deriva worker/doctor/company,
 * y pasa esos datos a LabOrderForm para admisión pre-llenada.
 *
 * Next.js 16+ requiere `await params`.
 */
import Link from "next/link";
import { notFound, redirect } from "next/navigation";
import { LabOrderForm } from "../_components/LabOrderForm";
import { InfoBanner } from "@/components/shared/InfoBanner";
import { getMedicalEventForLabAdmissionAction, autoGenerateLabOrderAction } from "@/actions/pending-order.actions";

export const dynamic = "force-dynamic";

type SP = {
  orderId?: string;
};

export default async function LabReceptionFromEventPage({
  params,
  searchParams,
}: {
  params: Promise<{ medicalEventId: string }>;
  searchParams: Promise<SP>;
}) {
  const { medicalEventId } = await params;
  const sp = await searchParams;
  const orderId = sp.orderId;

  const result = await getMedicalEventForLabAdmissionAction(medicalEventId);
  if (!result.ok) {
    if (result.code === "NOT_FOUND") notFound();
    return (
      <div className="p-8 bg-red-50 border border-red-200 rounded-2xl">
        <h2 className="text-lg font-bold text-red-700 mb-2">Error</h2>
        <p className="text-red-600 text-sm">{result.error}</p>
        <Link
          href="/lab/reception"
          className="mt-4 inline-block bg-red-600 text-white px-4 py-2 rounded-lg text-sm font-bold"
        >
          ← Volver a bandeja
        </Link>
      </div>
    );
  }
  const ev = result.data;

  // Si no hay orderId y hay eventTests, disparar el trigger automáticamente
  let resolvedOrderId = orderId;
  if (!resolvedOrderId && ev.eventTests.length > 0) {
    const trig = await autoGenerateLabOrderAction({ medicalEventId });
    if (trig.ok && trig.data.labOrderId) {
      resolvedOrderId = trig.data.labOrderId;
    }
  }

  // Si después del trigger no hay items Lab Pendientes, redirigir a la papeleta
  if (ev.eventTests.length === 0) {
    return (
      <div className="space-y-4">
        <InfoBanner
          icon={<span aria-hidden>⚠️</span>}
          title="Esta papeleta no tiene EventTests SAMPLE_TAKEN de Laboratorio"
        >
          Solo se pueden crear admisiones Lab desde papeletas con muestras de laboratorio.
        </InfoBanner>
        <Link
          href={`/events/${medicalEventId}`}
          className="inline-block bg-blue-600 text-white px-4 py-2 rounded-lg text-sm font-medium"
        >
          ← Volver a la papeleta
        </Link>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row md:items-center md:justify-between gap-3">
        <div>
          <h2 className="text-2xl font-bold text-slate-800">Admisión Lab — Papeleta auto-llenada</h2>
          <p className="text-sm text-slate-500">
            Datos importados automáticamente desde la papeleta #{ev.medicalEventId.slice(0, 8)}…
          </p>
        </div>
        <Link
          href="/lab/reception"
          className="text-xs px-3 py-1.5 rounded-lg border border-slate-300 text-slate-700 hover:bg-slate-50"
        >
          ← Bandeja
        </Link>
      </div>

      <InfoBanner
        icon={<span aria-hidden>✅</span>}
        title="Pre-llenado desde MedicalEvent"
      >
        Paciente, médico y empresa vienen de la papeleta. Solo confirme precios y folio.
      </InfoBanner>

      <LabOrderForm
        orderId={resolvedOrderId}
        initialWorkerId={ev.workerId}
        initialMedicalEventId={ev.medicalEventId}
        initialMedicalEvent={{
          medicalEventId: ev.medicalEventId,
          workerId: ev.workerId,
          workerName: ev.workerName,
          workerCode: ev.workerCode,
          companyId: ev.companyId,
          companyName: ev.companyName,
          branchId: ev.branchId,
          branchName: ev.branchName,
          doctorName: ev.doctorName,
          intakeCreatedByUserId: ev.intakeCreatedByUserId,
          eventTests: ev.eventTests,
        }}
      />
    </div>
  );
}

