/**
 * @file Formulario principal de admisión LabOrder.
 * @id IMPL-20260701-03 — Slice B Recepción.
 *
 * Cliente Component: orquesta todos los paneles + acciones.
 * Si recibe orderId por props (vía searchParams), carga la orden con
 * getLabOrderAction y la presenta en modo edición DRAFT.
 *
 * IMPL-20260706-02: refactor visual a paleta AMI (slate + blue-600).
 */
"use client";

import { useEffect, useMemo, useState } from "react";
import { useRouter } from "next/navigation";
import {
  confirmLabOrderAction,
  createLabOrderAction,
  getLabOrderAction,
  updateLabOrderAction,
  searchCompaniesAction,
  searchDoctorsAction,
  searchWorkersAction,
} from "@/actions/lab-order.actions";
import type {
  CompanySearchResult,
  DoctorSearchResult,
  LabOrderItemInput,
  WorkerSearchResult,
} from "@/lib/validations/lab-order";
import { LabOrderAutocomplete, type AutocompleteItem } from "./LabOrderAutocomplete";
import { LabOrderDeliveryPanel } from "./LabOrderDeliveryPanel";
import { LabOrderFlagsPanel, type LabOrderFlagsState } from "./LabOrderFlagsPanel";
import { LabOrderStudiesTable } from "./LabOrderStudiesTable";
import { LabOrderTotalsPanel } from "./LabOrderTotalsPanel";

interface Props {
  orderId?: string;
  // IMPL-20260707-16: Slice C — prefill desde papeleta AMI
  initialWorkerId?: string | null;
  initialMedicalEventId?: string | null;
  /**
   * IMPL-20260707-17 — Fase 1 B-v2: admisión auto-llenada desde papeleta.
   * Si viene, pre-llena worker, doctor, company, branchId y estudios desde MedicalEvent.
   */
  initialMedicalEvent?: {
    medicalEventId: string;
    workerId: string;
    workerName: string;
    workerCode: string;
    companyId: string | null;
    companyName: string | null;
    branchId: string | null;
    branchName: string | null;
    doctorName: string;
    intakeCreatedByUserId: string | null;
    eventTests: Array<{
      id: string;
      testNameSnapshot: string;
      medicalTestId: string | null;
      medicalTestCode: string | null;
    }>;
  } | null;
}

const EMPTY_FLAGS: LabOrderFlagsState = {
  urgency: "NORMAL",
  confidentiality: "NORMAL",
  language: "es",
  homeSample: false,
  sendResultsByEmail: false,
  generateInvoice: false,
  isCourtesy: false,
  courtesyType: null,
};

// Inputs estilo AMI: border-slate-300 rounded-lg px-3 py-2 focus:ring-2 focus:ring-blue-500
const BASE_INPUT =
  "w-full border border-slate-300 rounded-lg px-3 py-2 text-sm bg-white focus:outline-none focus:ring-2 focus:ring-blue-500 disabled:bg-slate-100 disabled:text-slate-500";
const READONLY_INPUT = `${BASE_INPUT} bg-slate-100 text-slate-500`;
const LABEL = "block text-xs font-medium text-slate-700 mb-1";

export function LabOrderForm({ orderId, initialWorkerId, initialMedicalEventId, initialMedicalEvent }: Props) {
  const router = useRouter();
  // IMPL-20260707-16: Slice C — prefill desde papeleta
  const [worker, setWorker] = useState<WorkerSearchResult | null>(
    initialMedicalEvent
      ? {
          id: initialMedicalEvent.workerId,
          fullName: initialMedicalEvent.workerName,
          code: initialMedicalEvent.workerCode,
          age: null,
          companyName: initialMedicalEvent.companyName,
        }
      : initialWorkerId
        ? { id: initialWorkerId, fullName: "", code: "", age: null, companyName: null }
        : null
  );
  const [medicalEventId, setMedicalEventId] = useState<string>(
    initialMedicalEvent?.medicalEventId ?? initialMedicalEventId ?? ""
  );
  const [doctorInput, setDoctorInput] = useState(""); // doctorName libre
  const [doctorClave, setDoctorClave] = useState("");
  const [doctorPicked, setDoctorPicked] = useState<DoctorSearchResult | null>(null);
  const [company, setCompany] = useState<CompanySearchResult | null>(null);
  const [classificationId, setClassificationId] = useState("");
  const [observations, setObservations] = useState("");

  const [patientDiscountPct, setPatientDiscountPct] = useState(0);
  const [doctorDiscountPct, setDoctorDiscountPct] = useState(0);
  const [doctorCommissionPct, setDoctorCommissionPct] = useState(0);
  const [companyDiscountPct, setCompanyDiscountPct] = useState(0);

  const [flags, setFlags] = useState<LabOrderFlagsState>(EMPTY_FLAGS);
  const [delivery, setDelivery] = useState<{ deliveryDate?: string | null; deliveryTime?: string | null }>({
    deliveryDate: null,
    deliveryTime: null,
  });
  const [items, setItems] = useState<LabOrderItemInput[]>([]);

  const [currentOrderId, setCurrentOrderId] = useState<string | undefined>(orderId);
  const [status, setStatus] = useState<string>("NEW");
  const [busy, setBusy] = useState(false);
  const [message, setMessage] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);

  // Cargar orden existente si se pasó orderId
  useEffect(() => {
    if (!orderId) return;
    (async () => {
      const res = await getLabOrderAction(orderId);
      if (!res.ok) {
        setError(res.error);
        return;
      }
      const o = res.data.order as Record<string, unknown>;
      setCurrentOrderId((o.id as string) ?? orderId);
      setStatus((o.status as string) ?? "DRAFT");
      setDoctorInput(String((o.doctorName as string) ?? ""));
      setDoctorClave(((o.doctorClave as string | null) ?? "") || "");
      setClassificationId(((o.classificationId as string | null) ?? "") || "");
      setObservations(((o.observations as string | null) ?? "") || "");
      setPatientDiscountPct(Number((o.patientDiscountPct as number) ?? 0));
      setDoctorDiscountPct(Number((o.doctorDiscountPct as number) ?? 0));
      setDoctorCommissionPct(Number((o.doctorCommissionPct as number) ?? 0));
      setCompanyDiscountPct(Number((o.companyDiscountPct as number) ?? 0));
      setFlags({
        urgency: ((o.urgency as "NORMAL" | "URGENT") ?? "NORMAL"),
        confidentiality: ((o.confidentiality as "NORMAL" | "CONFIDENTIAL") ?? "NORMAL"),
        language: ((o.language as "es" | "en") ?? "es"),
        homeSample: Boolean(o.homeSample),
        sendResultsByEmail: Boolean(o.sendResultsByEmail),
        generateInvoice: Boolean(o.generateInvoice),
        isCourtesy: Boolean(o.isCourtesy),
        courtesyType: (o.courtesyType as string | null) ?? null,
      });
      setDelivery({
        deliveryDate: o.deliveryDate ? String(o.deliveryDate).slice(0, 10) : null,
        deliveryTime: (o.deliveryTime as string | null) ?? null,
      });
      const loadedItems = Array.isArray(o.items)
        ? (o.items as Array<Record<string, unknown>>).map((it) => ({
            medicalTestId: String(it.medicalTestId),
            price: Number(it.price ?? 0),
            discountAmount: Number(it.discountAmount ?? 0),
            discountPct: Number(it.discountPct ?? 0),
          }))
        : [];
      setItems(loadedItems);
      // Worker y company via id se reconstruyen con el objeto completo si viene
      if (o.workerId) {
        setWorker({
          id: o.workerId as string,
          fullName: "",
          code: "",
          age: null,
          companyName: null,
        });
      }
      if (o.companyId) {
        setCompany({ id: o.companyId as string, name: "", rfc: null });
      }
    })();
  }, [orderId]);

  // IMPL-20260707-17: Fase 1 B-v2 — prefill desde MedicalEvent (admisin auto-llenada)
  useEffect(() => {
    if (!initialMedicalEvent) return;
    if (orderId) return; // si estamos editando, no pisar
    if (initialMedicalEvent.eventTests.length > 0 && items.length === 0) {
      // Pre-llenar items con los EventTests de la papeleta (precios en 0)
      const preItems: LabOrderItemInput[] = initialMedicalEvent.eventTests
        .filter((et) => et.medicalTestId)
        .map((et) => ({
          medicalTestId: et.medicalTestId as string,
          price: 0,
          discountAmount: 0,
          discountPct: 0,
        }));
      setItems(preItems);
    }
    // Pre-llenar doctor
    if (initialMedicalEvent.doctorName && !doctorPicked && !doctorInput) {
      setDoctorInput(initialMedicalEvent.doctorName);
    }
    // Pre-llenar company
    if (initialMedicalEvent.companyId && !company) {
      setCompany({
        id: initialMedicalEvent.companyId,
        name: initialMedicalEvent.companyName ?? "",
        rfc: null,
      });
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [initialMedicalEvent]);

  const readOnly = status !== "NEW" && status !== "DRAFT";

  const payload = useMemo(() => {
    if (!worker) return null;
    return {
      workerId: worker.id,
      medicalEventId: medicalEventId || null, // IMPL-20260707-16: Slice C
      doctorName: doctorPicked?.name || doctorInput,
      doctorClave: doctorClave || doctorPicked?.clave || null,
      classificationId: classificationId || null,
      companyId: company?.id ?? null,
      patientDiscountPct,
      doctorDiscountPct,
      doctorCommissionPct,
      companyDiscountPct,
      ...flags,
      deliveryDate: delivery.deliveryDate ?? null,
      deliveryTime: delivery.deliveryTime ?? null,
      observations: observations || null,
      items,
    };
  }, [
    worker,
    medicalEventId,
    doctorInput,
    doctorPicked,
    doctorClave,
    classificationId,
    company,
    patientDiscountPct,
    doctorDiscountPct,
    doctorCommissionPct,
    companyDiscountPct,
    flags,
    delivery,
    observations,
    items,
  ]);

  async function onSaveDraft() {
    if (!payload) {
      setError("Selecciona un paciente antes de guardar.");
      return;
    }
    setBusy(true);
    setError(null);
    setMessage(null);
    const action = currentOrderId
      ? updateLabOrderAction(currentOrderId, payload)
      : createLabOrderAction(payload);
    const res = await action;
    setBusy(false);
    if (!res.ok) {
      setError(res.error);
      return;
    }
    setMessage("Borrador guardado.");
    if (!currentOrderId && "id" in res.data) {
      const newId = String(res.data.id);
      setCurrentOrderId(newId);
      setStatus("DRAFT");
      router.replace(`/lab/reception?orderId=${newId}`);
    } else {
      setStatus("DRAFT");
    }
  }

  async function onConfirm() {
    if (!currentOrderId) {
      // Si no había orden previa, primero crear
      if (!payload) {
        setError("Selecciona un paciente y al menos un estudio.");
        return;
      }
      setBusy(true);
      const res = await createLabOrderAction(payload);
      setBusy(false);
      if (!res.ok) {
        setError(res.error);
        return;
      }
      setCurrentOrderId(res.data.id);
      const conf = await confirmLabOrderAction(res.data.id);
      if (!conf.ok) {
        setError(conf.error);
        return;
      }
      setStatus("SAVED");
      setMessage("Orden confirmada y folio generado.");
      router.replace(`/lab/reception?orderId=${res.data.id}`);
      return;
    }
    setBusy(true);
    // Si estamos editando DRAFT, confirmar
    const conf = await confirmLabOrderAction(currentOrderId);
    setBusy(false);
    if (!conf.ok) {
      setError(conf.error);
      return;
    }
    setStatus("SAVED");
    setMessage("Orden confirmada y folio generado.");
  }

  return (
    <div className="space-y-4">
      {/* Cabecera */}
      <div className="bg-white rounded-lg shadow-sm border border-slate-200 p-4">
        <div className="flex items-center justify-between mb-3">
          <div>
            <h2 className="text-base font-semibold text-slate-800">
              Nueva Admisión
              {currentOrderId && (
                <span className="ml-2 font-mono text-xs text-slate-500">
                  Editando: {currentOrderId.slice(0, 8)}…
                </span>
              )}
            </h2>
          </div>
          <span className="text-xs text-slate-500">
            Fecha: {new Date().toLocaleDateString()}
          </span>
        </div>

        {error && (
          <div className="mb-3 rounded-lg border border-red-200 bg-red-50 px-3 py-2 text-xs text-red-700">
            {error}
          </div>
        )}
        {message && (
          <div className="mb-3 rounded-lg border border-emerald-200 bg-emerald-50 px-3 py-2 text-xs text-emerald-700">
            {message}
          </div>
        )}

        <div className="grid grid-cols-12 gap-3">
          <div className="col-span-6">
            <LabOrderAutocomplete<WorkerSearchResult>
              label="Paciente *"
              placeholder="Buscar por nombre, código..."
              value={worker}
              onChange={setWorker}
              fetchAction={async (q) => await searchWorkersAction(q)}
              displayValue={(w) => `${w.fullName} (${w.code})`}
              renderItem={(w) => (
                <span>
                  <strong className="text-slate-800">{w.fullName}</strong>{" "}
                  <span className="text-slate-500">[{w.code}]</span>
                  {w.age != null && (
                    <span className="ml-2 text-xs text-slate-600">{w.age} años</span>
                  )}
                </span>
              )}
            />
          </div>
          <div className="col-span-2">
            <label className={LABEL}>Edad</label>
            <input
              type="text"
              readOnly
              value={worker?.age ?? ""}
              placeholder="—"
              className={READONLY_INPUT}
            />
          </div>
          <div className="col-span-2">
            <label className={LABEL}>Dto% Pac.</label>
            <input
              type="number"
              min={0}
              max={100}
              value={patientDiscountPct}
              disabled={readOnly}
              onChange={(e) => setPatientDiscountPct(Number(e.target.value) || 0)}
              className={BASE_INPUT}
            />
          </div>
          <div className="col-span-2">
            <label className={LABEL}>Empresa</label>
            <input
              type="text"
              value={worker?.companyName ?? ""}
              readOnly
              placeholder="—"
              className={READONLY_INPUT}
            />
          </div>
        </div>

        <div className="grid grid-cols-12 gap-3 mt-3">
          <div className="col-span-6">
            <LabOrderAutocomplete<DoctorSearchResult>
              label="Médico *"
              placeholder="Nombre del médico..."
              value={doctorPicked}
              onChange={(d) => {
                setDoctorPicked(d);
                if (d) setDoctorInput(d.name);
              }}
              fetchAction={async (q) => await searchDoctorsAction(q)}
              displayValue={(d) => d.name}
              renderItem={(d) => (
                <span>
                  <strong className="text-slate-800">{d.name}</strong>
                  {d.clave && <span className="ml-2 text-slate-500">{d.clave}</span>}
                </span>
              )}
            />
          </div>
          <div className="col-span-2">
            <label className={LABEL}>Clave</label>
            <input
              type="text"
              value={doctorClave}
              disabled={readOnly}
              onChange={(e) => setDoctorClave(e.target.value)}
              className={BASE_INPUT}
            />
          </div>
          <div className="col-span-2">
            <label className={LABEL}>Dto% Méd.</label>
            <input
              type="number"
              min={0}
              max={100}
              value={doctorDiscountPct}
              disabled={readOnly}
              onChange={(e) => setDoctorDiscountPct(Number(e.target.value) || 0)}
              className={BASE_INPUT}
            />
          </div>
          <div className="col-span-2">
            <label className={LABEL}>Comisión%</label>
            <input
              type="number"
              min={0}
              max={100}
              value={doctorCommissionPct}
              disabled={readOnly}
              onChange={(e) => setDoctorCommissionPct(Number(e.target.value) || 0)}
              className={BASE_INPUT}
            />
          </div>
        </div>

        <div className="grid grid-cols-12 gap-3 mt-3">
          <div className="col-span-6">
            <LabOrderAutocomplete<CompanySearchResult>
              label="Empresa (opcional)"
              placeholder="Razón social o RFC..."
              value={company}
              onChange={setCompany}
              fetchAction={async (q) => await searchCompaniesAction(q)}
              displayValue={(c) => c.name}
              renderItem={(c) => (
                <span>
                  <strong className="text-slate-800">{c.name}</strong>
                  {c.rfc && <span className="ml-2 text-slate-500">{c.rfc}</span>}
                </span>
              )}
            />
          </div>
          <div className="col-span-3">
            <label className={LABEL}>Dto% Empresa</label>
            <input
              type="number"
              min={0}
              max={100}
              value={companyDiscountPct}
              disabled={readOnly}
              onChange={(e) => setCompanyDiscountPct(Number(e.target.value) || 0)}
              className={BASE_INPUT}
            />
          </div>
          <div className="col-span-3">
            <label className={LABEL}>Clasificación</label>
            <input
              type="text"
              value={classificationId}
              disabled={readOnly}
              onChange={(e) => setClassificationId(e.target.value)}
              className={BASE_INPUT}
              placeholder="ID clasificación"
            />
          </div>
        </div>

        {/* IMPL-20260707-16: Slice C — Selector opcional de Papeleta Asociada */}
        <div className="grid grid-cols-12 gap-3 mt-3">
          <div className="col-span-12">
            <label className={LABEL}>
              Papeleta Asociada (opcional)
            </label>
            <input
              type="text"
              value={medicalEventId}
              disabled={readOnly}
              onChange={(e) => setMedicalEventId(e.target.value)}
              placeholder="ID de MedicalEvent (papeleta AMI)"
              className={BASE_INPUT}
            />
            {medicalEventId && (
              <p className="mt-1 text-xs text-blue-700">
                📎 Esta orden quedará vinculada a la papeleta:{" "}
                <a
                  href={`/events/${medicalEventId}`}
                  className="underline hover:text-blue-900"
                  target="_blank"
                  rel="noreferrer"
                >
                  {medicalEventId.slice(0, 12)}…
                </a>
              </p>
            )}
          </div>
        </div>

        <div className="mt-3">
          <label className={LABEL}>Observaciones</label>
          <textarea
            value={observations}
            disabled={readOnly}
            onChange={(e) => setObservations(e.target.value)}
            maxLength={2000}
            rows={2}
            className={BASE_INPUT}
          />
        </div>
      </div>

      <LabOrderStudiesTable items={items} onChange={setItems} readOnly={readOnly} />
      <LabOrderFlagsPanel value={flags} onChange={setFlags} readOnly={readOnly} />
      <LabOrderDeliveryPanel
        deliveryDate={delivery.deliveryDate}
        deliveryTime={delivery.deliveryTime}
        onChange={setDelivery}
        readOnly={readOnly}
      />
      <LabOrderTotalsPanel items={items} />

      <div className="flex flex-wrap justify-end gap-2">
        <button
          type="button"
          onClick={onSaveDraft}
          disabled={busy || readOnly}
          className="bg-slate-700 hover:bg-slate-800 text-white px-4 py-2 rounded-lg text-sm font-medium transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
        >
          Guardar Borrador
        </button>
        <button
          type="button"
          onClick={onConfirm}
          disabled={busy || readOnly || !worker || items.length === 0}
          className="bg-blue-600 hover:bg-blue-700 text-white px-4 py-2 rounded-lg text-sm font-medium transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
        >
          Confirmar y Generar Folio
        </button>
      </div>
      <p className="text-xs text-slate-500 italic">
        Para cancelar una orden DRAFT usa el botón × en el listado lateral.
      </p>
    </div>
  );
}

/**
 * @file Listado paginado de LabOrders (panel derecho en /lab/reception).
 * @id IMPL-20260701-03 — Slice B Recepción.
 *
 * Server Component: carga inicial vía listLabOrdersAction en mount.
 * Mantenerlo mínimo: tabla + paginación + acciones Ver/Editar/Cancelar.
 *
 * IMPL-20260706-02: refactor visual a paleta AMI.
 */
"use client";

import { useEffect, useState } from "react";
import { useRouter } from "next/navigation";
import {
  cancelLabOrderAction,
  getLabOrderAction,
  listLabOrdersAction,
} from "@/actions/lab-order.actions";

interface LabOrderRow {
  id: string;
  folio?: number | null;
  fecha?: string | null;
  paciente?: string | null;
  medico?: string | null;
  empresa?: string | null;
  total: number;
  status: string;
  itemCount?: number;
}

function statusBadge(status: string): string {
  switch (status) {
    case "DRAFT":
      return "bg-amber-100 text-amber-800";
    case "SAVED":
      return "bg-blue-100 text-blue-800";
    case "CANCELLED":
      return "bg-red-100 text-red-800";
    default:
      return "bg-slate-100 text-slate-800";
  }
}

export function LabOrdersList() {
  const router = useRouter();
  const [rows, setRows] = useState<LabOrderRow[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [draw, setDraw] = useState(1);
  const [length] = useState(25);
  const [start, setStart] = useState(0);
  const [recordsTotal, setRecordsTotal] = useState(0);
  const [search, setSearch] = useState("");
  const [busyId, setBusyId] = useState<string | null>(null);

  async function load() {
    setLoading(true);
    setError(null);
    const result = await listLabOrdersAction({
      draw,
      start,
      length,
      search: search || undefined,
    });
    if (!result.ok) {
      setError(result.error);
      setRows([]);
    } else {
      setRows(result.data.data as unknown as LabOrderRow[]);
      setRecordsTotal(result.data.recordsFiltered);
    }
    setLoading(false);
  }

  useEffect(() => {
    void load();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [draw, start]);

  async function onVer(id: string) {
    setBusyId(id);
    const res = await getLabOrderAction(id);
    setBusyId(null);
    if (res.ok) {
      router.push(`/lab/reception?orderId=${id}`);
    } else {
      alert(`No se pudo cargar: ${res.error}`);
    }
  }

  async function onCancelar(id: string) {
    const motivo = prompt("Motivo de cancelación (min 3 caracteres):");
    if (!motivo) return;
    setBusyId(id);
    const res = await cancelLabOrderAction(id, motivo);
    setBusyId(null);
    if (!res.ok) {
      alert(`Error: ${res.error}`);
    } else {
      void load();
    }
  }

  return (
    <div className="bg-white rounded-lg shadow-sm border border-slate-200 overflow-hidden">
      <div className="px-4 py-3 border-b border-slate-200 bg-slate-50 flex items-center justify-between">
        <h3 className="font-semibold text-sm text-slate-800">Órdenes recientes</h3>
        <span className="text-xs text-slate-500">{recordsTotal} total</span>
      </div>
      <div className="p-3 border-b border-slate-200">
        <input
          type="text"
          placeholder="Buscar paciente / folio / médico..."
          value={search}
          onChange={(e) => setSearch(e.target.value)}
          onKeyDown={(e) => {
            if (e.key === "Enter") {
              setDraw(1);
              setStart(0);
              void load();
            }
          }}
          className="w-full border border-slate-300 rounded-lg px-3 py-2 text-xs focus:outline-none focus:ring-2 focus:ring-blue-500"
        />
      </div>
      {error && (
        <div className="px-4 py-2 text-xs text-red-700 bg-red-50 border-b border-red-200">
          {error}
        </div>
      )}
      <div className="overflow-x-auto">
        <table className="w-full text-xs text-slate-700">
          <thead className="bg-slate-50 border-b border-slate-200">
            <tr>
              <th className="px-3 py-2 text-left text-xs font-semibold text-slate-600 uppercase tracking-wider">
                Folio
              </th>
              <th className="px-3 py-2 text-left text-xs font-semibold text-slate-600 uppercase tracking-wider">
                Paciente
              </th>
              <th className="px-3 py-2 text-right text-xs font-semibold text-slate-600 uppercase tracking-wider">
                Total
              </th>
              <th className="px-3 py-2 text-center text-xs font-semibold text-slate-600 uppercase tracking-wider">
                Estado
              </th>
              <th className="px-3 py-2 text-center text-xs font-semibold text-slate-600 uppercase tracking-wider">
                Acciones
              </th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100">
            {loading && (
              <tr>
                <td colSpan={5} className="px-3 py-6 text-center text-slate-500 italic">
                  Cargando…
                </td>
              </tr>
            )}
            {!loading && rows.length === 0 && (
              <tr>
                <td colSpan={5} className="px-3 py-6 text-center text-slate-500 italic">
                  Sin órdenes. Crea una con el formulario.
                </td>
              </tr>
            )}
            {rows.map((r) => (
              <tr key={r.id} className="hover:bg-slate-50">
                <td className="px-3 py-2 font-mono text-slate-600">{r.folio ?? "—"}</td>
                <td className="px-3 py-2 text-slate-800">{r.paciente ?? "—"}</td>
                <td className="px-3 py-2 text-right">
                  ${Number(r.total ?? 0).toFixed(2)}
                </td>
                <td className="px-3 py-2 text-center">
                  <span
                    className={`px-2 py-0.5 rounded text-[10px] font-semibold ${statusBadge(
                      r.status
                    )}`}
                  >
                    {r.status}
                  </span>
                </td>
                <td className="px-3 py-2 text-center space-x-2 whitespace-nowrap">
                  <button
                    type="button"
                    onClick={() => onVer(r.id)}
                    disabled={busyId === r.id}
                    className="text-blue-600 hover:text-blue-800 font-medium"
                    title="Ver"
                  >
                    Ver
                  </button>
                  {r.status === "DRAFT" && (
                    <button
                      type="button"
                      onClick={() => router.push(`/lab/reception?edit=${r.id}`)}
                      className="text-amber-700 hover:text-amber-900 font-medium"
                      title="Editar"
                    >
                      Editar
                    </button>
                  )}
                  {r.status === "DRAFT" && (
                    <button
                      type="button"
                      onClick={() => onCancelar(r.id)}
                      disabled={busyId === r.id}
                      className="text-red-600 hover:text-red-800 font-medium"
                      title="Cancelar"
                    >
                      ×
                    </button>
                  )}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
      <div className="p-3 border-t border-slate-200 flex items-center justify-between text-xs">
        <button
          type="button"
          onClick={() => {
            setStart(Math.max(0, start - length));
            setDraw(draw + 1);
          }}
          disabled={start === 0}
          className="px-3 py-1 border border-slate-300 rounded-lg bg-white text-slate-700 disabled:opacity-50 hover:bg-slate-50 transition-colors"
        >
          ← Anterior
        </button>
        <span className="text-slate-500">
          {start + 1} – {Math.min(start + length, recordsTotal)}
        </span>
        <button
          type="button"
          onClick={() => {
            if (start + length < recordsTotal) {
              setStart(start + length);
              setDraw(draw + 1);
            }
          }}
          disabled={start + length >= recordsTotal}
          className="px-3 py-1 border border-slate-300 rounded-lg bg-white text-slate-700 disabled:opacity-50 hover:bg-slate-50 transition-colors"
        >
          Siguiente →
        </button>
      </div>
    </div>
  );
}

/**
 * @file Fallback de admisión manual para /lab/reception?mode=manual.
 * @id IMPL-20260707-17 — Fase 1 NOVA absorción (ARCH-20260707-17) — B-v2.
 *
 * Wrapper delgado sobre LabOrderForm (que ya soporta admisión completa).
 * Usado cuando el paciente NO tiene papeleta (walk-in externo).
 */
"use client";

import { LabOrderForm } from "./LabOrderForm";

interface Props {
  orderId?: string;
}

export function ManualAdmissionForm({ orderId }: Props) {
  return (
    <div className="space-y-3">
      <div className="rounded-lg border border-amber-200 bg-amber-50 px-4 py-3 text-xs text-amber-800">
        <strong>Modo admisión manual.</strong>{" "}
        Use este formulario solo para pacientes sin papeleta previa (walk-in externo).
        Para admisiones automáticas use la <a href="/lab/reception" className="underline">bandeja de papeletas</a>.
      </div>
