/**
 * @file Cliente principal de /lab/results — orquesta filtros + tabla de órdenes + tabs.
 * @id IMPL-20260707-16 — Slice C Resultados.
 */
"use client";

import { useCallback, useEffect, useState } from "react";
import Link from "next/link";
import { useRouter, useSearchParams } from "next/navigation";
import { getLabResultsAction } from "@/actions/lab-result.actions";
import type { LabResultStatus } from "@/lib/validations/lab-result";
import { getStatusColor, getStatusLabel } from "@/lib/lab-result-utils";

interface Props {
  initialStatus: string;
}

const TABS: { key: LabResultStatus; label: string }[] = [
  { key: "PENDING", label: "Pendientes" },
  { key: "REPORTED", label: "Reportados" },
  { key: "AUTHORIZED", label: "Autorizados" },
  { key: "VALIDATED", label: "Validados" },
  { key: "INVALIDATED", label: "Inválidos" },
];

interface ResultRow {
  id: string;
  status: LabResultStatus;
  valueNumber: number | null;
  valueText: string | null;
  analyteCode: string | null;
  analyteName: string | null;
  unitSymbol: string | null;
  isOutOfRange: boolean;
  isCritical: boolean;
  createdAt: string;
}

export function LabResultsClient({ initialStatus }: Props) {
  const router = useRouter();
  const searchParams = useSearchParams();
  const [status, setStatus] = useState<LabResultStatus>(
    (initialStatus as LabResultStatus) || "PENDING"
  );
  const [rows, setRows] = useState<ResultRow[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [search, setSearch] = useState("");
  const [folioFilter, setFolioFilter] = useState("");

  const refresh = useCallback(async () => {
    setLoading(true);
    setError(null);
    const res = await getLabResultsAction({
      draw: 1,
      start: 0,
      length: 50,
      search: folioFilter,
      status,
    });
    setLoading(false);
    if (!res.ok) {
      setError(res.error);
      setRows([]);
      return;
    }
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    setRows(res.data.data as any);
  }, [status, folioFilter]);

  useEffect(() => {
    refresh();
  }, [refresh]);

  function handleStatusChange(next: LabResultStatus) {
    setStatus(next);
    const params = new URLSearchParams(searchParams.toString());
    params.set("status", next);
    router.replace(`/lab/results?${params.toString()}`);
  }

  const filtered = search
    ? rows.filter((r) => {
        const q = search.toLowerCase();
        return (
          (r.analyteCode ?? "").toLowerCase().includes(q) ||
          (r.analyteName ?? "").toLowerCase().includes(q) ||
          (r.valueText ?? "").toLowerCase().includes(q)
        );
      })
    : rows;

  return (
    <div className="space-y-4">
      {/* Tabs */}
      <div className="border-b border-slate-200">
        <nav className="flex gap-1 overflow-x-auto">
          {TABS.map((t) => {
            const active = status === t.key;
            return (
              <button
                key={t.key}
                type="button"
                onClick={() => handleStatusChange(t.key)}
                className={`px-4 py-2 text-sm font-medium border-b-2 transition-colors ${
                  active
                    ? "border-blue-600 text-blue-700"
                    : "border-transparent text-slate-600 hover:text-slate-800 hover:border-slate-300"
                }`}
              >
                {t.label}
              </button>
            );
          })}
        </nav>
      </div>

      {/* Filtros */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-3">
        <div>
          <label className="block text-xs font-medium text-slate-700 mb-1">Buscar</label>
          <input
            type="text"
            placeholder="Analito o valor..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            className="w-full border border-slate-300 rounded-lg px-3 py-2 text-sm bg-white focus:outline-none focus:ring-2 focus:ring-blue-500"
          />
        </div>
        <div>
          <label className="block text-xs font-medium text-slate-700 mb-1">Folio LabOrder</label>
          <input
            type="number"
            placeholder="Ej. 1001"
            value={folioFilter}
            onChange={(e) => setFolioFilter(e.target.value)}
            className="w-full border border-slate-300 rounded-lg px-3 py-2 text-sm bg-white focus:outline-none focus:ring-2 focus:ring-blue-500"
          />
        </div>
        <div className="flex items-end">
          <button
            type="button"
            onClick={refresh}
            disabled={loading}
            className="bg-slate-700 hover:bg-slate-800 text-white px-4 py-2 rounded-lg text-sm font-medium transition-colors disabled:opacity-50"
          >
            {loading ? "Cargando..." : "Refrescar"}
          </button>
        </div>
      </div>

      {error && (
        <div className="rounded-lg border border-red-200 bg-red-50 px-3 py-2 text-xs text-red-700">
          {error}
        </div>
      )}

      {/* Tabla */}
      <div className="bg-white rounded-lg shadow-sm border border-slate-200 overflow-hidden">
        <table className="w-full text-sm">
          <thead className="bg-slate-50 text-slate-700 text-xs uppercase tracking-wider">
            <tr>
              <th className="px-3 py-2 text-left">Estado</th>
              <th className="px-3 py-2 text-left">Analito</th>
              <th className="px-3 py-2 text-left">Valor</th>
              <th className="px-3 py-2 text-left">Unidad</th>
              <th className="px-3 py-2 text-left">Flags</th>
              <th className="px-3 py-2 text-left">Capturado</th>
              <th className="px-3 py-2 text-left">Acciones</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100">
            {filtered.length === 0 && (
              <tr>
                <td colSpan={7} className="px-3 py-6 text-center text-slate-500 text-sm">
                  {loading ? "Cargando..." : "Sin resultados para este estado"}
                </td>
              </tr>
            )}
            {filtered.map((r) => (
              <tr key={r.id} className="hover:bg-slate-50">
                <td className="px-3 py-2">
                  <span
                    className={`inline-flex items-center px-2 py-0.5 text-xs font-medium rounded border ${getStatusColor(
                      r.status
                    )}`}
                  >
                    {getStatusLabel(r.status)}
                  </span>
                </td>
                <td className="px-3 py-2">
                  <div className="font-medium text-slate-800">{r.analyteCode ?? "—"}</div>
                  <div className="text-xs text-slate-500">{r.analyteName ?? ""}</div>
                </td>
                <td className="px-3 py-2 font-mono">
                  {r.valueNumber !== null && r.valueNumber !== undefined
                    ? r.valueNumber
                    : r.valueText ?? "—"}
                </td>
                <td className="px-3 py-2 text-slate-600">{r.unitSymbol ?? "—"}</td>
                <td className="px-3 py-2">
                  {r.isCritical && (
                    <span className="inline-block px-2 py-0.5 text-xs font-semibold rounded bg-red-100 text-red-800 border border-red-300">
                      CRÍTICO
                    </span>
                  )}
                  {!r.isCritical && r.isOutOfRange && (
                    <span className="inline-block px-2 py-0.5 text-xs font-semibold rounded bg-amber-100 text-amber-800 border border-amber-300">
                      FUERA DE RANGO
                    </span>
                  )}
                  {!r.isOutOfRange && !r.isCritical && (
                    <span className="inline-block px-2 py-0.5 text-xs text-slate-500">
                      Normal
                    </span>
                  )}
                </td>
                <td className="px-3 py-2 text-xs text-slate-500">
                  {r.createdAt ? new Date(r.createdAt).toLocaleString() : "—"}
                </td>
                <td className="px-3 py-2">
                  <Link
                    href={`/lab/results/order/${r.id}`}
                    className="text-blue-600 hover:text-blue-800 text-xs font-medium"
                  >
                    Ver
                  </Link>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      <p className="text-xs text-slate-500 italic">
        Para ver el detalle de una orden con todos sus analitos, ve a{" "}
        <Link href="/lab/reception" className="text-blue-600 hover:underline">
          Recepción
        </Link>{" "}
        y selecciona una LabOrder confirmada.
      </p>
    </div>
  );
}

/**
 * @file Timeline de trazabilidad de LabOrder (D — Fase 2 NOVA).
 * @id IMPL-20260707-18
 * @backup context/SPECs/SPEC_IMPL-20260707-SLICES-D-G-FINAL.md §2
 *
 * Muestra cronológicamente los LabTraceEvent de la LabOrder con badges
 * de color por tipo. Carga vía getLabTraceAction y soporta recargar
 * con `refreshKey`.
 */
"use client";

import { useCallback, useEffect, useState } from "react";
import {
  getLabTraceAction,
  type LabTraceEventRow,
} from "@/actions/lab-trace.actions";

interface Props {
  orderId: string;
  refreshKey?: number;
}

const EVENT_LABEL: Record<string, string> = {
  SAMPLE_RECEIVED: "Muestra recibida",
  PROCESS_STARTED: "Proceso iniciado",
  ANALYSIS_DONE: "Análisis terminado",
  VALIDATED: "Validado",
  DELIVERED: "Entregado",
};

const EVENT_COLOR: Record<string, string> = {
  SAMPLE_RECEIVED: "bg-sky-100 text-sky-800 border-sky-300",
  PROCESS_STARTED: "bg-indigo-100 text-indigo-800 border-indigo-300",
  ANALYSIS_DONE: "bg-blue-100 text-blue-800 border-blue-300",
  VALIDATED: "bg-emerald-100 text-emerald-800 border-emerald-300",
  DELIVERED: "bg-teal-100 text-teal-800 border-teal-300",
};

const EVENT_ICON: Record<string, string> = {
  SAMPLE_RECEIVED: "🧪",
  PROCESS_STARTED: "⚙️",
  ANALYSIS_DONE: "🔬",
  VALIDATED: "✅",
  DELIVERED: "📤",
};

export function LabTraceTimeline({ orderId, refreshKey = 0 }: Props) {
  const [rows, setRows] = useState<LabTraceEventRow[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const load = useCallback(async () => {
    setLoading(true);
    setError(null);
    const res = await getLabTraceAction(orderId);
    setLoading(false);
    if (!res.ok) {
      setError(res.error);
      setRows([]);
      return;
    }
    setRows(res.data.rows);
  }, [orderId]);

  useEffect(() => {
    load();
  }, [load, refreshKey]);

  return (
    <div className="bg-white rounded-lg shadow-sm border border-slate-200 p-4">
      <div className="flex items-center justify-between mb-3">
        <h3 className="text-base font-semibold text-slate-800">
          Trazabilidad operativa
        </h3>
        <span className="text-[10px] uppercase tracking-wider text-slate-400 font-mono">
          {rows.length} evento{rows.length === 1 ? "" : "s"}
        </span>
      </div>

      {error && (
        <div className="rounded-lg border border-red-200 bg-red-50 px-3 py-2 text-xs text-red-700 mb-3">
          {error}
        </div>
      )}

      {loading && rows.length === 0 && (
        <p className="text-xs text-slate-500">Cargando eventos...</p>
      )}

      {!loading && rows.length === 0 && !error && (
        <p className="text-xs text-slate-500">
          Aún no hay eventos registrados. El primero se crea automáticamente al
          confirmar la orden (SAMPLE_RECEIVED).
        </p>
      )}

      <ol className="relative space-y-3 border-l-2 border-slate-200 pl-4">
        {rows.map((r) => {
          const label = EVENT_LABEL[r.event] ?? r.event;
          const color = EVENT_COLOR[r.event] ?? "bg-slate-100 text-slate-700 border-slate-300";
          const icon = EVENT_ICON[r.event] ?? "•";
          return (
            <li key={r.id} className="relative">
              <span className="absolute -left-[22px] top-0.5 w-4 h-4 rounded-full bg-white border-2 border-slate-300 flex items-center justify-center text-[9px]">
                {icon}
              </span>
              <div className="flex flex-wrap items-center gap-2">
                <span
                  className={`inline-flex items-center px-2 py-0.5 text-[11px] font-medium rounded border ${color}`}
                >
                  {label}
                </span>
                <span className="text-[11px] text-slate-500 font-mono">
                  {new Date(r.timestamp).toLocaleString()}
                </span>
              </div>
              <div className="mt-1 text-[11px] text-slate-600 space-y-0.5">
                {r.userFullName && (
                  <div>
                    <span className="text-slate-400">por</span>{" "}
                    <span className="font-medium text-slate-700">{r.userFullName}</span>
                  </div>
                )}
                {r.location && (
                  <div>
                    <span className="text-slate-400">lugar:</span>{" "}
                    <span className="font-mono">{r.location}</span>
                  </div>
                )}
                {r.notes && (
                  <div className="italic text-slate-600">
                    <span className="text-slate-400 not-italic">notas:</span> {r.notes}
                  </div>
                )}
              </div>
            </li>
          );
        })}
      </ol>
    </div>
  );
}

/**
 * @file Sección de pagos para una LabOrder (Fase 3 NOVA — G Caja).
 * @id IMPL-20260708-19
 * @backup context/SPECs/SPEC_IMPL-20260707-SLICES-D-G-FINAL.md §2 (FASE 3)
 *
 * Lista los pagos existentes de la LabOrder + botón "Registrar pago"
 * (modal) + total pendiente.
 */
"use client";

import { useCallback, useEffect, useState } from "react";
import {
  getLabPaymentsAction,
  registerLabPaymentAction,
  type CashPaymentsSummary,
} from "@/actions/lab-cash.actions";
import {
  PAYMENT_METHODS,
  PAYMENT_METHOD_LABEL,
  type PaymentMethod,
} from "@/lib/validations/lab-cash";

interface Props {
  orderId: string;
  refreshKey?: number;
}

export function PaymentSection({ orderId, refreshKey = 0 }: Props) {
  const [summary, setSummary] = useState<CashPaymentsSummary | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [message, setMessage] = useState<string | null>(null);
  const [showModal, setShowModal] = useState(false);

  const load = useCallback(async () => {
    setLoading(true);
    setError(null);
    const res = await getLabPaymentsAction(orderId);
    setLoading(false);
    if (!res.ok) {
      setError(res.error);
      setSummary(null);
      return;
    }
    setSummary(res.data);
  }, [orderId]);

  useEffect(() => {
    load();
  }, [load, refreshKey]);

  return (
    <div className="bg-white rounded-lg shadow-sm border border-slate-200 p-4">
      <div className="flex flex-wrap items-center justify-between gap-2 mb-3">
        <h3 className="text-base font-semibold text-slate-800">Pagos</h3>
        <button
          type="button"
          onClick={() => setShowModal(true)}
          className="px-3 py-1.5 text-xs font-medium rounded bg-emerald-600 text-white hover:bg-emerald-700"
        >
          + Registrar pago
        </button>
      </div>

      {error && (
        <div className="rounded-lg border border-red-200 bg-red-50 px-3 py-2 text-xs text-red-700 mb-3">
          {error}
        </div>
      )}
      {message && (
        <div className="rounded-lg border border-emerald-200 bg-emerald-50 px-3 py-2 text-xs text-emerald-700 mb-3">
          {message}
        </div>
      )}

      {loading && !summary && (
        <p className="text-xs text-slate-500">Cargando pagos...</p>
      )}

      {summary && (
        <>
          {/* Totales */}
          <div className="grid grid-cols-3 gap-2 mb-3 text-center">
            <div className="bg-slate-50 rounded p-2">
              <div className="text-[10px] uppercase tracking-wider text-slate-500">Total</div>
              <div className="text-sm font-bold text-slate-800">${summary.orderTotal.toFixed(2)}</div>
            </div>
            <div className="bg-emerald-50 rounded p-2">
              <div className="text-[10px] uppercase tracking-wider text-emerald-700">Cobrado</div>
              <div className="text-sm font-bold text-emerald-700">${summary.paidTotal.toFixed(2)}</div>
            </div>
            <div className={`${summary.balance > 0 ? "bg-red-50" : "bg-slate-50"} rounded p-2`}>
              <div className={`text-[10px] uppercase tracking-wider ${summary.balance > 0 ? "text-red-700" : "text-slate-500"}`}>
                Pendiente
              </div>
              <div className={`text-sm font-bold ${summary.balance > 0 ? "text-red-700" : "text-slate-800"}`}>
                ${summary.balance.toFixed(2)}
              </div>
            </div>
          </div>

          {/* Lista de pagos */}
          {summary.rows.length === 0 ? (
            <p className="text-xs text-slate-500 italic">Aún no hay pagos registrados.</p>
          ) : (
            <ul className="space-y-2">
              {summary.rows.map((r) => (
                <li
                  key={r.id}
                  className="flex items-center justify-between gap-2 px-3 py-2 bg-slate-50 rounded border border-slate-200"
                >
                  <div className="flex-1">
                    <div className="text-xs font-medium text-slate-800">
                      {PAYMENT_METHOD_LABEL[r.method as PaymentMethod] ?? r.method}
                      {r.reference && (
                        <span className="ml-2 text-[10px] text-slate-500 font-mono">
                          ref: {r.reference}
                        </span>
                      )}
                    </div>
                    <div className="text-[10px] text-slate-500">
                      {new Date(r.createdAt).toLocaleString()}
                      {r.userFullName && <> · por {r.userFullName}</>}
                    </div>
                  </div>
                  <div className="text-sm font-bold text-slate-800">${r.amount.toFixed(2)}</div>
                </li>
              ))}
            </ul>
          )}
        </>
      )}

      {showModal && summary && (
        <PaymentModal
          orderId={orderId}
          defaultAmount={Math.max(0, summary.balance)}
          onClose={() => setShowModal(false)}
          onSaved={async () => {
            setShowModal(false);
            setMessage("Pago registrado.");
            await load();
          }}
        />
      )}
    </div>
  );
}

// ---------------------------------------------------------------------------
// Modal: registrar pago
// ---------------------------------------------------------------------------
function PaymentModal({
  orderId,
  defaultAmount,
  onClose,
  onSaved,
}: {
  orderId: string;
  defaultAmount: number;
  onClose: () => void;
  onSaved: () => void | Promise<void>;
}) {
  const [amount, setAmount] = useState<string>(defaultAmount > 0 ? defaultAmount.toFixed(2) : "");
  const [method, setMethod] = useState<PaymentMethod>("CASH");
  const [reference, setReference] = useState<string>("");
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    setError(null);
    const numAmount = Number(amount);
    if (!Number.isFinite(numAmount) || numAmount <= 0) {
      setError("El monto debe ser un número mayor a 0.");
      return;
    }
    setBusy(true);
    const res = await registerLabPaymentAction(orderId, {
      amount: numAmount,
      method,
      reference: reference.trim() || null,
    });
    setBusy(false);
    if (!res.ok) {
      setError(res.error);
      return;
    }
    await onSaved();
  }

  return (
    <div className="fixed inset-0 z-50 bg-black/40 flex items-center justify-center p-4">
      <div className="bg-white rounded-lg shadow-xl border border-slate-200 w-full max-w-md p-5">
        <h3 className="text-base font-semibold text-slate-800 mb-3">Registrar pago</h3>
        <form onSubmit={handleSubmit} className="space-y-3">
          <div>
            <label className="block text-xs font-medium text-slate-700 mb-1">Monto (MXN)</label>
            <input
              type="number"
              step="0.01"
              min="0"
              value={amount}
              onChange={(e) => setAmount(e.target.value)}
              required
              autoFocus
              className="w-full px-3 py-2 text-sm border border-slate-300 rounded focus:outline-none focus:ring-2 focus:ring-emerald-500"
            />
          </div>
          <div>
            <label className="block text-xs font-medium text-slate-700 mb-1">Forma de pago</label>
            <select
              value={method}
              onChange={(e) => setMethod(e.target.value as PaymentMethod)}
              className="w-full px-3 py-2 text-sm border border-slate-300 rounded focus:outline-none focus:ring-2 focus:ring-emerald-500"
            >
              {PAYMENT_METHODS.map((m) => (
                <option key={m} value={m}>
                  {PAYMENT_METHOD_LABEL[m]}
                </option>
              ))}
            </select>
          </div>
          <div>
            <label className="block text-xs font-medium text-slate-700 mb-1">
              Referencia (opcional)
            </label>
            <input
              type="text"
              value={reference}
              onChange={(e) => setReference(e.target.value)}
              placeholder="Ej. últimos 4 dígitos, SPEI ref, cheque #"
              maxLength={200}
              className="w-full px-3 py-2 text-sm border border-slate-300 rounded focus:outline-none focus:ring-2 focus:ring-emerald-500"
            />
          </div>
          {error && (
            <div className="rounded border border-red-200 bg-red-50 px-3 py-2 text-xs text-red-700">
              {error}
            </div>
          )}
          <div className="flex justify-end gap-2 pt-2">
            <button
              type="button"
              onClick={onClose}
              disabled={busy}
              className="px-3 py-1.5 text-xs font-medium rounded border border-slate-300 text-slate-700 hover:bg-slate-50"
            >
              Cancelar
            </button>
            <button
              type="submit"
              disabled={busy}
              className="px-3 py-1.5 text-xs font-medium rounded bg-emerald-600 text-white hover:bg-emerald-700 disabled:opacity-50"
            >
              {busy ? "Guardando..." : "Registrar"}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}

/**
 * @file Vista principal del worklist: tabla de analitos + acciones P/R/A/V.
 * @id IMPL-20260707-16 — Slice C Resultados.
 */
"use client";

import { useCallback, useEffect, useState } from "react";
import {
  bulkCreateLabResultsAction,
  getWorklistAction,
  transitionLabResultAction,
} from "@/actions/lab-result.actions";
import { WorklistTable, type WorklistAnalyte } from "./WorklistTable";
import { LabResultAuditTimeline } from "./LabResultAuditTimeline";

interface OrderHeader {
  id: string;
  folio: number | null;
  status: string;
  urgency: string;
  confidentiality: string;
  patientName: string;
  patientCode: string;
  companyName: string | null;
  medicalEventId: string | null;
  doctorName: string;
  createdAt: string | null;
  items: Array<{ id: string; code: string; name: string }>;
}

interface WorklistItem {
  labOrderItemId: string;
  medicalTestId: string;
  medicalTestCode: string;
  medicalTestName: string;
  analytes: WorklistAnalyte[];
}

interface Props {
  orderId: string;
  header: OrderHeader;
}

export function WorklistView({ orderId, header }: Props) {
  const [items, setItems] = useState<WorklistItem[]>([]);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [message, setMessage] = useState<string | null>(null);
  const [refreshKey, setRefreshKey] = useState(0);

  const refresh = useCallback(async () => {
    const res = await getWorklistAction(orderId);
    if (!res.ok) {
      setError(res.error);
      setItems([]);
      return;
    }
    setItems(res.data.items as WorklistItem[]);
  }, [orderId]);

  useEffect(() => {
    refresh();
  }, [refresh, refreshKey]);

  async function handleBulkSave(
    payloads: Array<{
      labOrderItemId: string;
      analyteId: string;
      valueText?: string | null;
      valueNumber?: number | null;
    }>
  ) {
    if (payloads.length === 0) return;
    setBusy(true);
    setError(null);
    setMessage(null);
    const res = await bulkCreateLabResultsAction({ items: payloads });
    setBusy(false);
    if (!res.ok) {
      setError(res.error);
      return;
    }
    setMessage(`${res.data.created} resultado(s) capturado(s).`);
    setRefreshKey((k) => k + 1);
  }

  async function handleTransition(
    resultId: string,
    action: "report" | "authorize" | "validate" | "invalidate",
    reason?: string
  ) {
    setBusy(true);
    setError(null);
    setMessage(null);
    const res = await transitionLabResultAction(resultId, {
      action,
      reason: reason ?? undefined,
    });
    setBusy(false);
    if (!res.ok) {
      setError(res.error);
      return;
    }
    setMessage(`Transición aplicada. Nuevo estado: ${res.data.newStatus}`);
    setRefreshKey((k) => k + 1);
  }

  return (
    <div className="space-y-4">
      {/* Cabecera */}
      <div className="bg-white rounded-lg shadow-sm border border-slate-200 p-4">
        <div className="grid grid-cols-12 gap-3 text-sm">
          <div className="col-span-6">
            <div className="text-xs text-slate-500">Paciente</div>
            <div className="font-medium text-slate-800">
              {header.patientName} [{header.patientCode}]
            </div>
          </div>
          <div className="col-span-3">
            <div className="text-xs text-slate-500">Médico</div>
            <div className="font-medium text-slate-800">{header.doctorName}</div>
          </div>
          <div className="col-span-3">
            <div className="text-xs text-slate-500">Estado Orden</div>
            <div className="font-medium text-slate-800">{header.status}</div>
          </div>
        </div>
        {header.medicalEventId && (
          <div className="mt-3 p-3 bg-blue-50 border border-blue-200 rounded-lg text-sm">
            <span className="text-blue-800">
              📎 Vinculado a papeleta AMI:{" "}
              <a
                href={`/events/${header.medicalEventId}`}
                className="font-medium underline hover:text-blue-900"
              >
                {header.medicalEventId.slice(0, 8)}…
              </a>
            </span>
          </div>
        )}
      </div>

      {error && (
        <div className="rounded-lg border border-red-200 bg-red-50 px-3 py-2 text-xs text-red-700">
          {error}
        </div>
      )}
      {message && (
        <div className="rounded-lg border border-emerald-200 bg-emerald-50 px-3 py-2 text-xs text-emerald-700">
          {message}
        </div>
      )}

      {items.map((item) => (
        <WorklistTable
          key={item.labOrderItemId}
          item={item}
          busy={busy}
          onBulkSave={handleBulkSave}
          onTransition={handleTransition}
        />
      ))}

      <LabResultAuditTimeline orderId={orderId} refreshKey={refreshKey} />
    </div>
  );
}

/**
 * @file Dashboard operativo de unidades móviles — /operations/mobile-units.
 * @id IMPL-20260711-01 — SPEC §5.6
 *
 * Server component: contadores, próximos mantenimientos (7 días), unidades con
 * mantenimiento vencido, conflictos recientes, calendario semanal dual
 * (proyectos + mantenimientos) y tabla simple de utilización.
 */
import prisma from '@/lib/prisma'
import type { Prisma } from '@prisma/client'
import Link from 'next/link'

// Tipos locales para tipar las listas
type UnitWithCount = Prisma.MobileUnitGetPayload<{
  include: { _count: { select: { projects: true; maintenances: true } } }
}>
type MaintenanceWithUnit = Prisma.MaintenanceRecordGetPayload<{
  include: { mobileUnit: { select: { name: true; plate: true } } }
}>
type ProjectWithUnit = Prisma.ProjectGetPayload<{
  include: {
    mobileUnit: { select: { name: true; plate: true } }
    company: { select: { name: true } }
  }
}>

export const dynamic = 'force-dynamic'

const STATUS_LABEL: Record<string, { label: string; color: string }> = {
  ACTIVA: { label: 'Activa', color: 'bg-emerald-100 text-emerald-800 border-emerald-300' },
  MANTENIMIENTO: { label: 'Mantenimiento', color: 'bg-amber-100 text-amber-800 border-amber-300' },
  REPARACION: { label: 'Reparación', color: 'bg-red-100 text-red-800 border-red-300' },
  FUERA_SERVICIO: { label: 'Fuera de servicio', color: 'bg-slate-200 text-slate-700 border-slate-300' },
  BAJA_PERMANENTE: { label: 'Baja permanente', color: 'bg-zinc-300 text-zinc-700 border-zinc-400' },
}

function startOfWeek(d: Date) {
  const x = new Date(d)
  x.setHours(0, 0, 0, 0)
  x.setDate(x.getDate() - x.getDay())
  return x
}
function endOfWeek(d: Date) {
  const x = new Date(d)
  x.setHours(23, 59, 59, 999)
  x.setDate(x.getDate() + (6 - x.getDay()))
  return x
}

export default async function OperationsMobileUnitsPage() {
  // Prisma client directo (server component fuera del scope de actions).
  // Si @/lib/prisma-shim no existe, fallback a @/lib/prisma default.
  const prismaClient = prisma
  const now = new Date()
  const weekStart = startOfWeek(now)
  const weekEnd = endOfWeek(now)
  const in7Days = new Date(now.getTime() + 7 * 86400_000)

  const [
    allUnitsRaw,
    upcomingMaintenancesRaw,
    overdueMaintenancesRaw,
    weekProjectsRaw,
    weekMaintenancesRaw,
  ] = await Promise.all([
    prismaClient.mobileUnit.findMany({
      include: {
        _count: { select: { projects: true, maintenances: true } },
      },
      orderBy: { name: 'asc' },
    }),
    prismaClient.maintenanceRecord.findMany({
      where: {
        status: { in: ['PROGRAMADO', 'REPROGRAMADO'] },
        scheduledDate: { gte: now, lte: in7Days },
      },
      include: { mobileUnit: { select: { name: true, plate: true } } },
      orderBy: { scheduledDate: 'asc' },
    }),
    prismaClient.maintenanceRecord.findMany({
      where: {
        status: { in: ['PROGRAMADO', 'REPROGRAMADO'] },
        scheduledDate: { lt: now },
      },
      include: { mobileUnit: { select: { name: true } } },
      orderBy: { scheduledDate: 'asc' },
    }),
    prismaClient.project.findMany({
      where: {
        NOT: { status: 'CANCELLED' },
        AND: [{ startDate: { lte: weekEnd } }, { endDate: { gte: weekStart } }],
        mobileUnitId: { not: null },
      },
      include: {
        mobileUnit: { select: { name: true, plate: true } },
        company: { select: { name: true } },
      },
    }),
    prismaClient.maintenanceRecord.findMany({
      where: {
        status: { in: ['PROGRAMADO', 'REPROGRAMADO'] },
        scheduledDate: { gte: weekStart, lte: weekEnd },
      },
      include: { mobileUnit: { select: { name: true } } },
    }),
  ])

  const allUnits = allUnitsRaw as UnitWithCount[]
  const upcomingMaintenances = upcomingMaintenancesRaw as MaintenanceWithUnit[]
  const overdueMaintenances = overdueMaintenancesRaw as MaintenanceWithUnit[]
  const weekProjects = weekProjectsRaw as ProjectWithUnit[]
  const weekMaintenances = weekMaintenancesRaw as MaintenanceWithUnit[] 

  const statusCounts: Record<string, number> = {}
  for (const u of allUnits) {
    statusCounts[u.status] = (statusCounts[u.status] ?? 0) + 1
  }

  // Conflictos detectados esta semana: proyectos y mantenimientos del mismo día/unidad
  type Conflict = { unit: string; date: string; project: string; maintenance: string }
  const conflicts: Conflict[] = []
  for (const m of weekMaintenances) {
    const mDate = new Date(m.scheduledDate)
    mDate.setHours(0, 0, 0, 0)
    const mEnd = new Date(m.scheduledDate)
    mEnd.setHours(23, 59, 59, 999)
    const clashing = weekProjects.filter((p: typeof weekProjects[number]) => {
      if (p.mobileUnitId !== m.mobileUnitId) return false
      return new Date(p.startDate) <= mEnd && new Date(p.endDate) >= mDate
    })
    for (const p of clashing) {
      conflicts.push({
        unit: m.mobileUnit.name,
        date: new Date(m.scheduledDate).toLocaleDateString('es-MX'),
        project: p.name,
        maintenance: m.type,
      })
    }
  }

  // Heatmap semanal: por unidad y por día
  const days = Array.from({ length: 7 }).map((_, i) => {
    const d = new Date(weekStart)
    d.setDate(weekStart.getDate() + i)
    return d
  })

  return (
    <div className="p-6 space-y-6">
      <header>
        <h1 className="text-2xl font-semibold">Operaciones · Unidades Móviles</h1>
        <p className="text-sm text-slate-600">Vista operativa semanal, métricas y conflictos.</p>
      </header>

      <section>
        <h2 className="text-sm font-medium text-slate-600 mb-2">Estado operativo</h2>
        <div className="grid grid-cols-2 md:grid-cols-5 gap-3">
          {['ACTIVA', 'MANTENIMIENTO', 'REPARACION', 'FUERA_SERVICIO', 'BAJA_PERMANENTE'].map((s) => {
            const meta = STATUS_LABEL[s]
            const count = statusCounts[s] ?? 0
            return (
              <div key={s} className={`border rounded-lg p-3 ${meta.color.replace('text-', 'text-').replace('bg-', 'bg-')}`}>
                <p className="text-xs uppercase tracking-wide opacity-80">{meta.label}</p>
                <p className="text-2xl font-bold">{count}</p>
              </div>
            )
          })}
        </div>
      </section>

      <section className="grid grid-cols-1 md:grid-cols-2 gap-4">
        <div className="border rounded-lg p-3">
          <h3 className="text-sm font-medium mb-2">Próximos mantenimientos (7 días)</h3>
          {upcomingMaintenances.length === 0 ? (
            <p className="text-sm text-slate-500">Sin mantenimientos próximos.</p>
          ) : (
            <ul className="space-y-2 text-sm">
              {upcomingMaintenances.map((m) => (
                <li key={m.id} className="flex justify-between items-center border-b pb-1 last:border-b-0">
                  <span>
                    <strong>{m.mobileUnit.name}</strong> · {m.type}
                  </span>
                  <span className="text-xs text-slate-600">
                    {new Date(m.scheduledDate).toLocaleDateString('es-MX')}
                  </span>
                </li>
              ))}
            </ul>
          )}
        </div>

        <div className="border rounded-lg p-3">
          <h3 className="text-sm font-medium mb-2">Mantenimientos vencidos</h3>
          {overdueMaintenances.length === 0 ? (
            <p className="text-sm text-slate-500">Sin mantenimientos vencidos.</p>
          ) : (
            <ul className="space-y-2 text-sm">
              {overdueMaintenances.map((m) => (
                <li key={m.id} className="flex justify-between items-center border-b pb-1 last:border-b-0">
                  <span><strong>{m.mobileUnit.name}</strong> · {m.type}</span>
                  <span className="text-xs text-red-600">
                    {new Date(m.scheduledDate).toLocaleDateString('es-MX')}
                  </span>
                </li>
              ))}
            </ul>
          )}
        </div>
      </section>

      <section>
        <h3 className="text-sm font-medium mb-2">Calendario semanal (proyectos + mantenimientos)</h3>
        <div className="overflow-x-auto border rounded-lg bg-white">
          <table className="min-w-full text-xs">
            <thead>
              <tr className="bg-slate-50">
                <th className="px-2 py-2 text-left">Unidad</th>
                {days.map((d) => (
                  <th key={d.toISOString()} className="px-2 py-2 text-left">
                    {d.toLocaleDateString('es-MX', { weekday: 'short', day: 'numeric' })}
                  </th>
                ))}
              </tr>
            </thead>
            <tbody>
              {allUnits.map((u) => (
                <tr key={u.id} className="border-t">
                  <td className="px-2 py-2 font-medium">
                    <Link href={`/admin/mobile-units/${u.id}`} className="text-blue-600 hover:underline">
                      {u.name}
                    </Link>
                  </td>
                  {days.map((d) => {
                    const dayStart = new Date(d); dayStart.setHours(0, 0, 0, 0)
                    const dayEnd = new Date(d); dayEnd.setHours(23, 59, 59, 999)
                    const ps = weekProjects.filter((p) => {
                      if (p.mobileUnitId !== u.id) return false
                      return new Date(p.startDate) <= dayEnd && new Date(p.endDate) >= dayStart
                    })
                    const ms = weekMaintenances.filter((m) => {
                      if (m.mobileUnitId !== u.id) return false
                      const sd = new Date(m.scheduledDate)
                      return sd >= dayStart && sd <= dayEnd
                    })
                    return (
                      <td key={d.toISOString()} className="px-2 py-2 align-top">
                        {ps.map((p) => (
                          <div key={p.id} className="text-[10px] mb-0.5 px-1 rounded bg-emerald-100 border border-emerald-300">
                            📍 {p.name}
                          </div>
                        ))}
                        {ms.map((m) => (
                          <div key={m.id} className="text-[10px] mb-0.5 px-1 rounded bg-amber-100 border border-amber-300">
                            🔧 {m.type}
                          </div>
                        ))}
                      </td>
                    )
                  })}
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </section>

      <section>
        <h3 className="text-sm font-medium mb-2">Conflictos detectados esta semana</h3>
        {conflicts.length === 0 ? (
          <p className="text-sm text-slate-500">Sin conflictos.</p>
        ) : (
          <ul className="divide-y border rounded-md">
            {conflicts.map((c, i) => (
              <li key={i} className="px-3 py-2 text-sm">
                <strong>{c.unit}</strong> · {c.date} · Proyecto <em>{c.project}</em> vs Mantenimiento {c.maintenance}
              </li>
            ))}
          </ul>
        )}
      </section>

      <section>
        <h3 className="text-sm font-medium mb-2">Utilización por unidad</h3>
        <div className="overflow-x-auto border rounded-lg bg-white">
          <table className="min-w-full text-sm">
            <thead className="bg-slate-50 text-xs uppercase text-slate-600">
              <tr>
                <th className="px-3 py-2 text-left">Unidad</th>
                <th className="px-3 py-2 text-right">Proyectos asignados</th>
                <th className="px-3 py-2 text-right">Mantenimientos totales</th>
                <th className="px-3 py-2 text-right">Capacidad</th>
              </tr>
            </thead>
            <tbody>
              {allUnits.map((u) => (
                <tr key={u.id} className="border-t">
                  <td className="px-3 py-2">{u.name}</td>
                  <td className="px-3 py-2 text-right">{u._count.projects}</td>
                  <td className="px-3 py-2 text-right">{u._count.maintenances}</td>
                  <td className="px-3 py-2 text-right">{u.capacity ?? '—'}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </section>
    </div>
  )
}

