                  <div>
                    <p className="text-[10px] text-blue-500 font-bold uppercase">Tipo</p>
                    <p className="text-sm font-medium text-blue-800">{DOC_TYPE_LABELS[worker.lastIdentityDocumentType ?? ''] ?? worker.lastIdentityDocumentType ?? '—'}</p>
                  </div>
                  {worker.lastIdentityVerifiedAt && (
                    <div>
                      <p className="text-[10px] text-blue-500 font-bold uppercase">Verificada</p>
                      <p className="text-sm font-medium text-blue-800">
                        {new Date(worker.lastIdentityVerifiedAt).toLocaleDateString('es-MX')}
                      </p>
                    </div>
                  )}
                </div>
                {worker.lastIdentityFrontFileUrl && (
                  <img
                    src={worker.lastIdentityFrontFileUrl}
                    alt="Última evidencia"
                    className="w-full h-24 object-cover rounded-xl border border-blue-200"
                  />
                )}
                <label className="flex items-center gap-3 cursor-pointer">
                  <input
                    type="checkbox"
                    checked={reuseConfirmed}
                    onChange={e => setReuseConfirmed(e.target.checked)}
                    className="w-4 h-4 accent-blue-600"
                  />
                  <span className="text-xs font-bold text-blue-700">Confirmo que esta evidencia sigue siendo válida para el ingreso de hoy</span>
                </label>
              </div>
            </section>
          )}

          {/* ── Excepción / comentario operativo ────────────────────────── */}
          {evidenceMode === 'EXCEPTION_WITHOUT_CAPTURE' && (
            <section className="space-y-4 border-t border-slate-100 pt-4">
              <div className="bg-orange-50 border border-orange-200 rounded-2xl p-4 space-y-4">
                <div className="flex items-center gap-2">
                  <span className="text-xl">⚠️</span>
                  <p className="text-xs font-bold text-orange-700">Comentario operativo obligatorio</p>
                </div>
                <div>
                  <label className="text-xs font-bold text-slate-500 block mb-1">
                    Motivo <span className="text-red-500">*</span>
                  </label>
                  <select
                    value={exceptionReason}
                    onChange={e => setExceptionReason(e.target.value as IdentityExceptionReason)}
                    className="w-full bg-white ring-1 ring-orange-200 focus:ring-2 focus:ring-orange-400 border-none p-3 rounded-xl text-sm outline-none"
                  >
                    <option value="">— Seleccionar motivo —</option>
                    {IDENTITY_EXCEPTION_REASONS.map(r => (
                      <option key={r} value={r}>{EXCEPTION_REASON_LABELS[r] ?? r}</option>
                    ))}
                  </select>
                </div>
                <div>
                  <label className="text-xs font-bold text-slate-500 block mb-1">
                    Comentario operativo <span className="text-red-500">*</span>
                  </label>
                  <textarea
                    value={exceptionComment}
                    onChange={e => setExceptionComment(e.target.value)}
                    placeholder="Describe la situación específica de este ingreso..."
                    rows={3}
                    className="w-full bg-white ring-1 ring-orange-200 focus:ring-2 focus:ring-orange-400 border-none p-3 rounded-xl text-sm outline-none resize-none"
                  />
                  <p className="text-[10px] text-slate-400 mt-1">{exceptionComment.trim().length}/5 mín. · El ingreso continuará sin bloqueo.</p>
                </div>
              </div>
            </section>
          )}

          {/* Error */}
          {error && (
            <p className="text-xs text-red-600 bg-red-50 p-3 rounded-xl border border-red-100 font-medium">
              ⚠️ {error}
            </p>
          )}
        </div>

        {/* Acciones */}
        <div className="flex gap-3 p-6 border-t border-slate-100 flex-shrink-0">
          <button
            onClick={onClose}
            disabled={isPending}
            className="flex-1 bg-slate-100 hover:bg-slate-200 text-slate-600 py-3 rounded-2xl font-bold text-sm transition-all disabled:opacity-50"
          >
            Cancelar
          </button>
          <button
            onClick={handleConfirm}
            disabled={isPending || !canConfirm}
            className="flex-2 bg-emerald-600 hover:bg-emerald-700 text-white py-3 px-6 rounded-2xl font-black text-sm transition-all shadow-lg shadow-emerald-100 disabled:opacity-50 disabled:cursor-not-allowed"
          >
            {isPending ? '⏳ Procesando...' : '✅ Confirmar y Hacer Check-In'}
          </button>
        </div>
      </div>
    </div>
  )
}

'use client'

import { useState, useTransition, useRef } from 'react'
import { updateEventStatus, saveVerdict } from '@/actions/medical-event.actions'
import { signMedicalDictamPDF } from '@/actions/signature.actions'
import { useRouter } from 'next/navigation'
import { useSession } from 'next-auth/react'

interface EventFlowControllerProps {
    eventId: string
    currentStatus: string
    verdictData?: {
        finalDiagnosis?: string
        recommendations?: string
    }
}

export default function EventFlowController({
    eventId,
    currentStatus,
    verdictData
}: EventFlowControllerProps) {
    const [isPending, startTransition] = useTransition()
    const [error, setError] = useState<string | null>(null)
    const router = useRouter()
    const { data: session } = useSession()

    const diagRef = useRef<HTMLTextAreaElement>(null)
    const recRef = useRef<HTMLTextAreaElement>(null)

    // Status logic
    // MODIFICADO: Fase de carga solo debe aparecer si ya es estrictamente IN_PROGRESS para que no manche las demás etapas
    const isInProgress = currentStatus === 'IN_PROGRESS'
    const isValidating = currentStatus === 'VALIDATING'
    const isCompleted = currentStatus === 'COMPLETED'

    // El Paso 3 ya se resuelve dentro de la papeleta-workspace; este bloque no
    // debe renderizar ninguna UI para IN_PROGRESS aunque otro contenedor lo invoque.
    if (isInProgress) {
        return null
    }

    const handleFinishCapture = () => {
        startTransition(async () => {
            try {
                await updateEventStatus(eventId, 'VALIDATING')
                router.refresh()
            } catch {
                setError('Error al cambiar estado')
            }
        })
    }

    const handleSign = () => {
        if (!session?.user?.id) {
            setError('No se pudo identificar al validador')
            return
        }

        const diagnosis = diagRef.current?.value || ''
        if (!diagnosis) {
            setError('El diagnóstico es obligatorio para firmar')
            return
        }

        startTransition(async () => {
            try {
                // 1. Save verdict synchronously
                const recommendations = recRef.current?.value || ''
                await saveVerdict(eventId, diagnosis, recommendations, session.user.id)

                // 2. Sign
                const result = await signMedicalDictamPDF(eventId)
                if (result.success) {
                    router.refresh()
                } else {
                    setError(result.error || 'Error al firmar')
                }
            } catch (err: unknown) {
                const message = err instanceof Error ? err.message : 'Error de conexión'
                setError('Error en el proceso de firma: ' + message)
            }
        })
    }

    return (
        <div className="mt-12 p-8 bg-slate-50 rounded-2xl border-2 border-dashed border-slate-200">
            <div className="max-w-3xl mx-auto text-center">

                {/* 2. SECCIÓN: VALIDACIÓN Y FIRMA (El médico llena el diagnóstico) */}
                {isValidating && (
                    <div className="space-y-6 text-left animate-in fade-in zoom-in-95 duration-500">
                        <div className="flex items-center gap-4 mb-6">
                            <div className="w-12 h-12 bg-purple-100 text-purple-600 rounded-xl flex items-center justify-center text-xl">
                                🩺
                            </div>
                            <div>
                                <h3 className="text-xl font-bold text-slate-800">Reporte médico de aptitud</h3>
                                <p className="text-sm text-slate-500">Completa la evaluación para generar el certificado firmado.</p>
                            </div>
                        </div>

                        <div className="bg-white p-6 rounded-xl border border-slate-200 shadow-sm space-y-4">
                            <div>
                                <label className="block text-xs font-bold text-slate-400 uppercase mb-1">Diagnóstico Final</label>
                                <textarea
                                    ref={diagRef}
                                    className="w-full border border-slate-200 rounded-lg p-3 text-sm focus:ring-2 focus:ring-purple-500 outline-none min-h-[100px]"
                                    placeholder="Ej: Apto para el puesto sin restricciones..."
                                    defaultValue={verdictData?.finalDiagnosis}
                                ></textarea>
                            </div>
                            <div>
                                <label className="block text-xs font-bold text-slate-400 uppercase mb-1">Recomendaciones</label>
                                <textarea
                                    ref={recRef}
                                    className="w-full border border-slate-200 rounded-lg p-3 text-sm focus:ring-2 focus:ring-purple-500 outline-none"
                                    placeholder="Ej: Uso de protección auditiva..."
                                    defaultValue={verdictData?.recommendations}
                                ></textarea>
                            </div>
                        </div>

                        <div className="flex flex-col items-center gap-4 pt-4">
                            <button
                                onClick={handleSign}
                                disabled={isPending}
                                className="w-full max-w-sm bg-slate-900 hover:bg-black text-white px-8 py-4 rounded-xl font-bold shadow-xl transition-all hover:scale-[1.02] active:scale-95 disabled:opacity-50 flex items-center justify-center gap-2"
                            >
                                {isPending ? 'Generando Firma Digital...' : '🔏 Firmar y Emitir Dictamen'}
                            </button>
                            <p className="text-[10px] text-slate-400 flex items-center gap-1">
                                <span className="text-emerald-500">🔒</span> Se aplicará sello digital del Dr. Usuario Demo
                            </p>
                        </div>
                    </div>
                )}

                {/* 3. SECCIÓN: COMPLETADO */}
                {isCompleted && (
                    <div className="space-y-6 animate-in fade-in fill-mode-both duration-700">
                        <div className="w-20 h-20 bg-emerald-100 text-emerald-600 rounded-full flex items-center justify-center mx-auto text-4xl mb-4 shadow-sm border-4 border-white">
                            ✨
                        </div>
                        <div>
                            <h3 className="text-3xl font-extrabold text-slate-900">¡Expediente Completado!</h3>
                            <p className="text-slate-500 mt-2">El dictamen médico ha sido firmado y está listo para descarga.</p>
                        </div>

                        <div className="flex flex-col md:flex-row gap-4 justify-center pt-4">
                            <a
                                href={`/api/pdf/${eventId}`}
                                target="_blank"
                                className="bg-emerald-600 hover:bg-emerald-700 text-white px-10 py-4 rounded-xl font-bold shadow-lg shadow-emerald-100 transition-all flex items-center justify-center gap-2"
                            >
                                ⬇️ Descargar Dictamen (PDF)
                            </a>
                            <button
                                onClick={() => router.push('/reception')}
                                className="bg-slate-200 hover:bg-slate-300 text-slate-700 px-8 py-4 rounded-xl font-bold transition-all"
                            >
                                Volver a Recepción
                            </button>
                        </div>
                    </div>
                )}

                {error && (
                    <div className="mt-4 p-3 bg-red-50 text-red-600 text-sm rounded-lg border border-red-100 italic">
                        ⚠️ {error}
                    </div>
                )}

            </div>
        </div>
    )
}

'use client'

/**
 * Modal de creación y edición de proyectos de visita médica.
 * @id IMPL-20260519-14
 * @spec context/SPECs/SPEC_ARCH-20260519-12-ENTIDAD-PROJECT-VISITA-MEDICA.md
 * @id IMPL-20260527-03
 * @spec context/SPECs/SPEC_ARCH-20260527-03-ALTA-MASIVA-DESDE-PROYECTO.md
 * @backup context/checkpoints/CHK_IMPL-20260527-03-ALTA-MASIVA-DESDE-PROYECTO.md
 */

import { useState, useTransition, useEffect, useRef } from 'react'
import { createProject, updateProject } from '@/actions/project.actions'

interface CompanyOption {
  id: string
  name: string
}

interface BranchOption {
  id: string
  name: string
}

export interface ProjectForEdit {
  id: string
  name: string
  companyId: string
  startDate: Date | string
  endDate: Date | string
  branchId?: string | null
  unitRef?: string | null
  notes?: string | null
}

interface ProjectFormModalProps {
  companies: CompanyOption[]
  branches: BranchOption[]
  /** Si se provee, opera en modo edición controlado por el padre */
  projectToEdit?: ProjectForEdit | null
  /** Estado de visibilidad (modo controlado) */
  isOpen?: boolean
  /** Callback de cierre (modo controlado) */
  onClose?: () => void
  /** Callback tras crear/actualizar exitosamente */
  onSuccess?: (projectId: string, projectName: string, companyId?: string) => void
  /** Texto del botón trigger (solo en modo no controlado) */
  triggerLabel?: string
}

function toISOLocal(val: Date | string | undefined | null): string {
  if (!val) return ''
  const d = val instanceof Date ? val : new Date(val)
  if (isNaN(d.getTime())) return ''
  // Formato YYYY-MM-DDTHH:mm para inputs de tipo datetime-local
  return d.toISOString().slice(0, 16)
}

export default function ProjectFormModal({
  companies,
  branches,
  projectToEdit,
  isOpen: isOpenProp,
  onClose,
  onSuccess,
  triggerLabel = 'Nuevo Proyecto',
}: ProjectFormModalProps) {
  const isControlled = isOpenProp !== undefined
  const [internalOpen, setInternalOpen] = useState(false)
  const modalOpen = isControlled ? isOpenProp! : internalOpen

  const [isPending, startTransition] = useTransition()
  const [error, setError] = useState<string | null>(null)

  // Campos del formulario
  const [name, setName] = useState('')
  const [companyId, setCompanyId] = useState('')
  const [startDate, setStartDate] = useState('')
  const [endDate, setEndDate] = useState('')
  const [branchId, setBranchId] = useState('')
  const [unitRef, setUnitRef] = useState('')
  const [notes, setNotes] = useState('')

  const isEditMode = !!projectToEdit

  const prevIdRef = useRef<string | undefined>(undefined)

  // Sincronizar campos cuando cambia el proyecto a editar
  // eslint-disable-next-line react-hooks/exhaustive-deps
  useEffect(() => {
    const currentId = projectToEdit?.id
    if (currentId === prevIdRef.current) return
    prevIdRef.current = currentId
    if (projectToEdit) {
      setName(projectToEdit.name)
      setCompanyId(projectToEdit.companyId)
      setStartDate(toISOLocal(projectToEdit.startDate))
      setEndDate(toISOLocal(projectToEdit.endDate))
      setBranchId(projectToEdit.branchId ?? '')
      setUnitRef(projectToEdit.unitRef ?? '')
      setNotes(projectToEdit.notes ?? '')
    } else {
      setName('')
      setCompanyId('')
      setStartDate('')
      setEndDate('')
      setBranchId('')
      setUnitRef('')
      setNotes('')
    }
    setError(null)
  })

  function openModal() {
    setError(null)
    setInternalOpen(true)
  }

  function closeModal() {
    if (isControlled) {
      onClose?.()
    } else {
      setInternalOpen(false)
    }
    setError(null)
  }

  function handleSubmit(e: React.FormEvent) {
    e.preventDefault()
    setError(null)

    // Convertir datetime-local a ISO con segundos
    const toISO = (val: string) => {
      if (!val) return ''
      const d = new Date(val)
      return isNaN(d.getTime()) ? '' : d.toISOString()
    }

    const payload = {
      name: name.trim(),
      companyId,
      startDate: toISO(startDate),
      endDate: toISO(endDate),
      branchId: branchId || undefined,
      unitRef: unitRef.trim() || undefined,
      notes: notes.trim() || undefined,
    }

    startTransition(async () => {
      let result: { success: boolean; error?: string; project?: { id: string; name: string } }

      if (isEditMode && projectToEdit) {
        result = await updateProject(projectToEdit.id, payload)
      } else {
        result = await createProject(payload)
      }

      if (!result.success) {
        setError(result.error ?? 'Error inesperado')
        return
      }

      closeModal()
      if (!isEditMode && result.project) {
        onSuccess?.(result.project.id, result.project.name, payload.companyId)
      } else if (isEditMode && projectToEdit) {
        onSuccess?.(projectToEdit.id, projectToEdit.name, projectToEdit.companyId)
      }
    })
  }

  return (
    <>
      {/* Botón trigger (solo en modo no controlado) */}
      {!isControlled && (
        <button
          onClick={openModal}
          className="inline-flex items-center gap-2 px-4 py-2 bg-blue-600 hover:bg-blue-700 text-white text-sm font-semibold rounded-lg transition-colors"
        >
          <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-8H4" />
          </svg>
          {triggerLabel}
        </button>
      )}

      {/* Modal */}
      {modalOpen && (
        <div
          className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm"
          onClick={(e) => { if (e.target === e.currentTarget) closeModal() }}
        >
          <div className="w-full max-w-lg bg-white rounded-2xl shadow-2xl overflow-hidden">
            {/* Header */}
            <div className="flex items-center justify-between px-6 py-4 bg-gradient-to-r from-blue-600 to-indigo-600">
              <h2 className="text-lg font-bold text-white">
                {isEditMode ? 'Editar Proyecto' : 'Nuevo Proyecto de Visita Médica'}
              </h2>
              <button
                onClick={closeModal}
                className="text-white/70 hover:text-white transition-colors"
                aria-label="Cerrar"
              >
                <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
                </svg>
              </button>
            </div>

            {/* Formulario */}
            <form onSubmit={handleSubmit} className="px-6 py-5 space-y-4">
              {error && (
                <div className="rounded-lg bg-red-50 border border-red-200 p-3 text-sm text-red-700">
                  {error}
                </div>
              )}

              {/* Nombre */}
              <div>
                <label className="block text-xs font-semibold text-slate-600 mb-1">
                  Nombre del Proyecto <span className="text-red-500">*</span>
                </label>
                <input
                  type="text"
                  value={name}
                  onChange={(e) => setName(e.target.value)}
                  placeholder="Ej: AIRBUS Mayo 2026"
                  required
                  maxLength={200}
                  className="w-full border border-slate-300 rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500"
                />
              </div>

              {/* Empresa */}
              <div>
                <label className="block text-xs font-semibold text-slate-600 mb-1">
                  Empresa <span className="text-red-500">*</span>
                </label>
                <select
                  value={companyId}
                  onChange={(e) => setCompanyId(e.target.value)}
                  required
                  disabled={isEditMode} // No se permite cambiar empresa en edición
                  className="w-full border border-slate-300 rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500 disabled:bg-slate-100 disabled:text-slate-500"
                >
                  <option value="">Seleccionar empresa...</option>
                  {companies.map((c) => (
                    <option key={c.id} value={c.id}>{c.name}</option>
                  ))}
                </select>
                {isEditMode && (
                  <p className="text-xs text-slate-400 mt-1">La empresa no puede cambiarse una vez creado el proyecto.</p>
                )}
              </div>

              {/* Fechas */}
              <div className="grid grid-cols-2 gap-3">
                <div>
                  <label className="block text-xs font-semibold text-slate-600 mb-1">
                    Fecha Inicio <span className="text-red-500">*</span>
                  </label>
                  <input
                    type="datetime-local"
                    value={startDate}
                    onChange={(e) => setStartDate(e.target.value)}
                    required
                    className="w-full border border-slate-300 rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500"
                  />
                </div>
                <div>
                  <label className="block text-xs font-semibold text-slate-600 mb-1">
                    Fecha Fin <span className="text-red-500">*</span>
                  </label>
                  <input
                    type="datetime-local"
                    value={endDate}
                    onChange={(e) => setEndDate(e.target.value)}
                    required
                    className="w-full border border-slate-300 rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500"
                  />
                </div>
              </div>

              {/* Unidad y Sucursal */}
              <div className="grid grid-cols-2 gap-3">
                <div>
                  <label className="block text-xs font-semibold text-slate-600 mb-1">
                    Unidad Asignada
                  </label>
                  <input
                    type="text"
                    value={unitRef}
                    onChange={(e) => setUnitRef(e.target.value)}
                    placeholder="Ej: Unidad Móvil 3"
                    maxLength={100}
                    className="w-full border border-slate-300 rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500"
                  />
                </div>
                <div>
                  <label className="block text-xs font-semibold text-slate-600 mb-1">
                    Sucursal AMI
                  </label>
                  <select
                    value={branchId}
                    onChange={(e) => setBranchId(e.target.value)}
                    className="w-full border border-slate-300 rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500"
                  >
                    <option value="">Sin sucursal (planta cliente)</option>
                    {branches.map((b) => (
                      <option key={b.id} value={b.id}>{b.name}</option>
                    ))}
                  </select>
                </div>
              </div>

              {/* Notas */}
              <div>
                <label className="block text-xs font-semibold text-slate-600 mb-1">
                  Notas
                </label>
                <textarea
                  value={notes}
                  onChange={(e) => setNotes(e.target.value)}
                  rows={2}
                  maxLength={1000}
                  placeholder="Notas del vendedor, número de contrato..."
                  className="w-full border border-slate-300 rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500 resize-none"
                />
              </div>

              {/* Acciones */}
              <div className="flex justify-end gap-3 pt-2">
                <button
                  type="button"
                  onClick={closeModal}
                  className="px-4 py-2 text-sm font-medium text-slate-600 hover:text-slate-800 hover:bg-slate-100 rounded-lg transition-colors"
                >
                  Cancelar
                </button>
                <button
                  type="submit"
                  disabled={isPending}
                  className="px-5 py-2 bg-blue-600 hover:bg-blue-700 disabled:bg-blue-300 text-white text-sm font-semibold rounded-lg transition-colors"
                >
                  {isPending
                    ? (isEditMode ? 'Guardando...' : 'Creando...')
                    : (isEditMode ? 'Guardar Cambios' : 'Crear Proyecto')}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </>
  )
}

'use client'

import { useState, useTransition } from 'react'
import { updateEventStatus } from '@/actions/event.actions'
import { useRouter } from 'next/navigation'

export default function StatusUpdateButton({ eventId, nextStatus }: { eventId: string, nextStatus: 'IN_PROGRESS' | 'VALIDATING' }) {
    const [isPending, startTransition] = useTransition()
    const [error, setError] = useState<boolean>(false)
    const router = useRouter()

    const handleClick = (e: React.FormEvent) => {
        e.preventDefault()
        setError(false)

        startTransition(async () => {
            try {
                const result = await updateEventStatus(eventId, nextStatus)
                if (!result.success) {
                    setError(true)
                    // Auto-hide error after 3 seconds
                    setTimeout(() => setError(false), 3000)
                } else {
                    router.refresh()
                }
            } catch (err) {
                setError(true)
                setTimeout(() => setError(false), 3000)
            }
        })
    }

    return (
        <div className="relative">
            <button 
                onClick={handleClick}
                disabled={isPending}
                className={`text-[10px] font-black text-emerald-500 uppercase tracking-widest flex items-center gap-1 hover:gap-2 transition-all bg-emerald-50 px-2 py-1 rounded-md hover:bg-emerald-100 disabled:opacity-50 disabled:cursor-not-allowed`}
            >
                {isPending ? 'Moviendo...' : (nextStatus === 'IN_PROGRESS' ? 'A Consultorio' : 'A Validar')} <span className="text-xs">→</span>
            </button>

            {error && (
                <div className="absolute top-full right-0 mt-1 bg-red-100 text-red-600 text-[9px] font-bold px-2 py-1 rounded shadow-lg whitespace-nowrap z-50 animate-in fade-in slide-in-from-top-1">
                    ⚠️ Error al mover
                </div>
            )}
        </div>
    )
}

'use client'

// IMPL-20260318-01: WorkerFormModal — modo dual (crear/editar) con selector dinámico de Puesto de Trabajo
// IMPL-20260318-09: Manejo explícito de duplicate_found
import { useState, useTransition, useEffect } from 'react'
import { createWorker, updateWorker } from '@/actions/worker.actions'
import { useRouter } from 'next/navigation'
import { EVENTS, OpenAppointmentModalDetail } from '@/types/events'

interface CompanyOption { id: string; name: string }
interface JobPositionOption { id: string; name: string; companyId: string }

/** Datos básicos del trabajador existente cuando se detecta duplicado */
interface DuplicateWorker {
    id: string
    universalId: string | null
    firstName: string
    lastName: string
    dob: Date | null
    email: string | null
    phone: string | null
    company: { id: string; name: string } | null
}

export interface WorkerForEdit {
    id: string
    firstName: string
    lastName: string
    dob?: Date | null
    email?: string | null
    phone?: string | null
    companyId?: string | null
    jobPositionId?: string | null
}

interface WorkerRef {
    id: string
    company?: { id: string; defaultBranchId: string | null } | null
}

interface WorkerFormModalProps {
    companies: CompanyOption[]
    jobPositions: JobPositionOption[]
    /** Si se provee junto con isOpen/onClose, el modal opera en modo edición (controlado por el padre). */
    workerToEdit?: WorkerForEdit | null
    /** Solo en modo controlado (edición): estado de visibilidad que maneja el padre. */
    isOpen?: boolean
    /** Solo en modo controlado (edición): callback para cerrar el modal. */
    onClose?: () => void
}

export default function WorkerFormModal({
    companies,
    jobPositions,
    workerToEdit,
    isOpen: isOpenProp,
    onClose,
}: WorkerFormModalProps) {
    const isControlled = isOpenProp !== undefined
    const [internalOpen, setInternalOpen] = useState(false)
    const modalOpen = isControlled ? isOpenProp! : internalOpen

    const [isPending, startTransition] = useTransition()
    const [successData, setSuccessData] = useState<{ success: boolean; worker?: WorkerRef } | null>(null)
    const [error, setError] = useState<string | null>(null)
    const [duplicateWorker, setDuplicateWorker] = useState<DuplicateWorker | null>(null)
    const [selectedCompanyId, setSelectedCompanyId] = useState('')
    const [selectedJobPositionId, setSelectedJobPositionId] = useState('')
    const router = useRouter()

    // Sincroniza los selects controlados cuando cambia el trabajador en edición
    useEffect(() => {
        setSelectedCompanyId(workerToEdit?.companyId || '')
        setSelectedJobPositionId(workerToEdit?.jobPositionId || '')
    }, [workerToEdit?.id])

    const filteredJobPositions = selectedCompanyId
        ? jobPositions.filter(jp => jp.companyId === selectedCompanyId)
        : []

    function handleOpen() {
        setInternalOpen(true)
        setError(null)
        setDuplicateWorker(null)
        setSelectedCompanyId('')
        setSelectedJobPositionId('')
    }

    function handleClose() {
        if (isControlled) {
            onClose?.()
        } else {
            setInternalOpen(false)
            setSuccessData(null)
            setError(null)
        }
    }

    async function handleSubmit(formData: FormData) {
        startTransition(async () => {
            setError(null)
            setDuplicateWorker(null)
            try {
                if (workerToEdit) {
                    const result = await updateWorker(workerToEdit.id, formData) as { success: boolean; error?: string }
                    if (result.success) {
                        router.refresh()
                        onClose?.()
                    } else {
                        setError(result.error || 'Error al guardar')
                    }
                } else {
                    const result = await createWorker(formData) as {
                        success: boolean
                        status?: string
                        worker?: WorkerRef
                        existingWorker?: DuplicateWorker
                        error?: string
                    }
                    // IMPL-20260318-09: Manejar duplicate_found explícitamente
                    if (result.status === 'duplicate_found' && result.existingWorker) {
                        setDuplicateWorker(result.existingWorker)
                        return
                    }
                    if (result.success) {
                        router.refresh()
                        setSuccessData(result)
                    } else {
                        setError(result.error || 'Error al guardar')
                    }
                }
            } catch {
                setError('Error de conexión')
            }
        })
    }

    // Pantalla de duplicado — solo en modo creación (no controlado)
    if (!isControlled && duplicateWorker) {
        return (
            <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm flex items-center justify-center z-[60] p-4 animate-in fade-in duration-300">
                <div className="bg-white p-8 rounded-[2rem] shadow-2xl max-w-sm w-full space-y-6">
                    <div className="text-center space-y-2">
                        <div className="w-20 h-20 bg-amber-100 text-amber-500 rounded-full flex items-center justify-center mx-auto text-4xl">
                            ⚠️
                        </div>
                        <h3 className="text-xl font-black text-slate-800">Trabajador ya existe</h3>
                        <p className="text-slate-500 text-sm">
                            Se encontró un registro existente con los mismos datos. No se creó un duplicado.
                        </p>
                    </div>

                    <div className="bg-amber-50 border border-amber-200 rounded-2xl p-4 space-y-3">
                        <div className="flex items-center gap-3">
                            <div className="w-10 h-10 bg-amber-200 text-amber-700 rounded-xl flex items-center justify-center text-xl flex-shrink-0">
                                👤
                            </div>
                            <div>
                                <p className="font-black text-slate-800">
                                    {duplicateWorker.firstName} {duplicateWorker.lastName}
                                </p>
                                {duplicateWorker.universalId && (
                                    <p className="text-xs font-mono text-slate-500">
                                        ID: {duplicateWorker.universalId}
                                    </p>
                                )}
                            </div>
                        </div>
                        <div className="grid grid-cols-2 gap-2 pt-2 border-t border-amber-200 text-xs">
                            <div>
                                <p className="text-[10px] font-bold text-slate-400 uppercase">Empresa</p>
                                <p className="font-medium text-slate-700">{duplicateWorker.company?.name || '—'}</p>
                            </div>
                            <div>
                                <p className="text-[10px] font-bold text-slate-400 uppercase">Teléfono</p>
                                <p className="font-medium text-slate-700">{duplicateWorker.phone || '—'}</p>
                            </div>
                        </div>
                    </div>

                    <div className="space-y-3 pt-2">
                        <button
                            onClick={() => {
                                setDuplicateWorker(null)
                                setInternalOpen(false)
                                router.push(`/workers?edit=${duplicateWorker.id}`)
                            }}
                            className="w-full bg-amber-500 hover:bg-amber-600 text-white py-3 rounded-xl font-bold transition-all hover:scale-[1.02]"
                        >
                            ✏️ Editar Trabajador Existente
                        </button>
                        <button
                            onClick={() => setDuplicateWorker(null)}
                            className="w-full bg-slate-100 hover:bg-slate-200 text-slate-600 py-3 rounded-xl font-bold transition-all"
                        >
                            Cancelar
                        </button>
                    </div>
                </div>
            </div>
        )
    }

    // Pantalla de éxito solo para modo creación
    if (!isControlled && successData) {
        return (
            <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm flex items-center justify-center z-[60] p-4 animate-in fade-in duration-300">
                <div className="bg-white p-8 rounded-[2rem] shadow-2xl max-w-sm w-full text-center space-y-6">
                    <div className="w-20 h-20 bg-blue-100 text-blue-600 rounded-full flex items-center justify-center mx-auto text-4xl animate-bounce">
                        👤
                    </div>
                    <div>
                        <h3 className="text-2xl font-black text-slate-800">¡Trabajador Listo!</h3>
                        <p className="text-slate-500 mt-2 text-sm font-medium">El registro se completó correctamente.</p>
                    </div>
                    <div className="space-y-3 pt-2">
                        <button
                            onClick={() => {
                                const w = successData.worker
                                setSuccessData(null)
                                setInternalOpen(false)
                                const params = new URLSearchParams()
                                params.set('action', 'new-appointment')
                                if (w?.id) params.set('workerId', w.id)
                                if (w?.company?.defaultBranchId) params.set('branchId', w.company.defaultBranchId)
                                if (w?.company?.id) params.set('companyId', w.company.id)
                                const event = new CustomEvent<OpenAppointmentModalDetail>(EVENTS.OPEN_APPOINTMENT_MODAL, {
                                    detail: { workerId: w?.id, branchId: w?.company?.defaultBranchId || undefined, companyId: w?.company?.id || undefined }
                                })
                                window.dispatchEvent(event)
                                router.push(`/appointments?${params.toString()}`)
                            }}
                            className="w-full bg-slate-900 hover:bg-black text-white py-3 rounded-xl font-bold transition-all hover:scale-[1.02]"
                        >
                            🗓️ Agendar Consulta Aquí
                        </button>
                        <button
                            onClick={() => { setSuccessData(null); setInternalOpen(false) }}
                            className="w-full bg-slate-100 hover:bg-slate-200 text-slate-600 py-3 rounded-xl font-bold transition-all"
                        >
                            Ver Padrón
                        </button>
                    </div>
                </div>
            </div>
        )
    }

    return (
        <>
            {/* Botón trigger — solo en modo no controlado (creación) */}
            {!isControlled && (
                <button
                    onClick={handleOpen}
                    className="bg-slate-900 hover:bg-black text-white px-6 py-3 rounded-xl text-sm font-bold transition-all shadow-lg shadow-slate-200 flex items-center gap-2"
                >
                    <span className="text-lg">+</span> Registrar Trabajador
                </button>
            )}

            {modalOpen && (
                <div className="fixed inset-0 bg-slate-900/40 backdrop-blur-[2px] flex items-center justify-center z-50 p-4 animate-in fade-in duration-200">
                    <div className="bg-white p-8 rounded-3xl shadow-2xl w-full max-w-md border border-slate-100 relative overflow-hidden">
                        <div className={`absolute top-0 left-0 w-full h-2 ${workerToEdit ? 'bg-amber-500' : 'bg-blue-500'}`} />

                        <div className="flex justify-between items-center mb-8">
                            <div>
                                <h3 className="text-xl font-black text-slate-800">
                                    {workerToEdit ? 'Editar Trabajador' : 'Nuevo Trabajador'}
                                </h3>
                                <p className="text-[10px] text-slate-400 uppercase font-extrabold tracking-widest mt-1">
                                    {workerToEdit ? 'Actualizar datos en Padrón AMI' : 'Alta en Padrón AMI'}
                                </p>
                            </div>
                            <button onClick={handleClose} className="text-slate-300 hover:text-red-500 transition-colors p-2 hover:bg-red-50 rounded-full">
                                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M6 18L18 6M6 6l12 12" />
                                </svg>
                            </button>
                        </div>

                        {/*
                          key en el form: fuerza re-montaje cuando cambia el trabajador en edición,
                          garantizando que los defaultValue de los inputs uncontrolled se actualicen.
                        */}
                        <form key={workerToEdit?.id || 'new'} action={handleSubmit} className="space-y-4">
                            {/* Nombre y Apellidos */}
                            <div className="grid grid-cols-2 gap-4">
                                <div className="space-y-1">
                                    <label className="text-[10px] font-bold text-slate-400 uppercase ml-1">Nombre(s)</label>
                                    <input
                                        name="firstName"
                                        placeholder="Nombre"
                                        required
                                        defaultValue={workerToEdit?.firstName || ''}
                                        className="w-full bg-slate-50 border-none ring-1 ring-slate-200 focus:ring-2 focus:ring-blue-500 p-3 rounded-xl text-sm outline-none"
                                    />
                                </div>
                                <div className="space-y-1">
                                    <label className="text-[10px] font-bold text-slate-400 uppercase ml-1">Apellidos</label>
                                    <input
                                        name="lastName"
                                        placeholder="Apellidos"
                                        required
                                        defaultValue={workerToEdit?.lastName || ''}
                                        className="w-full bg-slate-50 border-none ring-1 ring-slate-200 focus:ring-2 focus:ring-blue-500 p-3 rounded-xl text-sm outline-none"
                                    />
                                </div>
                            </div>

                            {/* DOB + Género: solo en creación (género necesario para generar universalId) */}
                            {!workerToEdit ? (
                                <div className="grid grid-cols-2 gap-4">
                                    <div className="space-y-1">
                                        <label className="text-[10px] font-bold text-slate-400 uppercase ml-1">Fecha de Nacimiento</label>
                                        <input name="dob" type="date" required className="w-full bg-slate-50 border-none ring-1 ring-slate-200 focus:ring-2 focus:ring-blue-500 p-3 rounded-xl text-sm outline-none" />
                                    </div>
                                    <div className="space-y-1">
                                        <label className="text-[10px] font-bold text-slate-400 uppercase ml-1">Género</label>
                                        <select name="gender" required className="w-full bg-slate-50 border-none ring-1 ring-slate-200 focus:ring-2 focus:ring-blue-500 p-3 rounded-xl text-sm outline-none appearance-none">
                                            <option value="M">Masculino</option>
                                            <option value="F">Femenino</option>
                                        </select>
                                    </div>
                                </div>
                            ) : (
                                <div className="space-y-1">
                                    <label className="text-[10px] font-bold text-slate-400 uppercase ml-1">Fecha de Nacimiento</label>
                                    <input
                                        name="dob"
                                        type="date"
                                        defaultValue={workerToEdit.dob ? new Date(workerToEdit.dob).toISOString().split('T')[0] : ''}
                                        className="w-full bg-slate-50 border-none ring-1 ring-slate-200 focus:ring-2 focus:ring-blue-500 p-3 rounded-xl text-sm outline-none"
                                    />
                                </div>
                            )}

                            {/* Empresa (controlado — dispara filtrado de puestos) */}
                            <div className="space-y-1">
                                <label className="text-[10px] font-bold text-slate-400 uppercase ml-1">Empresa</label>
                                <select
                                    name="companyId"
                                    value={selectedCompanyId}
                                    onChange={e => {
                                        setSelectedCompanyId(e.target.value)
                                        setSelectedJobPositionId('')
                                    }}
                                    className="w-full bg-slate-50 border-none ring-1 ring-slate-200 focus:ring-2 focus:ring-blue-500 p-3 rounded-xl text-sm outline-none appearance-none"
                                >
                                    <option value="">-- Seleccionar Empresa --</option>
                                    {companies.map(c => (
                                        <option key={c.id} value={c.id}>{c.name}</option>
                                    ))}
                                </select>
                            </div>

                            {/* Puesto de Trabajo (dinámico según empresa seleccionada) */}
                            <div className="space-y-1">
                                <label className="text-[10px] font-bold text-slate-400 uppercase ml-1">Puesto de Trabajo</label>
                                <select
                                    name="jobPositionId"
                                    value={selectedJobPositionId}
                                    onChange={e => setSelectedJobPositionId(e.target.value)}
                                    disabled={!selectedCompanyId}
                                    className="w-full bg-slate-50 border-none ring-1 ring-slate-200 focus:ring-2 focus:ring-blue-500 p-3 rounded-xl text-sm outline-none appearance-none disabled:opacity-50 disabled:cursor-not-allowed"
                                >
                                    <option value="">
                                        {selectedCompanyId ? '-- Seleccionar Puesto --' : '← Selecciona primero una empresa'}
                                    </option>
                                    {filteredJobPositions.map(jp => (
                                        <option key={jp.id} value={jp.id}>{jp.name}</option>
                                    ))}
                                </select>
                            </div>

                            {/* Email y Teléfono */}
                            <div className="grid grid-cols-2 gap-4">
                                <div className="space-y-1">
                                    <label className="text-[10px] font-bold text-slate-400 uppercase ml-1">Email</label>
                                    <input
                                        name="email"
                                        placeholder="email@ejemplo.com"
                                        type="email"
                                        defaultValue={workerToEdit?.email || ''}
                                        className="w-full bg-slate-50 border-none ring-1 ring-slate-200 focus:ring-2 focus:ring-blue-500 p-3 rounded-xl text-sm outline-none"
                                    />
                                </div>
                                <div className="space-y-1">
                                    <label className="text-[10px] font-bold text-slate-400 uppercase ml-1">Teléfono</label>
                                    <input
                                        name="phone"
                                        placeholder="10 dígitos"
                                        defaultValue={workerToEdit?.phone || ''}
                                        className="w-full bg-slate-50 border-none ring-1 ring-slate-200 focus:ring-2 focus:ring-blue-500 p-3 rounded-xl text-sm outline-none"
                                    />
                                </div>
                            </div>

                            {/* Banner ID (solo creación) */}
                            {!workerToEdit && (
                                <div className="bg-blue-50 p-4 rounded-xl border border-blue-100">
                                    <div className="flex items-center gap-3">
                                        <div className="w-8 h-8 bg-blue-500 rounded-full flex items-center justify-center text-white text-xs">🆔</div>
                                        <div>
                                            <p className="text-[10px] font-black text-blue-600 uppercase">Seguridad AMI</p>
                                            <p className="text-[9px] text-blue-400 font-bold uppercase tracking-tighter">ID se generará automáticamente</p>
                                        </div>
                                    </div>
                                </div>
                            )}

                            {error && (
                                <p className="text-xs text-red-500 font-bold bg-red-50 p-3 rounded-lg border border-red-100 italic">⚠️ {error}</p>
                            )}

                            <button
                                type="submit"
                                disabled={isPending}
                                className={`w-full ${workerToEdit
                                    ? 'bg-amber-500 hover:bg-amber-600 shadow-amber-100'
                                    : 'bg-blue-600 hover:bg-blue-700 shadow-blue-100'
                                } text-white py-4 rounded-2xl font-black shadow-lg transition-all hover:scale-[1.01] active:scale-95 disabled:opacity-50 mt-4`}
                            >
                                {isPending ? 'Procesando...' : workerToEdit ? 'Actualizar Trabajador' : 'Guardar Trabajador'}
                            </button>
                        </form>
                    </div>
                </div>
            )}
        </>
    )
}

'use client'

// IMPL-20260318-01: WorkersTable — tabla de trabajadores con botón Editar y modal de edición controlado
// ARCH-20260318-09: apertura automática por query param ?edit= para resolver duplicate_found
import { useEffect, useState } from 'react'
import Link from 'next/link'
import { usePathname, useRouter } from 'next/navigation'
import WorkerFormModal, { WorkerForEdit } from './WorkerFormModal'

interface WorkerRow {
    id: string
    universalId: string
    firstName: string
    lastName: string
    email: string | null
    phone: string | null
    dob: Date | null
    companyId: string | null
    jobPositionId: string | null
    company: { name: string; defaultBranchId: string | null } | null
    jobPosition: { id: string; name: string; defaultProfileId: string | null } | null
}

interface CompanyOption { id: string; name: string }
interface JobPositionOption { id: string; name: string; companyId: string }

interface WorkersTableProps {
    workers: WorkerRow[]
    companies: CompanyOption[]
    jobPositions: JobPositionOption[]
    initialEditWorkerId?: string
}

/**
 * @id ARCH-20260318-09
 * @see context/handoffs/HANDOFF-ARCH-20260318-08-CORRECTIVO-SOFIA.md
 */
export default function WorkersTable({ workers, companies, jobPositions, initialEditWorkerId }: WorkersTableProps) {
    const [workerToEdit, setWorkerToEdit] = useState<WorkerForEdit | null>(null)
    const router = useRouter()
    const pathname = usePathname()

    function toEditPayload(w: WorkerRow): WorkerForEdit {
        return {
            id: w.id,
            firstName: w.firstName,
            lastName: w.lastName,
            dob: w.dob,
            email: w.email,
            phone: w.phone,
            companyId: w.companyId,
            jobPositionId: w.jobPositionId,
        }
    }

    useEffect(() => {
        if (!initialEditWorkerId) return

        const matchedWorker = workers.find(worker => worker.id === initialEditWorkerId)
        if (!matchedWorker) return

        setWorkerToEdit(toEditPayload(matchedWorker))
        router.replace(pathname)
    }, [initialEditWorkerId, pathname, router, workers])

    function handleCloseEditModal() {
        setWorkerToEdit(null)
        router.replace(pathname)
    }

    return (
        <>
            <div className="bg-white rounded-[2rem] shadow-xl shadow-slate-100 border border-slate-100 overflow-hidden">
                <table className="w-full text-left text-sm">
                    {/* IMPL-20260624-03: Tabla re-estructurada — Empresa/Puesto y Contacto se separan en columnas independientes (ID, Nombre, Empresa, Puesto, Correo, Teléfono, Acciones) */}
                    <thead className="bg-slate-50 border-b border-slate-200 text-slate-500 font-medium">
                        <tr>
                            <th className="px-6 py-4">ID</th>
                            <th className="px-6 py-4">Nombre Completo</th>
                            <th className="px-6 py-4">Empresa</th>
                            <th className="px-6 py-4">Puesto</th>
                            <th className="px-6 py-4">Correo</th>
                            <th className="px-6 py-4">Teléfono</th>
                            <th className="px-6 py-4 text-right">Acciones</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-100">
                        {workers.length === 0 && (
                            <tr>
                                <td colSpan={7} className="p-8 text-center text-slate-400">Sin trabajadores registrados</td>
                            </tr>
                        )}
                        {workers.map(w => (
                            <tr key={w.id} className="hover:bg-slate-50 transition-colors">
                                <td className="px-6 py-4 font-mono text-xs text-slate-500">{w.universalId}</td>
                                <td className="px-6 py-4 font-medium text-slate-900">{w.firstName} {w.lastName}</td>
                                <td className="px-6 py-4">
                                    {w.company ? (
                                        <span className="bg-blue-50 text-blue-700 px-2 py-1 rounded text-xs font-bold border border-blue-100 w-fit inline-block">
                                            {w.company.name}
                                        </span>
                                    ) : (
                                        <span className="text-slate-400 text-xs italic">Sin Empresa</span>
                                    )}
                                </td>
                                <td className="px-6 py-4">
                                    {w.jobPosition ? (
                                        <span className="bg-amber-50 text-amber-700 px-2 py-1 rounded text-xs font-bold border border-amber-100 w-fit inline-block">
                                            {w.jobPosition.name}
                                        </span>
                                    ) : (
                                        <span className="text-slate-400 text-xs italic">—</span>
                                    )}
                                </td>
                                <td className="px-6 py-4 text-slate-500 text-xs">{w.email || <span className="text-slate-400">—</span>}</td>
                                <td className="px-6 py-4 text-slate-500 text-xs">{w.phone || <span className="text-slate-400">—</span>}</td>
                                <td className="px-6 py-4 text-right">
                                    <div className="flex items-center justify-end gap-3">
                                        <button
                                            onClick={() => setWorkerToEdit(toEditPayload(w))}
                                            className="text-amber-600 hover:text-amber-800 text-xs font-semibold hover:underline"
                                        >
                                            Editar
                                        </button>
                                        <Link href={`/history/${w.id}`} className="text-blue-600 hover:underline text-xs">
                                            Historial
                                        </Link>
                                    </div>
                                </td>
                            </tr>
                        ))}
                    </tbody>
                </table>
            </div>

            {/* Modal de edición (controlado): se monta solo cuando hay un trabajador seleccionado */}
            {workerToEdit && (
                <WorkerFormModal
                    companies={companies}
                    jobPositions={jobPositions}
                    workerToEdit={workerToEdit}
                    isOpen={true}
                    onClose={handleCloseEditModal}
                />
            )}
        </>
    )
}

/**
 * @fileoverview CalibrationWorkspaceClient — layout desktop 2 columnas.
 *   Izquierda: tabs de calibración (Propuesta IA, Configuración, Historial, Snapshots, Pruebas).
 *   Derecha: CalibrationDocumentViewer sticky y dominante.
 *   Gestiona el snapshot seleccionado como estado compartido entre ambos paneles.
 * @id IMPL-20260327-19
 * @backup context/SPECs/SPEC_ARCH-20260327-19-CALIBRACION-IA-ASISTIDA-VERSIONADO-AUTOMATICO.md
 * @intervention IMPL-20260604-01
 * @backup context/SPECs/SPEC_ARCH-20260604-01-CALIBRACION-PRESENTACION-ESTUDIOS-IA.md
 * @intervention IMPL-20260715-04
 * @backup context/SPECs/SPEC_ARCH-20260715-04-UPLOAD-PDFS-CALIBRACION.md
 */
"use client"

import { useState } from "react"
import type {
  CandidateField,
  AICalibrationV2,
  CalibrationTestResults as CalibrationTestResultsData,
  FieldDefinition,
} from "@/types/calibration"
import CandidateSchemaPanel from "@/components/calibration/CandidateSchemaPanel"
import CalibrationVersionHistory from "@/components/calibration/CalibrationVersionHistory"
import CalibrationAIAssistantRail from "@/components/calibration/CalibrationAIAssistantRail"
import CalibrationDocumentViewer, {
  type DocumentEntry,
} from "@/components/calibration/CalibrationDocumentViewer"
import AICalibrationEditor from "@/components/calibration/AICalibrationEditor"
import PresentationSchemaPanel from "@/components/calibration/PresentationSchemaPanel"
import CalibrationTestUpload from "@/components/calibration/CalibrationTestUpload"
import CalibrationTestResults from "@/components/calibration/CalibrationTestResults"

// ─────────────────────────────────────────────────────────────────────────────
// Tipos derivados de los datos Prisma (serializables — dates como string)
// ─────────────────────────────────────────────────────────────────────────────

interface ExtractionSnapshotEntry {
  id: string
  version: number
  studyType: string
  sourceFileName: string | null
  sourceFileUrl: string | null
  structuredData: unknown
  clinicalState: string
  modelName: string
  promptVersion: string
  isSuperseded: boolean
  createdAt: Date | string
}

interface EventTestEntry {
  id: string
  status: string
  fileUrl: string | null
  resultNotes: string | null
  createdAt: Date | string
  extractionSnapshots: ExtractionSnapshotEntry[]
}

// ─────────────────────────────────────────────────────────────────────────────
// Props del workspace
// ─────────────────────────────────────────────────────────────────────────────

interface CalibrationWorkspaceClientProps {
  testId: string
  aiCalibration: AICalibrationV2 | null
  initialRawCalibration: Record<string, unknown> | null
  eventTests: EventTestEntry[]
  candidateFields: CandidateField[]
  apiUrl: string
}

// ─────────────────────────────────────────────────────────────────────────────
// Tipos de tab del panel izquierdo
// ─────────────────────────────────────────────────────────────────────────────

type LeftTab = "propuesta" | "presentacion" | "configuracion" | "historial" | "snapshots" | "pruebas"

const TAB_LABELS: Record<LeftTab, string> = {
  propuesta: "🤖 Propuesta IA",
  presentacion: "🧩 Presentación",
  configuracion: "⚙ Configuración",
  historial: "🕐 Historial",
  snapshots: "📋 Snapshots",
  // IMPL-20260715-04 — Upload de PDFs de prueba directo en calibración.
  pruebas: "📄 Pruebas",
}

// ─────────────────────────────────────────────────────────────────────────────
// Helpers
// ─────────────────────────────────────────────────────────────────────────────

function formatDate(date: Date | string) {
  return new Date(date).toLocaleString("es-MX", {
    dateStyle: "short",
    timeStyle: "short",
  })
}

function BadgeStatus({ state }: { state: string }) {
  const map: Record<string, string> = {
    DRAFT_EXTRACTED: "bg-amber-100 text-amber-700",
    COMPLETED: "bg-green-100 text-green-700",
    FAILED: "bg-red-100 text-red-700",
    AI_PENDING_REVIEW: "bg-blue-100 text-blue-700",
    REVIEWED_ACCEPTED: "bg-green-100 text-green-700",
    REVIEWED_EDITED: "bg-violet-100 text-violet-700",
    REVIEWED_REJECTED: "bg-red-100 text-red-700",
  }
  const cls = map[state] ?? "bg-slate-100 text-slate-600"
  return (
    <span className={`inline-block px-2 py-0.5 rounded text-xs font-mono font-semibold ${cls}`}>
      {state}
    </span>
  )
}

// ─────────────────────────────────────────────────────────────────────────────
// RawJsonBlock reutilizable
// ─────────────────────────────────────────────────────────────────────────────

function RawJsonBlock({ label, data }: { label: string; data: unknown }) {
  const [open, setOpen] = useState(false)
  return (
    <div className="border border-slate-200 rounded-lg overflow-hidden">
      <button
        className="w-full flex items-center justify-between px-4 py-2 bg-slate-50 text-xs font-semibold text-slate-700 hover:bg-slate-100 transition-colors"
        onClick={() => setOpen((o) => !o)}
      >
        <span>{label}</span>
        <span className="text-slate-400">{open ? "▲" : "▼"}</span>
      </button>
      {open && (
        <pre className="bg-slate-950 text-green-300 text-xs p-4 overflow-x-auto max-h-80 whitespace-pre-wrap break-all">
          {JSON.stringify(data, null, 2)}
        </pre>
      )}
    </div>
  )
}

// ─────────────────────────────────────────────────────────────────────────────
// Tab: Snapshots (versión compacta del CalibrationTabs anterior)
// ─────────────────────────────────────────────────────────────────────────────

function SnapshotsTab({
  eventTests,
  apiUrl,
  selectedSnapshotId,
  onSelectSnapshot,
}: {
  eventTests: EventTestEntry[]
  apiUrl: string
  selectedSnapshotId: string | null
  onSelectSnapshot: (snapshotId: string, fileUrl: string | null) => void
}) {
  const allSnapshots = eventTests.flatMap((et) =>
    et.extractionSnapshots.map((snap) => ({ snap, et }))
  )

  if (allSnapshots.length === 0) {
    return (
      <div className="py-8 text-center text-slate-400 space-y-2">
        <p className="text-4xl">📭</p>
        <p className="text-sm font-medium">Sin snapshots de calibración.</p>
        <p className="text-xs">Se generan al procesar estudios de esta prueba médica.</p>
      </div>
    )
  }

  const selected = allSnapshots.find((s) => s.snap.id === selectedSnapshotId)
  const selectedSnap = selected?.snap ?? null
  const selectedEt = selected?.et ?? null

  const structured = selectedSnap?.structuredData as Record<string, unknown> | null
  const extracted = structured?.extracted_data
  const missing = structured?.missing_fields as string[] | undefined

  return (
    <div className="space-y-4">
      {/* Lista de snapshots */}
      <div>
        <p className="text-xs font-semibold text-slate-500 uppercase tracking-wide mb-2">
          Snapshots ({allSnapshots.length})
        </p>
        <div className="space-y-1.5">
          {allSnapshots.map(({ snap, et }) => {
            const rawUrl = snap.sourceFileUrl ?? et.fileUrl
            const fullUrl = rawUrl
              ? rawUrl.startsWith("http")
                ? rawUrl
                : `${apiUrl}${rawUrl}`
              : null
            return (
              <button
                key={snap.id}
                onClick={() => onSelectSnapshot(snap.id, fullUrl)}
                className={`w-full text-left px-3 py-2.5 rounded-lg border text-xs transition-colors ${
                  selectedSnapshotId === snap.id
                    ? "border-violet-400 bg-violet-50 text-violet-900"
                    : "border-slate-200 bg-white hover:border-slate-300 text-slate-700"
                }`}
              >
                <div className="flex items-center justify-between gap-1 mb-1">
                  <span className="font-mono font-semibold">{snap.studyType}</span>
                  <span className="text-slate-400">v{snap.version}</span>
                </div>
                <div className="flex items-center gap-1 flex-wrap">
                  <BadgeStatus state={snap.clinicalState} />
                  {snap.isSuperseded && <span className="text-orange-500 font-mono">↯</span>}
                  {fullUrl && <span className="text-teal-600">📎</span>}
                </div>
                <p className="mt-1 text-slate-400">{formatDate(snap.createdAt)}</p>
              </button>
            )
          })}
        </div>
      </div>

      {/* Detalle del snapshot seleccionado */}
      {selectedSnap && (
        <div className="space-y-3 border-t border-slate-200 pt-4">
          <p className="text-xs font-semibold text-slate-600 uppercase tracking-wide">
            Snapshot seleccionado
          </p>
          <div className="flex flex-wrap items-center gap-2 text-xs text-slate-500">
            <BadgeStatus state={selectedSnap.clinicalState} />
            <span>v{selectedSnap.version}</span>
            <span>·</span>
            <span className="font-mono">{selectedSnap.studyType}</span>
            <span>·</span>
            <span>{selectedSnap.modelName} / {selectedSnap.promptVersion}</span>
          </div>
          {selectedSnap.sourceFileName && (
            <p className="text-xs font-mono text-slate-600 bg-slate-50 px-2 py-1 rounded border border-slate-200">
              📄 {selectedSnap.sourceFileName}
            </p>
          )}
          {extracted !== undefined && extracted !== null ? (
            <div className="space-y-1">
              <p className="text-xs font-semibold text-slate-600 uppercase tracking-wide">
                Datos extraídos
              </p>
              <div className="bg-slate-50 border border-slate-200 rounded-lg p-3 overflow-x-auto">
                <pre className="text-xs text-slate-800 whitespace-pre-wrap break-all">
                  {JSON.stringify(extracted, null, 2)}
                </pre>
              </div>
            </div>
          ) : null}
          {Array.isArray(missing) && missing.length > 0 && (
            <div className="space-y-1">
              <p className="text-xs font-semibold text-red-600 uppercase tracking-wide">
                Campos faltantes
              </p>
              <div className="flex flex-wrap gap-1.5">
                {missing.map((field, i) => (
                  <span
                    key={i}
                    className="bg-red-50 border border-red-200 text-red-700 px-2 py-0.5 rounded text-xs font-mono"
                  >
                    {field}
                  </span>
                ))}
              </div>
            </div>
          )}
          <RawJsonBlock label="structuredData (raw)" data={selectedSnap.structuredData} />
        </div>
      )}
    </div>
  )
}

// ─────────────────────────────────────────────────────────────────────────────
// Componente principal
// ─────────────────────────────────────────────────────────────────────────────

export default function CalibrationWorkspaceClient({
  testId,
  aiCalibration,
  initialRawCalibration,
  eventTests,
  candidateFields,
  apiUrl,
}: CalibrationWorkspaceClientProps) {
  const [activeTab, setActiveTab] = useState<LeftTab>("propuesta")

  // Snapshot seleccionado (controla qué documento se muestra a la derecha)
  const allSnapshots = eventTests.flatMap((et) =>
    et.extractionSnapshots.map((snap) => ({ snap, et }))
  )

  const firstSnapshotUrl = (() => {
    for (const { snap, et } of allSnapshots) {
      const raw = snap.sourceFileUrl ?? et.fileUrl
      if (raw) return raw.startsWith("http") ? raw : `${apiUrl}${raw}`
    }
    return null
  })()

  const [selectedSnapshotId, setSelectedSnapshotId] = useState<string | null>(
    allSnapshots[0]?.snap.id ?? null
  )
  const [selectedDocumentUrl, setSelectedDocumentUrl] = useState<string | null>(firstSnapshotUrl)

  // IMPL-20260715-04 — Estado para resultados del último PDF de prueba subido.
  const [testResults, setTestResults] = useState<CalibrationTestResultsData | null>(null)

  const selectedSnapshotEntry =
    allSnapshots.find(({ snap }) => snap.id === selectedSnapshotId) ?? allSnapshots[0] ?? null
  const selectedStructuredData =
    selectedSnapshotEntry?.snap.structuredData &&
    typeof selectedSnapshotEntry.snap.structuredData === "object" &&
    !Array.isArray(selectedSnapshotEntry.snap.structuredData)
      ? (selectedSnapshotEntry.snap.structuredData as Record<string, unknown>)
      : null
  const selectedExtractedData =
    selectedStructuredData?.extracted_data &&
    typeof selectedStructuredData.extracted_data === "object" &&
    !Array.isArray(selectedStructuredData.extracted_data)
      ? (selectedStructuredData.extracted_data as Record<string, unknown>)
      : null

  // Construir lista de documentos para el visor
  const documents: DocumentEntry[] = []
  for (const { snap, et } of allSnapshots) {
    const rawUrl = snap.sourceFileUrl ?? et.fileUrl
    if (!rawUrl) continue
    const fullUrl = rawUrl.startsWith("http") ? rawUrl : `${apiUrl}${rawUrl}`
    if (!documents.find((d) => d.url === fullUrl)) {
      documents.push({
        id: snap.id,
        label: `v${snap.version} · ${snap.studyType}`,
        url: fullUrl,
        fileName: snap.sourceFileName ?? null,
      })
    }
  }

  const selectedDocIdx = documents.findIndex((d) => d.url === selectedDocumentUrl)

  function handleSnapshotSelect(snapshotId: string, fileUrl: string | null) {
    setSelectedSnapshotId(snapshotId)
    if (fileUrl) setSelectedDocumentUrl(fileUrl)
  }

  function handleDocumentSelect(idx: number) {
    const doc = documents[idx]
    if (doc) setSelectedDocumentUrl(doc.url)
  }

  const totalSnapshots = allSnapshots.length
  const currentFieldKeys = ((aiCalibration?.fieldDefinitions ?? []) as FieldDefinition[]).map(
    (f) => f.key
  )

  const tabCls = (tab: LeftTab) =>
    `px-3 py-2 text-xs font-semibold rounded-t-lg border-b-2 transition-colors whitespace-nowrap ${
      activeTab === tab
        ? "border-violet-600 text-violet-700 bg-white"
        : "border-transparent text-slate-500 hover:text-slate-700 bg-slate-50"
    }`

  return (
    <div className="flex gap-0 min-h-0">
      {/* ── Panel izquierdo (40%) ─────────────────────────────────────────── */}
      <div className="w-[42%] shrink-0 flex flex-col min-h-0 border-r border-slate-200">
        {/* Tabs header */}
        <div className="flex border-b border-slate-200 overflow-x-auto bg-slate-50">
          {(["propuesta", "presentacion", "configuracion", "historial", "snapshots", "pruebas"] as LeftTab[]).map((tab) => (
            <button key={tab} className={tabCls(tab)} onClick={() => setActiveTab(tab)}>
              {TAB_LABELS[tab]}
              {tab === "propuesta" && candidateFields.length > 0 && (
                <span className="ml-1 px-1.5 py-0.5 rounded-full bg-violet-600 text-white text-xs">
                  {candidateFields.length}
                </span>
              )}
            </button>
          ))}
        </div>

        {/* Contenido del tab */}
        <div className="flex-1 overflow-y-auto p-4 bg-white">
          {/* ── Tab: Propuesta IA ── */}
          {activeTab === "propuesta" && (
            <div className="space-y-5">
              <CalibrationAIAssistantRail
                candidates={candidateFields}
                aiCalibration={aiCalibration}
                snapshotCount={totalSnapshots}
              />
              <div className="border-t border-slate-200 pt-4">
                <p className="text-xs font-semibold text-slate-700 uppercase tracking-wide mb-3">
                  Campos candidatos
                </p>
                <CandidateSchemaPanel
                  testId={testId}
                  candidates={candidateFields}
                  currentFieldKeys={currentFieldKeys}
                />
              </div>
            </div>
          )}

          {/* ── Tab: Presentación ── */}
          {activeTab === "presentacion" && (
            <PresentationSchemaPanel
              testId={testId}
              aiCalibration={aiCalibration}
              selectedSnapshot={
                selectedSnapshotEntry
                  ? {
                      id: selectedSnapshotEntry.snap.id,
                      studyType: selectedSnapshotEntry.snap.studyType,
                      extractedData: selectedExtractedData,
                    }
                  : null
              }
            />
          )}

          {/* ── Tab: Configuración (V1 legacy) ── */}
          {activeTab === "configuracion" && (
            <div className="space-y-4">
              {aiCalibration && (
                <div className="flex items-center gap-2 px-3 py-2 bg-violet-50 border border-violet-200 rounded-lg text-xs text-violet-700">
                  <span className="font-bold">v{aiCalibration.currentVersion}</span>
                  <span>·</span>
                  <span className="font-mono">{aiCalibration.currentVersionLabel}</span>
                  <span className="ml-auto text-violet-500">Versión vigente</span>
                </div>
              )}
              <AICalibrationEditor testId={testId} initial={initialRawCalibration} />
            </div>
          )}

          {/* ── Tab: Historial ── */}
          {activeTab === "historial" && (
            <CalibrationVersionHistory aiCalibration={aiCalibration} />
          )}

          {/* ── Tab: Snapshots ── */}
          {activeTab === "snapshots" && (
            <SnapshotsTab
              eventTests={eventTests}
              apiUrl={apiUrl}
              selectedSnapshotId={selectedSnapshotId}
              onSelectSnapshot={handleSnapshotSelect}
            />
          )}

          {/* ── Tab: Pruebas (IMPL-20260715-04) ── */}
          {activeTab === "pruebas" && (
            <div className="space-y-4">
              <div className="rounded-lg border border-violet-200 bg-violet-50 px-3 py-2 text-xs text-violet-700 space-y-1">
                <p className="font-semibold">Modo de prueba — sin persistencia</p>
                <p>
                  Sube un PDF directamente para validar la calibración actual
                  (extracción + prediagnóstico). Los resultados viven solo en
                  memoria del backend durante esta sesión y no crean EventTest.
                </p>
              </div>
              <CalibrationTestUpload
                testId={testId}
                testType={aiCalibration?.canonicalStudyType ?? "Audiometria"}
                onResults={setTestResults}
                apiUrl={apiUrl}
              />
              {testResults && <CalibrationTestResults results={testResults} />}
            </div>
          )}
        </div>
      </div>

      {/* ── Panel derecho (58%) — Documento sticky ────────────────────────── */}
      <div className="flex-1 min-w-0 sticky top-0 self-start h-screen">
        <div className="h-full border-l border-slate-200 flex flex-col bg-slate-900 rounded-br-xl overflow-hidden">
          {/* Barra superior del visor */}
          <div className="shrink-0 px-4 py-2 bg-slate-800 border-b border-slate-700 flex items-center gap-2">
            <span className="text-slate-300 text-xs font-semibold uppercase tracking-wide">
              Documento fuente
            </span>
            {documents.length > 0 && (
              <span className="ml-auto text-slate-400 text-xs">
                {documents.length} doc(s) disponible(s)
              </span>
            )}
          </div>
          <div className="flex-1 min-h-0">
            <CalibrationDocumentViewer
              documents={documents}
              externalSelectedIdx={selectedDocIdx >= 0 ? selectedDocIdx : 0}
              onSelectDocument={handleDocumentSelect}
            />
          </div>
        </div>
      </div>
    </div>
  )
}

/**
 * @fileoverview Editor MVP de schema declarativo para aiCalibration.presentation.
 * @id IMPL-20260604-01
 * @backup context/SPECs/SPEC_ARCH-20260604-01-CALIBRACION-PRESENTACION-ESTUDIOS-IA.md
 */
'use client'

import { useEffect, useMemo, useState, useTransition } from 'react'
import { useRouter } from 'next/navigation'
import { proposePresentationSchema } from '@/actions/ai-presentation.actions'
import { saveAICalibrationV2 } from '@/actions/medical-profiles'
import type {
  AICalibrationV2,
  PresentationColumn,
  PresentationSection,
  PresentationSectionKind,
  StudyPresentationSchema,
} from '@/types/calibration'

interface SnapshotInput {
  id: string
  studyType: string
  extractedData: Record<string, unknown> | null
}

interface PresentationSchemaPanelProps {
  testId: string
  aiCalibration: AICalibrationV2 | null
  selectedSnapshot: SnapshotInput | null
}

function createEmptySection(kind: PresentationSectionKind): PresentationSection {
  if (kind === 'table') {
    return { kind, title: 'Nueva tabla', source: '', columns: [] }
  }
  if (kind === 'note') {
    return { kind, title: 'Nueva nota', source: '' }
  }
  if (kind === 'badges') {
    return { kind, title: 'Nuevos badges', sourceKey: '', fields: [] }
  }
  if (kind === 'bilateralFrequency') {
    return { kind, title: 'Nueva tabla bilateral', rightKey: '', leftKey: '', preferredOrder: [] }
  }
  return { kind, title: 'Nueva sección', sourceKey: '', fields: [] }
}

function normalizeSchema(
  schema: StudyPresentationSchema | null | undefined,
  fallbackStudyType: string
): StudyPresentationSchema {
  return {
    studyType: schema?.studyType || fallbackStudyType,
    sections: Array.isArray(schema?.sections) ? schema.sections : [],
  }
}

function parseCommaList(value: string): string[] {
  return value
    .split(',')
    .map((item) => item.trim())
    .filter(Boolean)
}

function parseNumberList(value: string): number[] {
  return value
    .split(',')
    .map((item) => Number(item.trim()))
    .filter((item) => !Number.isNaN(item))
}

function formatColumns(columns: PresentationColumn[]): string {
  return columns.map((col) => `${col.key}|${col.label}`).join('\n')
}

function parseColumns(value: string): PresentationColumn[] {
  return value
    .split('\n')
    .map((line) => line.trim())
    .filter(Boolean)
    .map((line) => {
      const [key, label] = line.split('|').map((item) => item.trim())
      return {
        key: key || '',
        label: label || key || '',
      }
    })
    .filter((column) => column.key)
}

export default function PresentationSchemaPanel({
  testId,
  aiCalibration,
  selectedSnapshot,
}: PresentationSchemaPanelProps) {
  const router = useRouter()
  const [isSuggesting, startSuggesting] = useTransition()
  const [isSaving, startSaving] = useTransition()
  const initialPresentation = aiCalibration?.presentation
  const [schema, setSchema] = useState<StudyPresentationSchema>(() =>
    normalizeSchema(initialPresentation?.schema, selectedSnapshot?.studyType || '')
  )
  const [enabled, setEnabled] = useState<boolean>(initialPresentation?.enabled ?? true)
  const [feedback, setFeedback] = useState<string | null>(null)
  const [error, setError] = useState<string | null>(null)
  const [lastSuggestedAt, setLastSuggestedAt] = useState<string | undefined>(
    initialPresentation?.lastSuggestedAt
  )
  const [lastSuggestionModel, setLastSuggestionModel] = useState<string | undefined>(
    initialPresentation?.lastSuggestionModel
  )
  const [lastSuggestionSummary, setLastSuggestionSummary] = useState<string | undefined>(
    initialPresentation?.lastSuggestionSummary
  )

  useEffect(() => {
    const fallbackStudyType = selectedSnapshot?.studyType || aiCalibration?.canonicalStudyType || ''
    setSchema(normalizeSchema(aiCalibration?.presentation?.schema, fallbackStudyType))
    setEnabled(aiCalibration?.presentation?.enabled ?? true)
    setLastSuggestedAt(aiCalibration?.presentation?.lastSuggestedAt)
    setLastSuggestionModel(aiCalibration?.presentation?.lastSuggestionModel)
    setLastSuggestionSummary(aiCalibration?.presentation?.lastSuggestionSummary)
  }, [aiCalibration?.currentVersion, aiCalibration?.presentation, aiCalibration?.canonicalStudyType, selectedSnapshot?.studyType])

  const selectedStudyType =
    selectedSnapshot?.studyType || schema.studyType || aiCalibration?.canonicalStudyType || ''

  const extractedDataPreview = useMemo(
    () => JSON.stringify(selectedSnapshot?.extractedData ?? {}, null, 2),
    [selectedSnapshot?.extractedData]
  )

  function updateSection(index: number, next: PresentationSection) {
    setSchema((current) => ({
      ...current,
      sections: current.sections.map((section, sectionIndex) =>
        sectionIndex === index ? next : section
      ),
    }))
  }

  function moveSection(index: number, direction: -1 | 1) {
    setSchema((current) => {
      const nextSections = [...current.sections]
      const targetIndex = index + direction
      if (targetIndex < 0 || targetIndex >= nextSections.length) return current
      ;[nextSections[index], nextSections[targetIndex]] = [nextSections[targetIndex], nextSections[index]]
      return { ...current, sections: nextSections }
    })
  }

  function removeSection(index: number) {
    setSchema((current) => ({
      ...current,
      sections: current.sections.filter((_, sectionIndex) => sectionIndex !== index),
    }))
  }

  function addSection(kind: PresentationSectionKind) {
    setSchema((current) => ({
      ...current,
      studyType: current.studyType || selectedStudyType,
      sections: [...current.sections, createEmptySection(kind)],
    }))
  }

  function changeSectionKind(index: number, kind: PresentationSectionKind) {
    updateSection(index, createEmptySection(kind))
  }

  function sanitizeForSave(currentSchema: StudyPresentationSchema): StudyPresentationSchema {
    return {
      studyType: currentSchema.studyType.trim() || selectedStudyType,
      sections: currentSchema.sections.map((section) => {
        if (section.kind === 'table') {
          return {
            ...section,
            title: section.title.trim(),
            source: section.source.trim(),
            columns: section.columns.filter((column) => column.key.trim()),
          }
        }
        if (section.kind === 'note') {
          return {
            ...section,
            title: section.title.trim(),
            source: section.source.trim(),
          }
        }
        if (section.kind === 'bilateralFrequency') {
          return {
            ...section,
            title: section.title.trim(),
            rightKey: section.rightKey.trim(),
            leftKey: section.leftKey.trim(),
            preferredOrder: (section.preferredOrder ?? []).filter((item) => Number.isFinite(item)),
          }
        }
        return {
          ...section,
          title: section.title.trim(),
          sourceKey: section.sourceKey?.trim(),
          fields: section.fields.filter((field) => field.trim()),
        }
      }),
    }
  }

  function handleSuggest() {
    const extractedData = selectedSnapshot?.extractedData
    if (!extractedData || !selectedStudyType) {
      setError('Selecciona un snapshot con extracted_data antes de generar la propuesta.')
      return
    }

    setError(null)
    setFeedback(null)

    startSuggesting(async () => {
      const result = await proposePresentationSchema({
        studyType: selectedStudyType,
        extractedData,
        aiCalibration: aiCalibration
          ? {
              canonicalStudyType: aiCalibration.canonicalStudyType,
            }
          : null,
      })

      if (!result.success || !result.schema) {
        setError(result.error || 'No fue posible generar la propuesta.')
        return
      }

      setSchema(result.schema)
      setLastSuggestedAt(new Date().toISOString())
      setLastSuggestionModel(result.audit?.model_name)
      setLastSuggestionSummary(result.summary)
      setFeedback(result.summary || 'Propuesta cargada correctamente.')
    })
  }

  function handleSave() {
    const sanitizedSchema = sanitizeForSave({
      studyType: schema.studyType || selectedStudyType,
      sections: schema.sections,
    })

    if (!sanitizedSchema.studyType) {
      setError('El schema necesita un studyType antes de guardarse.')
      return
    }

    setError(null)
    setFeedback(null)

    startSaving(async () => {
      const result = await saveAICalibrationV2(testId, {
        fieldDefinitions: aiCalibration?.fieldDefinitions ?? [],
        source: lastSuggestionSummary ? 'ai-assisted-review' : 'manual-review',
        summary: `Actualización de presentación con ${sanitizedSchema.sections.length} sección(es).`,
        presentation: {
          enabled,
          schema: sanitizedSchema,
          lastSuggestedAt,
          lastSuggestionModel,
          lastSuggestionSummary,
        },
        legacyFields: {
          enabled: aiCalibration?.enabled,
          canonicalStudyType: aiCalibration?.canonicalStudyType,
          extraction: aiCalibration?.extraction,
          diagnosis: aiCalibration?.diagnosis,
        },
      })

      if (!result.success) {
        setError(result.error || 'No se pudo guardar la presentación.')
        return
      }

      setFeedback('Schema de presentación guardado y versionado correctamente.')
      router.refresh()
    })
  }

  return (
    <div className="space-y-4">
      <div className="rounded-xl border border-slate-200 bg-slate-50 p-4 space-y-3">
        <div className="flex flex-wrap items-center gap-2 justify-between">
          <div>
            <p className="text-xs font-semibold uppercase tracking-wide text-slate-500">
              Presentación persistida
            </p>
            <h3 className="text-sm font-bold text-slate-800">Schema visual editable por calibración</h3>
          </div>
          <label className="flex items-center gap-2 text-xs font-medium text-slate-700">
            <input type="checkbox" checked={enabled} onChange={(event) => setEnabled(event.target.checked)} />
            Habilitado
          </label>
        </div>

        <div className="grid gap-3 md:grid-cols-2">
          <div>
            <label className="text-xs font-semibold text-slate-600">Study type</label>
            <input
              value={schema.studyType || selectedStudyType}
              onChange={(event) => setSchema((current) => ({ ...current, studyType: event.target.value }))}
              className="mt-1 w-full rounded-lg border border-slate-300 px-3 py-2 text-sm"
            />
          </div>
          <div>
            <label className="text-xs font-semibold text-slate-600">Snapshot activo</label>
            <div className="mt-1 rounded-lg border border-slate-200 bg-white px-3 py-2 text-sm text-slate-700">
              {selectedSnapshot ? `${selectedSnapshot.studyType} · ${selectedSnapshot.id}` : 'Sin snapshot seleccionado'}
            </div>
          </div>
        </div>

        <div className="flex flex-wrap gap-2">
          <button
            type="button"
            onClick={handleSuggest}
            disabled={isSuggesting || !selectedSnapshot?.extractedData}
            className="rounded-lg bg-violet-600 px-4 py-2 text-sm font-semibold text-white disabled:opacity-50"
          >
            {isSuggesting ? 'Generando propuesta...' : 'Generar propuesta desde extracción'}
          </button>
          <button
            type="button"
            onClick={handleSave}
            disabled={isSaving}
            className="rounded-lg border border-slate-300 bg-white px-4 py-2 text-sm font-semibold text-slate-700 disabled:opacity-50"
          >
            {isSaving ? 'Guardando...' : 'Guardar presentación'}
          </button>
        </div>

        {lastSuggestionSummary && (
          <div className="rounded-lg border border-emerald-200 bg-emerald-50 px-3 py-2 text-xs text-emerald-700">
            <p className="font-semibold">Última propuesta</p>
            <p>{lastSuggestionSummary}</p>
            {(lastSuggestedAt || lastSuggestionModel) && (
              <p className="mt-1 font-mono text-[11px] text-emerald-600">
                {[lastSuggestedAt, lastSuggestionModel].filter(Boolean).join(' · ')}
              </p>
            )}
          </div>
        )}

        {feedback && <p className="text-xs text-emerald-700">{feedback}</p>}
        {error && <p className="text-xs text-red-600">{error}</p>}
      </div>

      <div className="rounded-xl border border-slate-200 bg-white p-4 space-y-4">
        <div className="flex flex-wrap gap-2">
          {(['keyValue', 'table', 'note', 'badges', 'bilateralFrequency'] as PresentationSectionKind[]).map((kind) => (
            <button
              key={kind}
              type="button"
              onClick={() => addSection(kind)}
              className="rounded-full border border-slate-300 px-3 py-1 text-xs font-semibold text-slate-600"
            >
              + {kind}
            </button>
          ))}
        </div>

        {schema.sections.length === 0 ? (
          <p className="text-sm text-slate-500">
            Aún no hay secciones. Genera una propuesta o agrega bloques manualmente.
          </p>
        ) : (
          <div className="space-y-4">
            {schema.sections.map((section, index) => (
              <div key={`${section.kind}-${index}`} className="rounded-xl border border-slate-200 p-4 space-y-3">
                <div className="flex flex-wrap items-center gap-2 justify-between">
                  <div className="flex flex-wrap items-center gap-2">
                    <span className="rounded-full bg-slate-100 px-2 py-1 text-xs font-semibold text-slate-600">
                      #{index + 1}
                    </span>
                    <select
                      value={section.kind}
                      onChange={(event) =>
                        changeSectionKind(index, event.target.value as PresentationSectionKind)
                      }
                      className="rounded-lg border border-slate-300 px-2 py-1 text-sm"
                    >
                      <option value="keyValue">keyValue</option>
                      <option value="table">table</option>
                      <option value="note">note</option>
                      <option value="badges">badges</option>
                      <option value="bilateralFrequency">bilateralFrequency</option>
                    </select>
                  </div>
                  <div className="flex gap-2">
                    <button type="button" onClick={() => moveSection(index, -1)} className="text-xs text-slate-500">
                      Subir
                    </button>
                    <button type="button" onClick={() => moveSection(index, 1)} className="text-xs text-slate-500">
                      Bajar
                    </button>
                    <button type="button" onClick={() => removeSection(index)} className="text-xs text-red-600">
                      Eliminar
                    </button>
                  </div>
                </div>

                <div>
                  <label className="text-xs font-semibold text-slate-600">Título</label>
                  <input
                    value={section.title}
                    onChange={(event) => updateSection(index, { ...section, title: event.target.value })}
                    className="mt-1 w-full rounded-lg border border-slate-300 px-3 py-2 text-sm"
                  />
                </div>

                {(section.kind === 'keyValue' || section.kind === 'badges') && (
                  <>
                    <div>
                      <label className="text-xs font-semibold text-slate-600">sourceKey</label>
                      <input
                        value={section.sourceKey ?? ''}
                        onChange={(event) =>
                          updateSection(index, { ...section, sourceKey: event.target.value })
                        }
                        className="mt-1 w-full rounded-lg border border-slate-300 px-3 py-2 text-sm"
                      />
                    </div>
                    <div>
                      <label className="text-xs font-semibold text-slate-600">fields (CSV)</label>
                      <input
                        value={section.fields.join(', ')}
                        onChange={(event) =>
                          updateSection(index, { ...section, fields: parseCommaList(event.target.value) })
                        }
                        className="mt-1 w-full rounded-lg border border-slate-300 px-3 py-2 text-sm"
                      />
                    </div>
                  </>
                )}

                {section.kind === 'note' && (
                  <div>
                    <label className="text-xs font-semibold text-slate-600">source</label>
                    <input
                      value={section.source}
                      onChange={(event) => updateSection(index, { ...section, source: event.target.value })}
                      className="mt-1 w-full rounded-lg border border-slate-300 px-3 py-2 text-sm"
                    />
                  </div>
                )}

                {section.kind === 'table' && (
                  <>
                    <div>
                      <label className="text-xs font-semibold text-slate-600">source</label>
                      <input
                        value={section.source}
                        onChange={(event) => updateSection(index, { ...section, source: event.target.value })}
                        className="mt-1 w-full rounded-lg border border-slate-300 px-3 py-2 text-sm"
                      />
                    </div>
                    <div>
                      <label className="text-xs font-semibold text-slate-600">columns (una por línea: key|label)</label>
                      <textarea
                        value={formatColumns(section.columns)}
                        onChange={(event) =>
                          updateSection(index, { ...section, columns: parseColumns(event.target.value) })
                        }
                        rows={5}
                        className="mt-1 w-full rounded-lg border border-slate-300 px-3 py-2 text-sm"
                      />
                    </div>
                  </>
                )}

                {section.kind === 'bilateralFrequency' && (
                  <div className="grid gap-3 md:grid-cols-3">
                    <div>
                      <label className="text-xs font-semibold text-slate-600">rightKey</label>
                      <input
                        value={section.rightKey}
                        onChange={(event) =>
                          updateSection(index, { ...section, rightKey: event.target.value })
                        }
                        className="mt-1 w-full rounded-lg border border-slate-300 px-3 py-2 text-sm"
                      />
                    </div>
                    <div>
                      <label className="text-xs font-semibold text-slate-600">leftKey</label>
                      <input
                        value={section.leftKey}
                        onChange={(event) =>
                          updateSection(index, { ...section, leftKey: event.target.value })
                        }
                        className="mt-1 w-full rounded-lg border border-slate-300 px-3 py-2 text-sm"
                      />
                    </div>
                    <div>
                      <label className="text-xs font-semibold text-slate-600">preferredOrder (CSV)</label>
                      <input
                        value={(section.preferredOrder ?? []).join(', ')}
                        onChange={(event) =>
                          updateSection(index, {
                            ...section,
                            preferredOrder: parseNumberList(event.target.value),
                          })
                        }
                        className="mt-1 w-full rounded-lg border border-slate-300 px-3 py-2 text-sm"
                      />
                    </div>
                  </div>
                )}
              </div>
            ))}
          </div>
        )}
      </div>

      <div className="rounded-xl border border-slate-200 bg-slate-950 p-4">
        <p className="mb-2 text-xs font-semibold uppercase tracking-wide text-slate-300">
          extracted_data del snapshot seleccionado
        </p>
        <pre className="max-h-72 overflow-auto whitespace-pre-wrap break-all text-xs text-green-300">
          {extractedDataPreview}
        </pre>
      </div>
    </div>
  )
}

