                  <p className="text-xs text-red-600 bg-red-50 border border-red-200 rounded-lg px-3 py-2">
                    {regenError}
                  </p>
                )}
                {!readonly && (
                  isRegenerating && regenStage ? (
                    <UploadProgressPanel stage={regenStage} isRegen />
