            {/* Panel de Prediagnóstico IA — separado visualmente del raw */}
            {isAIEligible && test.aiSnapshot && (
              <StudyAIPrediagnosisPanel
                prediagnosisSnapshotId={test.aiSnapshot.prediagnosisSnapshotId}
                snapshot={test.aiSnapshot.snapshot as unknown as Parameters<typeof StudyAIPrediagnosisPanel>[0]['snapshot']}
                reviewerUserId={reviewerUserId}
                eventId={eventId}
                existingReview={test.aiSnapshot.existingReview as unknown as Parameters<typeof StudyAIPrediagnosisPanel>[0]['existingReview']}
                readonly={readonly}
              />
            )}

            {/* Acciones de estado */}
            {!readonly && (
              <div className="bg-slate-50 rounded-xl p-4 space-y-3">
                <p className="text-xs font-bold text-slate-500 uppercase tracking-wider">
                  Cambiar estado
                </p>
                <div className="flex flex-wrap gap-2">
                  {test.status === 'PENDING' && (
                    <button
                      onClick={() => onStatusChange(test.id, 'IN_PROGRESS')}
                      disabled={isPending}
                      className="bg-blue-100 hover:bg-blue-200 text-blue-700 px-3 py-1.5 rounded-lg text-xs font-bold transition-colors disabled:opacity-50"
                    >
                      ▶ Iniciar proceso
                    </button>
                  )}
                  {isLab && !sampleTracked && (test.status === 'PENDING' || test.status === 'IN_PROGRESS') && (
                    <button
                      onClick={() => onStatusChange(test.id, 'SAMPLE_TAKEN')}
                      disabled={isPending}
                      className="bg-purple-100 hover:bg-purple-200 text-purple-700 px-3 py-1.5 rounded-lg text-xs font-bold transition-colors disabled:opacity-50"
                    >
                      🧪 Muestra tomada
                    </button>
                  )}
                  {(test.status !== 'COMPLETED' && test.status !== 'RESULT_REGISTERED') && (
                    <button
                      onClick={() => onStatusChange(test.id, 'RESULT_REGISTERED')}
                      disabled={isPending}
                      className="bg-teal-100 hover:bg-teal-200 text-teal-700 px-3 py-1.5 rounded-lg text-xs font-bold transition-colors disabled:opacity-50"
                    >
                      ✅ Resultado registrado
                    </button>
                  )}
                  {test.status !== 'COMPLETED' && (
                    <button
                      onClick={() => onStatusChange(test.id, 'COMPLETED')}
                      disabled={isPending}
                      className="bg-emerald-100 hover:bg-emerald-200 text-emerald-700 px-3 py-1.5 rounded-lg text-xs font-bold transition-colors disabled:opacity-50"
                    >
                      🏁 Completar estudio
                    </button>
                  )}
                </div>
                {isPending && (
                  <p className="text-xs text-slate-400 animate-pulse">Guardando...</p>
                )}
              </div>
            )}

            {/* Badge de solo lectura */}
            {readonly && (
              <div className="bg-slate-50 border border-slate-200 rounded-xl p-3 text-center">
                <p className="text-xs text-slate-400">Vista de solo lectura — el expediente ya fue cerrado.</p>
              </div>
            )}
          </div>

          {/* ===== COLUMNA DERECHA: EVIDENCIA DOCUMENTAL ===== */}
          <div className="space-y-3 lg:sticky lg:top-4 self-start">

            {/* Archivo vinculado + visor embebido */}
            {test.fileUrl ? (
              <div className="bg-emerald-50 border border-emerald-200 rounded-xl p-4 space-y-3">
                <p className="text-xs font-bold text-emerald-700 uppercase tracking-wider">Archivo vinculado</p>
                <StudyDocumentViewer
                  fileUrl={`${apiUrl}${test.fileUrl}`}
                  fileName={test.fileUrl.split('/').pop() || 'archivo'}
                />
              </div>
            ) : (
              <div className="bg-slate-50 border border-dashed border-slate-200 rounded-xl p-5 text-center">
                <span className="text-2xl block mb-1">📂</span>
                <p className="text-sm text-slate-400 font-medium">Sin archivo vinculado</p>
                <p className="text-xs text-slate-400 mt-1">Sube el resultado para visualizarlo aquí.</p>
              </div>
            )}
          </div>
        </div>
      )}

      {/* Acciones y badge para estudios de formulario (Médico, Somatometría, Agudeza Visual) */}
      {(isMedico || isSomato || isAgudeza) && !readonly && (
        <div className="bg-slate-50 rounded-xl p-4 space-y-3">
          <p className="text-xs font-bold text-slate-500 uppercase tracking-wider">
            Cambiar estado
          </p>
          <div className="flex flex-wrap gap-2">
            {test.status === 'PENDING' && (
              <button
                onClick={() => onStatusChange(test.id, 'IN_PROGRESS')}
                disabled={isPending}
                className="bg-blue-100 hover:bg-blue-200 text-blue-700 px-3 py-1.5 rounded-lg text-xs font-bold transition-colors disabled:opacity-50"
              >
                ▶ Iniciar proceso
              </button>
            )}
            {(test.status !== 'COMPLETED' && test.status !== 'RESULT_REGISTERED') && !isMedico && (
              <button
                onClick={() => onStatusChange(test.id, 'RESULT_REGISTERED')}
                disabled={isPending}
                className="bg-teal-100 hover:bg-teal-200 text-teal-700 px-3 py-1.5 rounded-lg text-xs font-bold transition-colors disabled:opacity-50"
              >
                ✅ Resultado registrado
              </button>
            )}
            {test.status !== 'COMPLETED' && (
              <button
                onClick={() => onStatusChange(test.id, 'COMPLETED')}
                disabled={isPending}
                className="bg-emerald-100 hover:bg-emerald-200 text-emerald-700 px-3 py-1.5 rounded-lg text-xs font-bold transition-colors disabled:opacity-50"
              >
                🏁 Completar estudio
              </button>
            )}
          </div>
          {isPending && (
            <p className="text-xs text-slate-400 animate-pulse">Guardando...</p>
          )}
        </div>
      )}

      {(isMedico || isSomato || isAgudeza) && readonly && (
        <div className="bg-slate-50 border border-slate-200 rounded-xl p-3 text-center">
          <p className="text-xs text-slate-400">Vista de solo lectura — el expediente ya fue cerrado.</p>
        </div>
      )}
    </div>
  )
}

'use client'
/**
 * Modal de Pago y Recibo de la Papeleta.
 * Patrón visual inspirado en CorroborationModal.tsx: header ámbar, max-w-xl,
 * z-50, animación fade-in.
 *
 * @id IMPL-20260630-01
 * @id IMPL-20260630-02 — WhatsApp Web receipt support
 * @spec context/SPECs/SPEC_ARCH-20260630-01-MODAL-PAGO-RECIBO-PAPELETA.md
 * @spec context/SPECs/SPEC_ARCH-20260630-02-WHATSAPP-RECIBO.md
 */

import { useState, useTransition, useMemo, useCallback } from 'react'
import { pdf } from '@react-pdf/renderer'
import { PaymentReceiptPDF, type ReceiptPDFData } from '@/components/pdf/PaymentReceiptPDF'
import {
  createPaymentRecord,
} from '@/actions/payment.actions'
import {
  getPaymentMethodLabel,
  PAYMENT_METHODS,
  buildDefaultReceiptMessage,
  buildWhatsAppShareUrl,
  normalizeWhatsAppPhone,
  type PaymentMethod,
} from '@/lib/payment.constants'

// ── Props ────────────────────────────────────────────────────────────────────
interface PaymentModalProps {
  isOpen: boolean
  onClose: () => void
  /** Callback cuando el pago se persiste correctamente. */
  onSuccess?: (info: { paymentId: string; receiptSent: boolean }) => void
  eventId: string
  workerId: string
  workerName: string
  universalId?: string | null
  companyName: string
  branchName?: string | null
  receivedBy: string
}

// ── Helpers ──────────────────────────────────────────────────────────────────
function formatCurrency(n: number): string {
  return new Intl.NumberFormat('es-MX', {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
  }).format(n)
}

function parseAmount(input: string): number {
  if (!input) return NaN
  // Aceptar coma decimal europea
  const normalized = input.replace(',', '.').replace(/[^0-9.]/g, '')
  return Number(normalized)
}

// ── Componente ───────────────────────────────────────────────────────────────
export default function PaymentModal({
  isOpen,
  onClose,
  onSuccess,
  eventId,
  workerId,
  workerName,
  universalId,
  companyName,
  branchName,
  receivedBy,
  }: PaymentModalProps) {
  const [isPending, startTransition] = useTransition()
  const [error, setError] = useState<string | null>(null)

  const [method, setMethod] = useState<PaymentMethod>('EFECTIVO')
  const [amountStr, setAmountStr] = useState('')
  const [reference, setReference] = useState('')
  const [sendReceipt, setSendReceipt] = useState(false)
  const [recipientEmail, setRecipientEmail] = useState('')
  // ARCH-20260630-02: WhatsApp Web option
  const [sendWhatsApp, setSendWhatsApp] = useState(false)
  const [whatsAppPhone, setWhatsAppPhone] = useState('')
  // FIX-20260630-04: Estado de éxito con datos para construir <a> wa.me
  // Patrón copiado de AppointmentFormModal.tsx (línea 286-328)
  const [successInfo, setSuccessInfo] = useState<{
    paymentId: string
    whatsAppUrl: string | null
    receiptSent: boolean
  } | null>(null)

  const amount = useMemo(() => parseAmount(amountStr), [amountStr])
  const amountValid = Number.isFinite(amount) && amount > 0

  const emailValid = useMemo(() => {
    if (!sendReceipt) return true
    return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(recipientEmail.trim())
  }, [sendReceipt, recipientEmail])

  const whatsAppPhoneValid = useMemo(() => {
    if (!sendWhatsApp) return true
    return normalizeWhatsAppPhone(whatsAppPhone).length >= 12
  }, [sendWhatsApp, whatsAppPhone])

  const canSubmit = amountValid && emailValid && whatsAppPhoneValid && !isPending

  const reset = useCallback(() => {
    setMethod('EFECTIVO')
    setAmountStr('')
    setReference('')
    setSendReceipt(false)
    setRecipientEmail('')
    setSendWhatsApp(false)
    setWhatsAppPhone('')
    setSuccessInfo(null)
    setError(null)
  }, [])

  const handleClose = useCallback(() => {
    if (isPending) return
    reset()
    onClose()
  }, [isPending, reset, onClose])

  const generatePdfDataUrl = useCallback(async (): Promise<string | undefined> => {
    try {
      const payload: ReceiptPDFData = {
        paymentId: `PENDIENTE-${Date.now()}`,
        eventId,
        createdAt: new Date(),
        amount,
        method: getPaymentMethodLabel(method),
        reference: reference.trim() || null,
        worker: { firstName: workerName.split(' ')[0] ?? '', lastName: workerName.split(' ').slice(1).join(' ') || '·', universalId },
        company: companyName ? { name: companyName } : null,
        branch: branchName ? { name: branchName } : null,
        receivedBy,
      }
      const blob = await pdf(<PaymentReceiptPDF data={payload} />).toBlob()
      return await new Promise<string>((resolve, reject) => {
        const reader = new FileReader()
        reader.onload = () => resolve(reader.result as string)
        reader.onerror = reject
        reader.readAsDataURL(blob)
      })
    } catch (err) {
      console.warn('[PaymentModal] No se pudo generar el PDF, continuando sin adjunto.', err)
      return undefined
    }
  }, [amount, method, reference, eventId, workerName, universalId, companyName, branchName, receivedBy])

  const handleSubmit = useCallback(() => {
    setError(null)
    if (!amountValid) {
      setError('El monto debe ser mayor a 0.')
      return
    }
    if (sendReceipt && !emailValid) {
      setError('Ingresa un email válido para enviar el recibo.')
      return
    }
    if (sendWhatsApp && !whatsAppPhoneValid) {
      setError('Ingresa un teléfono válido para enviar por WhatsApp (mínimo 10 dígitos).')
      return
    }

    startTransition(async () => {
      // FIX-20260630-04: Patrón copiado de AppointmentFormModal.tsx.
      //
      // Simplicidad:
      //   1. Solo persistir el pago (sin PDF, sin storage, sin upload).
      //   2. Construir la URL de wa.me client-side con los datos del pago.
      //   3. Mostrar un botón <a href="wa.me..." target="_blank"> que el usuario
      //      hace click → el navegador abre nueva pestaña a WhatsApp Web.
      //   4. Si el usuario no quiere WhatsApp, solo cierra el modal.
      //
      // NO popup blocker, NO endpoint, NO storage, NO complejidad.
      // Patrón ya probado en producción: AppointmentFormModal línea 286.

      // Generar PDF solo si se va a enviar por email
      const pdfDataUrl = sendReceipt ? await generatePdfDataUrl() : undefined

      // 1. Persistir el pago (puede incluir envío email)
      const result = await createPaymentRecord({
        eventId,
        workerId,
        amount,
        method,
        reference: reference.trim() || null,
        sendReceiptTo: sendReceipt ? recipientEmail.trim() : undefined,
        pdfDataUrl,
      })

      if (!result.success || !result.paymentId) {
        setError(result.error ?? 'Error al registrar el pago.')
        return
      }

      // 2. Construir URL de WhatsApp client-side (si el usuario marcó WhatsApp)
      const whatsAppUrl = sendWhatsApp
        ? buildWhatsAppShareUrl(
            whatsAppPhone.trim(),
            buildDefaultReceiptMessage({
              amount: formatCurrency(amount),
              methodLabel: getPaymentMethodLabel(method),
              paymentId: result.paymentId,
              workerName,
              downloadUrl: null,
            })
          )
        : null

      // 3. Mostrar pantalla de éxito con el botón de WhatsApp (si aplica)
      setSuccessInfo({
        paymentId: result.paymentId,
        whatsAppUrl,
        receiptSent: !!result.receiptSent,
      })

      onSuccess?.({
        paymentId: result.paymentId,
        receiptSent: !!result.receiptSent,
      })
    })
  }, [
    amountValid,
    amount,
    emailValid,
    whatsAppPhoneValid,
    sendReceipt,
    sendWhatsApp,
    recipientEmail,
    whatsAppPhone,
    generatePdfDataUrl,
    eventId,
    workerId,
    method,
    reference,
    workerName,
    onSuccess,
    reset,
    onClose,
  ])

  if (!isOpen) return null

  // FIX-20260630-04: Pantalla de éxito (patrón AppointmentFormModal).
  // Render ANTES del formulario para no mostrarlo después del pago.
  if (successInfo) {
    return (
      <div className="fixed inset-0 bg-black/60 backdrop-blur-sm flex items-center justify-center z-50 p-4 animate-in fade-in duration-200">
        <div className="bg-white rounded-3xl shadow-2xl w-full max-w-xl overflow-hidden">
          {/* Header verde de éxito */}
          <div className="bg-emerald-500 px-8 py-6 text-white">
            <div className="flex items-center gap-3">
              <span className="text-3xl">✅</span>
              <div>
                <h2 className="text-lg font-black">¡Pago Registrado!</h2>
                <p className="text-emerald-100 text-xs font-medium">
                  Folio: <span className="font-mono">{successInfo.paymentId.slice(0, 8)}</span>
                </p>
              </div>
            </div>
          </div>

          <div className="p-8 space-y-5">
            {/* Resumen del pago */}
            <section className="bg-slate-50 rounded-2xl p-5 space-y-2 border border-slate-100">
              <div className="flex justify-between">
                <span className="text-xs text-slate-500">Trabajador:</span>
                <span className="text-sm font-bold text-slate-800">{workerName}</span>
              </div>
              <div className="flex justify-between">
                <span className="text-xs text-slate-500">Monto:</span>
                <span className="text-sm font-bold text-emerald-700">${formatCurrency(amount)} MXN</span>
              </div>
              <div className="flex justify-between">
                <span className="text-xs text-slate-500">Método:</span>
                <span className="text-sm font-medium text-slate-700">{getPaymentMethodLabel(method)}</span>
              </div>
              {successInfo.receiptSent && (
                <div className="pt-2 border-t border-slate-200">
                  <p className="text-xs text-emerald-700 font-medium">
                    📧 Recibo enviado por email
                  </p>
                </div>
              )}
            </section>

            {/* Botón WhatsApp (patrón AppointmentFormModal) */}
            {successInfo.whatsAppUrl && (
              <a
                href={successInfo.whatsAppUrl}
                target="_blank"
                rel="noopener noreferrer"
                className="block w-full bg-[#25D366] hover:bg-[#128C7E] text-white py-3 rounded-xl font-bold transition-all hover:scale-[1.02] flex items-center justify-center gap-2"
              >
                <span>📱</span> Enviar Recibo por WhatsApp
              </a>
            )}

            {/* Botón cerrar */}
            <button
              onClick={() => {
                setSuccessInfo(null)
                reset()
                onClose()
              }}
              className="block w-full bg-slate-100 hover:bg-slate-200 text-slate-600 py-3 rounded-xl font-bold transition-all"
            >
              Cerrar
            </button>
          </div>
        </div>
      </div>
    )
  }

  return (
    <div className="fixed inset-0 bg-black/60 backdrop-blur-sm flex items-center justify-center z-50 p-4 animate-in fade-in duration-200">
      <div className="bg-white rounded-3xl shadow-2xl w-full max-w-xl overflow-hidden max-h-[95vh] flex flex-col">
        {/* Header */}
        <div className="bg-amber-500 px-8 py-6 text-white flex-shrink-0">
          <div className="flex items-center gap-3">
            <span className="text-3xl">💳</span>
            <div>
              <h2 className="text-lg font-black">Pago y Recibo</h2>
              <p className="text-amber-100 text-xs font-medium">
                Registra el pago de la papeleta y emite un comprobante · Email o WhatsApp
              </p>
            </div>
          </div>
        </div>

        <div className="overflow-y-auto flex-1 p-8 space-y-6">
          {/* Datos del evento */}
          <section className="bg-slate-50 rounded-2xl p-5 space-y-3 border border-slate-100">
            <p className="text-[10px] uppercase font-bold text-slate-400 tracking-widest">
              Papeleta
            </p>
            <div className="grid grid-cols-2 gap-3">
              <div>
                <p className="text-[10px] font-bold text-slate-400 uppercase">
                  Trabajador
                </p>
                <p className="text-sm font-medium text-slate-700">
                  {workerName || '—'}
                </p>
              </div>
              {universalId && (
                <div>
                  <p className="text-[10px] font-bold text-slate-400 uppercase">
                    ID
                  </p>
                  <p className="text-xs font-mono text-slate-500">
                    {universalId}
                  </p>
                </div>
              )}
              <div>
                <p className="text-[10px] font-bold text-slate-400 uppercase">
                  Empresa
                </p>
                <p className="text-sm font-medium text-slate-700">
                  {companyName || '—'}
                </p>
              </div>
              {branchName && (
                <div>
                  <p className="text-[10px] font-bold text-slate-400 uppercase">
                    Sucursal
                  </p>
                  <p className="text-sm font-medium text-slate-700">
                    {branchName}
                  </p>
                </div>
              )}
            </div>
          </section>

          {/* Método de pago */}
          <section className="space-y-3">
            <p className="text-[10px] uppercase font-bold text-slate-400 tracking-widest">
              Método de pago
            </p>
            <select
              value={method}
              onChange={(e) => setMethod(e.target.value as PaymentMethod)}
              disabled={isPending}
              className="w-full bg-slate-50 ring-1 ring-slate-200 focus:ring-2 focus:ring-amber-400 border-none p-3 rounded-xl text-sm outline-none disabled:opacity-60"
            >
              {PAYMENT_METHODS.map((m) => (
                <option key={m} value={m}>
                  {getPaymentMethodLabel(m)}
                </option>
              ))}
            </select>
          </section>

          {/* Monto */}
          <section className="space-y-3">
            <p className="text-[10px] uppercase font-bold text-slate-400 tracking-widest">
              Monto
            </p>
            <div className="relative">
              <span className="absolute left-3 top-1/2 -translate-y-1/2 text-sm font-bold text-slate-400">
                $
              </span>
              <input
                type="text"
                inputMode="decimal"
                value={amountStr}
                onChange={(e) => setAmountStr(e.target.value)}
                placeholder="0.00"
                disabled={isPending}
                className="w-full bg-slate-50 ring-1 ring-slate-200 focus:ring-2 focus:ring-amber-400 border-none p-3 pl-8 rounded-xl text-lg font-bold outline-none disabled:opacity-60"
              />
            </div>
            {amountStr && !amountValid && (
              <p className="text-[10px] text-red-600 font-medium">
                Ingresa un monto válido mayor a 0.
              </p>
            )}
            {amountValid && (
              <p className="text-[10px] text-emerald-600 font-medium">
                Monto a registrar: ${formatCurrency(amount)} MXN
              </p>
            )}
          </section>

          {/* Referencia / Nota */}
          <section className="space-y-3">
            <p className="text-[10px] uppercase font-bold text-slate-400 tracking-widest">
              Referencia / Nota <span className="text-slate-400 font-normal">(opcional)</span>
            </p>
            <textarea
              value={reference}
              onChange={(e) => setReference(e.target.value)}
              maxLength={500}
              rows={2}
              disabled={isPending}
              placeholder="Folio de transferencia, número de cheque, autorización, etc."
              className="w-full bg-slate-50 ring-1 ring-slate-200 focus:ring-2 focus:ring-amber-400 border-none p-3 rounded-xl text-sm outline-none resize-none disabled:opacity-60"
            />
          </section>

          {/* Enviar recibo por email */}
          <section className="space-y-3 border-t border-slate-100 pt-4">
            <label className="flex items-center gap-3 cursor-pointer">
              <input
                type="checkbox"
                checked={sendReceipt}
                onChange={(e) => setSendReceipt(e.target.checked)}
                disabled={isPending}
                className="w-4 h-4 accent-amber-500"
              />
              <span className="text-xs font-bold text-slate-700">
                📧 Enviar recibo por email
              </span>
            </label>
            {sendReceipt && (
              <div className="space-y-2">
                <label className="text-xs font-bold text-slate-500 block">
                  Email destino <span className="text-red-500">*</span>
                </label>
                <input
                  type="email"
                  value={recipientEmail}
                  onChange={(e) => setRecipientEmail(e.target.value)}
                  disabled={isPending}
                  placeholder="cliente@empresa.com"
                  className="w-full bg-slate-50 ring-1 ring-slate-200 focus:ring-2 focus:ring-amber-400 border-none p-3 rounded-xl text-sm outline-none disabled:opacity-60"
                />
                {recipientEmail && !emailValid && (
                  <p className="text-[10px] text-red-600 font-medium">
                    Email inválido.
                  </p>
                )}
                <p className="text-[10px] text-slate-400">
                  Se adjuntará un PDF del recibo generado al momento del pago.
                </p>
              </div>
            )}
          </section>

          {/* ARCH-20260630-02: Enviar recibo por WhatsApp Web */}
          <section className="space-y-3">
            <label className="flex items-center gap-3 cursor-pointer">
              <input
                type="checkbox"
                checked={sendWhatsApp}
                onChange={(e) => setSendWhatsApp(e.target.checked)}
                disabled={isPending}
                className="w-4 h-4 accent-emerald-500"
              />
              <span className="text-xs font-bold text-slate-700">
                📱 Enviar recibo por WhatsApp
              </span>
            </label>
            {sendWhatsApp && (
              <div className="space-y-2 bg-emerald-50 border border-emerald-200 rounded-xl p-3">
                <label className="text-xs font-bold text-emerald-700 block">
                  Teléfono destino <span className="text-red-500">*</span>
                </label>
                <input
                  type="tel"
                  value={whatsAppPhone}
                  onChange={(e) => setWhatsAppPhone(e.target.value)}
                  disabled={isPending}
                  placeholder="+52 1 55 1234 5678"
                  className="w-full bg-white ring-1 ring-emerald-200 focus:ring-2 focus:ring-emerald-400 border-none p-3 rounded-xl text-sm outline-none disabled:opacity-60"
                />
                {whatsAppPhone && !whatsAppPhoneValid && (
                  <p className="text-[10px] text-red-600 font-medium">
                    Teléfono inválido (mínimo 10 dígitos).
                  </p>
                )}
                <p className="text-[10px] text-emerald-700">
                  Después de registrar el pago, verás un botón verde para abrir WhatsApp Web con el mensaje prellenado.
                </p>
              </div>
            )}
          </section>

          {/* Error */}
          {error && (
            <p className="text-xs text-red-600 bg-red-50 p-3 rounded-xl border border-red-100 font-medium">
              ⚠️ {error}
            </p>
          )}
        </div>

        {/* Acciones */}
        <div className="flex gap-3 p-6 border-t border-slate-100 flex-shrink-0">
          <button
            onClick={handleClose}
            disabled={isPending}
            className="flex-1 bg-slate-100 hover:bg-slate-200 text-slate-600 py-3 rounded-2xl font-bold text-sm transition-all disabled:opacity-50"
          >
            Cancelar
          </button>
          <button
            onClick={handleSubmit}
            disabled={!canSubmit}
            className="flex-1 bg-amber-500 hover:bg-amber-600 text-white py-3 px-6 rounded-2xl font-black text-sm transition-all shadow-lg shadow-amber-100 disabled:opacity-50 disabled:cursor-not-allowed"
          >
            {isPending
              ? '⏳ Procesando...'
              : sendReceipt || sendWhatsApp
                ? '🧾 Registrar y Enviar Recibo'
                : '💾 Registrar Pago'}
          </button>
        </div>
      </div>
    </div>
  )
}

/**
 * @fileoverview Bloque de trazabilidad operativa ligera del evento médico.
 * Deriva visibilidad de avance, último movimiento y siguiente paso directamente
 * de los estados ya existentes de EventTest. No modifica el flujo clínico.
 * Las incidencias operativas se persisten en localStorage por eventId (V1, sin migración).
 * @id IMPL-20260507-07
 * @spec context/SPECs/SPEC_ARCH-20260507-07-TRAZABILIDAD-LIGERA-SIN-CAMBIAR-FLUJO.md
 * @backup context/checkpoints/CHK_IMPL-20260507-07-TRAZABILIDAD-LIGERA.md
 */
"use client"

import { useState, useEffect } from "react"

// Tipo mínimo compatible con StudyTest de PapeletaWorkspace (solo campos usados aquí)
type StudyStatus =
  | 'PENDING'
  | 'IN_PROGRESS'
  | 'SAMPLE_TAKEN'
  | 'RESULT_REGISTERED'
  | 'COMPLETED'
  | 'SKIPPED'
  | 'CANCELLED'

type TrazTest = {
  id: string
  testNameSnapshot: string
  status: StudyStatus
}

// IMPL-20260630-02: rename de labels según doc Renombramiento de catálogos (líneas 67-73)
const STATUS_LABELS: Record<StudyStatus, string> = {
  PENDING: 'Pendiente de resultado de prueba',
  IN_PROGRESS: 'En proceso',
  SAMPLE_TAKEN: 'Pendiente de resultado de prueba de laboratorio',
  RESULT_REGISTERED: 'Pendiente de Reporte de aptitud',
  COMPLETED: 'Pendiente de envio',
  SKIPPED: 'Omitido',
  CANCELLED: 'Cancelado',
}

/** Peso para determinar "más avanzado" sin timestamps */
const STATUS_WEIGHT: Record<StudyStatus, number> = {
  CANCELLED: 0,
  SKIPPED: 1,
  PENDING: 2,
  IN_PROGRESS: 3,
  SAMPLE_TAKEN: 4,
  RESULT_REGISTERED: 5,
  COMPLETED: 6,
}

const INCIDENCE_OPTIONS = [
  { value: 'EQUIPO_NO_DISPONIBLE', label: 'Equipo no disponible' },
  { value: 'PACIENTE_EN_ESPERA',   label: 'Paciente en espera prolongada' },
  { value: 'MUESTRA_REPETIR',      label: 'Muestra pendiente de repetir' },
  { value: 'SEGUIMIENTO_MANUAL',   label: 'Requiere seguimiento manual' },
] as const

type IncidenceValue = typeof INCIDENCE_OPTIONS[number]['value']

type Incidence = {
  type: IncidenceValue
  label: string
  testName?: string
  registeredAt: string
}

// --- Helpers ---------------------------------------------------------------

function getTimelineIcon(status: StudyStatus): string {
  if (status === 'COMPLETED')         return '✅'
  if (status === 'RESULT_REGISTERED') return '📊'
  if (status === 'SAMPLE_TAKEN')      return '🧪'
  if (status === 'IN_PROGRESS')       return '⏳'
  if (status === 'SKIPPED')           return '⏭️'
  if (status === 'CANCELLED')         return '❌'
  return '○'
}

function getTimelineBadge(status: StudyStatus): string {
  if (status === 'COMPLETED')         return 'bg-emerald-100 text-emerald-700'
  if (status === 'RESULT_REGISTERED') return 'bg-teal-100 text-teal-700'
  if (status === 'SAMPLE_TAKEN')      return 'bg-purple-100 text-purple-700'
  if (status === 'IN_PROGRESS')       return 'bg-blue-100 text-blue-700'
  if (status === 'SKIPPED')           return 'bg-slate-100 text-slate-500'
  if (status === 'CANCELLED')         return 'bg-red-100 text-red-500'
  return 'bg-slate-100 text-slate-400'
}

/** Detecta estudios de laboratorio por nombre (heurística ligera, sin importar isLabTest) */
function isLabByName(name: string): boolean {
  const n = name.toLowerCase()
  return (
    n.includes('sangre') || n.includes('sanguín') || n.includes('sanguinea') ||
    n.includes('biometría') || n.includes('biometria') ||
    n.includes('química') || n.includes('quimica') ||
    n.includes('glucosa') || n.includes('colesterol') ||
    n.includes('hemograma') || n.includes('orina') ||
    n.includes('ego') || n.includes('urin') ||
    n.includes('heces') || n.includes('copro') ||
    n.includes('laborat') || n.includes('lab ')
  )
}

// --- LocalStorage (incidencias V1) -----------------------------------------

function loadIncidences(eventId: string): Incidence[] {
  if (typeof window === 'undefined') return []
  try {
    const raw = localStorage.getItem(`ami_inc_${eventId}`)
    return raw ? (JSON.parse(raw) as Incidence[]) : []
  } catch {
    return []
  }
}

function persistIncidences(eventId: string, items: Incidence[]): void {
  if (typeof window === 'undefined') return
  try {
    localStorage.setItem(`ami_inc_${eventId}`, JSON.stringify(items))
  } catch { /* silent */ }
}

// --- Componente principal ---------------------------------------------------

interface TraceabilidadLigeraProps {
  eventId: string
  /** Compatible con StudyTest[] de PapeletaWorkspace (superconjunto de TrazTest) */
  tests: TrazTest[]
  readonly?: boolean
}

/**
 * ARCH-20260507-07: Bloque compacto de trazabilidad operativa ligera.
 * Se monta encima del flujo existente como capa de observabilidad.
 */
export default function TraceabilidadLigera({
  eventId,
  tests,
  readonly = false,
}: TraceabilidadLigeraProps) {
  const [expanded, setExpanded]     = useState(false)
  const [showForm, setShowForm]     = useState(false)
  const [selType, setSelType]       = useState<IncidenceValue>(INCIDENCE_OPTIONS[0].value)
  const [selTestId, setSelTestId]   = useState('')
  const [incidences, setIncidences] = useState<Incidence[]>([])

  useEffect(() => {
    setIncidences(loadIncidences(eventId))
  }, [eventId])

  // --- Métricas derivadas ---------------------------------------------------

  const activeTests    = tests.filter(t => t.status !== 'CANCELLED' && t.status !== 'SKIPPED')
  const completedTests = tests.filter(t => t.status === 'COMPLETED' || t.status === 'RESULT_REGISTERED')
  const totalActive    = activeTests.length
  const progressPct    = totalActive > 0 ? Math.round((completedTests.length / totalActive) * 100) : 0
  const pendingCount   = activeTests.filter(t => t.status === 'PENDING' || t.status === 'IN_PROGRESS').length
  const allDone        = totalActive > 0 && pendingCount === 0

  // Último movimiento: test con estado más avanzado entre los que ya tienen actividad
  const withActivity = tests.filter(
    t => t.status !== 'PENDING' && t.status !== 'CANCELLED' && t.status !== 'SKIPPED'
  )
  const ultimoMovimiento = withActivity.length > 0
    ? withActivity.reduce(
        (best, t) => STATUS_WEIGHT[t.status] >= STATUS_WEIGHT[best.status] ? t : best,
        withActivity[0]
      )
    : null

  // Siguiente paso: primero EN_PROGRESO, si no el primer PENDIENTE
  const inProgress   = tests.find(t => t.status === 'IN_PROGRESS')
  const firstPending = tests.find(t => t.status === 'PENDING')
  const siguientePaso: TrazTest | null = inProgress ?? firstPending ?? null

  // Hitos cruzados: muestras de laboratorio ya tomadas (visibilidad para médico/otras áreas)
  const sampleHitos = tests.filter(
    t =>
      isLabByName(t.testNameSnapshot) &&
      ['SAMPLE_TAKEN', 'RESULT_REGISTERED', 'COMPLETED'].includes(t.status)
  )

  // Timeline operativa: ordenada por peso de estado (más avanzado primero)
  const timelineTests = [...tests].sort(
    (a, b) => STATUS_WEIGHT[b.status] - STATUS_WEIGHT[a.status]
  )

  // --- Manejadores de incidencias -------------------------------------------

  function addIncidence() {
    const option = INCIDENCE_OPTIONS.find(o => o.value === selType)
    if (!option) return
    const testName = selTestId
      ? tests.find(t => t.id === selTestId)?.testNameSnapshot
      : undefined
    const inc: Incidence = {
      type: selType,
      label: option.label,
      testName,
      registeredAt: new Date().toLocaleTimeString('es-MX', {
        hour: '2-digit',
        minute: '2-digit',
      }),
    }
    const updated = [...incidences, inc]
    setIncidences(updated)
    persistIncidences(eventId, updated)
    setShowForm(false)
    setSelTestId('')
  }

  function removeIncidence(i: number) {
    const updated = incidences.filter((_, idx) => idx !== i)
    setIncidences(updated)
    persistIncidences(eventId, updated)
  }

  // --- Render ---------------------------------------------------------------

  return (
    <div className="bg-slate-50 border border-slate-200 rounded-xl overflow-hidden mb-3">

      {/* ── Cabecera siempre visible ──────────────────────────────────────── */}
      <div className="px-4 py-2.5 flex items-center justify-between gap-3">
        <div className="flex items-center gap-2.5 min-w-0">
          <span className="text-sm leading-none shrink-0">📍</span>
          <div className="min-w-0">
            <p className="text-[10px] font-bold text-slate-500 uppercase tracking-wider leading-tight">
              Estado del evento
            </p>
            <div className="flex items-center gap-2 mt-0.5 flex-wrap">
              <span className="text-xs font-semibold text-slate-700">
                {allDone
                  ? '✅ Todos completados'
                  : `${completedTests.length}/${totalActive} completados`}
              </span>
              {!allDone && (
                <div className="h-1.5 w-16 bg-slate-200 rounded-full overflow-hidden">
                  <div
                    className="h-full bg-teal-500 rounded-full transition-all duration-500"
                    style={{ width: `${progressPct}%` }}
                  />
                </div>
              )}
              {pendingCount > 0 && (
                <span className="text-[10px] text-amber-600 font-medium">
                  {pendingCount} pendiente{pendingCount > 1 ? 's' : ''}
                </span>
              )}
            </div>
          </div>
        </div>

        <button
          onClick={() => setExpanded(v => !v)}
          className="text-[11px] text-slate-400 hover:text-slate-600 font-medium shrink-0 transition-colors"
          aria-expanded={expanded}
        >
          {expanded ? 'Cerrar ▲' : 'Detalle ▼'}
        </button>
      </div>

      {/* ── Resumen compacto: último movimiento + siguiente paso ─────────── */}
      <div className="px-4 pb-3 grid grid-cols-2 gap-2">
        <div className="bg-white border border-slate-200 rounded-lg px-3 py-2">
          <p className="text-[9px] font-bold text-slate-400 uppercase tracking-wider mb-1">
            Último movimiento
          </p>
          {ultimoMovimiento ? (
            <>
              <p className="text-xs font-semibold text-slate-800 leading-tight truncate">
                {ultimoMovimiento.testNameSnapshot}
              </p>
              <p className="text-[10px] text-slate-500 mt-0.5">
                {STATUS_LABELS[ultimoMovimiento.status]}
              </p>
            </>
          ) : (
            <p className="text-xs text-slate-400 italic">Sin actividad aún</p>
          )}
        </div>

        <div className="bg-white border border-slate-200 rounded-lg px-3 py-2">
          <p className="text-[9px] font-bold text-slate-400 uppercase tracking-wider mb-1">
            Siguiente paso
          </p>
          {siguientePaso ? (
            <>
              <p className="text-xs font-semibold text-teal-700 leading-tight truncate">
                {siguientePaso.testNameSnapshot}
              </p>
              <p className="text-[10px] text-slate-500 mt-0.5">
                {STATUS_LABELS[siguientePaso.status]}
              </p>
            </>
          ) : (
            <p className="text-xs text-emerald-600 font-semibold">Sin pendientes</p>
          )}
        </div>
      </div>

      {/* ── Hitos cruzados: muestras de laboratorio ya tomadas ───────────── */}
      {sampleHitos.length > 0 && (
        <div className="px-4 pb-3 flex flex-wrap gap-1.5">
          {sampleHitos.map(t => (
            <span
              key={t.id}
              className="text-[10px] bg-purple-50 text-purple-700 border border-purple-200 px-2 py-0.5 rounded-full font-medium"
            >
              🧪 {t.testNameSnapshot}
            </span>
          ))}
        </div>
      )}

      {/* ── Incidencias activas (siempre visibles si existen) ────────────── */}
      {incidences.length > 0 && (
        <div className="px-4 pb-3 flex flex-wrap gap-1.5">
          {incidences.map((inc, i) => (
            <span
              key={i}
              className="inline-flex items-center gap-1 text-[10px] bg-amber-50 text-amber-700 border border-amber-200 px-2 py-0.5 rounded-full font-medium"
            >
              ⚠️ {inc.label}
              {inc.testName && (
                <span className="text-amber-500">— {inc.testName}</span>
              )}
              {!readonly && (
                <button
                  onClick={() => removeIncidence(i)}
                  className="text-amber-400 hover:text-amber-700 ml-0.5 leading-none"
                  aria-label="Quitar incidencia"
                >
                  ✕
                </button>
              )}
            </span>
          ))}
        </div>
      )}

      {/* ── Panel expandible: timeline + registro de incidencias ─────────── */}
      {expanded && (
        <div className="border-t border-slate-200 bg-white">

          {/* Timeline operativa */}
          <div className="px-4 py-3">
            <p className="text-[10px] font-bold text-slate-400 uppercase tracking-wider mb-2.5">
              Actividad operativa
            </p>
            <div className="space-y-2">
              {timelineTests.map(t => (
                <div key={t.id} className="flex items-center gap-2.5">
                  <span className="text-sm leading-none shrink-0">
                    {getTimelineIcon(t.status)}
                  </span>
                  <span className="text-xs text-slate-700 flex-1 truncate">
                    {t.testNameSnapshot}
                  </span>
                  <span
                    className={`text-[10px] font-bold px-2 py-0.5 rounded-full whitespace-nowrap ${getTimelineBadge(t.status)}`}
                  >
                    {STATUS_LABELS[t.status]}
                  </span>
                </div>
              ))}
            </div>
          </div>

          {/* Registro de incidencias */}
          {!readonly && (
            <div className="border-t border-slate-100 px-4 py-3">
              <div className="flex items-center justify-between gap-2 mb-2">
                <p className="text-[10px] font-bold text-slate-400 uppercase tracking-wider">
                  Incidencias operativas
                </p>
                {!showForm && (
                  <button
                    onClick={() => setShowForm(true)}
                    className="text-[10px] bg-amber-100 hover:bg-amber-200 text-amber-700 px-2 py-0.5 rounded font-bold transition-colors"
                  >
                    + Registrar
                  </button>
                )}
              </div>

              {showForm && (
                <div className="bg-amber-50 border border-amber-200 rounded-lg p-3 space-y-2">
                  <select
                    value={selType}
                    onChange={e => setSelType(e.target.value as IncidenceValue)}
                    className="w-full text-xs border border-amber-300 rounded px-2 py-1.5 bg-white outline-none focus:ring-1 focus:ring-amber-400"
                  >
                    {INCIDENCE_OPTIONS.map(o => (
                      <option key={o.value} value={o.value}>{o.label}</option>
                    ))}
                  </select>
                  <select
                    value={selTestId}
                    onChange={e => setSelTestId(e.target.value)}
                    className="w-full text-xs border border-amber-300 rounded px-2 py-1.5 bg-white outline-none focus:ring-1 focus:ring-amber-400"
                  >
                    <option value="">Estudio relacionado (opcional)</option>
                    {tests.map(t => (
                      <option key={t.id} value={t.id}>{t.testNameSnapshot}</option>
                    ))}
                  </select>
                  <div className="flex gap-2">
                    <button
                      onClick={addIncidence}
                      className="flex-1 bg-amber-600 hover:bg-amber-700 text-white text-xs px-3 py-1.5 rounded font-bold transition-colors"
                    >
                      Guardar
                    </button>
                    <button
                      onClick={() => { setShowForm(false); setSelTestId('') }}
                      className="text-xs text-slate-500 hover:text-slate-700 px-2"
                    >
                      Cancelar
                    </button>
                  </div>
                </div>
              )}

              {incidences.length === 0 && !showForm && (
                <p className="text-xs text-slate-400">Sin incidencias registradas.</p>
              )}
            </div>
          )}
        </div>
      )}
    </div>
  )
}

"use client"

import { useState } from "react"
import { updateSomatometria, updateAgudezaVisual } from "@/actions/medical-exam.actions"

export default function TriageForm({ eventId, initialData = {}, readonly = false }: { eventId: string, initialData?: any, readonly?: boolean }) {
  const [formData, setFormData] = useState(initialData)
  const [isSaving, setIsSaving] = useState(false)
  const [message, setMessage] = useState("")

  // Estado para Agudeza Visual (IMPL-20260318-07: movido desde DoctorExamForm)
  const [formVisual, setFormVisual] = useState(initialData?.eyeAcuityData || {
    vision_lejana_od: 'NO APLICA',
    vision_lejana_oi: 'NO APLICA',
    vision_cercana_od: 'NO APLICA',
    vision_cercana_oi: 'NO APLICA',
    lejana_corregida_od: 'NO APLICA',
    lejana_corregida_oi: 'NO APLICA',
    cercana_corregida_od: 'NO APLICA',
    cercana_corregida_oi: 'NO APLICA',
    reflejos: 'PRESENTES Y NORMOREFLECTICOS',
    test_ishihara: '',
    campimetria: ''
  })
  const [isSavingVisual, setIsSavingVisual] = useState(false)
  const [messageVisual, setMessageVisual] = useState("")

  const handleChange = (field: string, value: string) => {
    setFormData((prev: any) => ({ ...prev, [field]: value }))
  }

  const handleVisualChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setFormVisual((prev: any) => ({ ...prev, [e.target.name]: e.target.value }))
  }

  // Cálculos Automáticos
  const peso = parseFloat(formData.peso_kg) || 0
  const talla = parseFloat(formData.talla_m) || 0
  const imc = (peso > 0 && talla > 0) ? (peso / (talla * talla)).toFixed(2) : "0.00"

  let complexion = "NORMAL"
  if (parseFloat(imc) > 29.9) complexion = "OBESIDAD"
  else if (parseFloat(imc) > 24.9) complexion = "SOBREPESO"
  else if (parseFloat(imc) < 18.5 && parseFloat(imc) > 0) complexion = "BAJO PESO"

  const handleSave = async () => {
    setIsSaving(true)
    setMessage("")
    const payload = { ...formData, imc: parseFloat(imc), complexion }

    const res = await updateSomatometria(eventId, payload)
    if (res.success) {
      setMessage("✅ Somatometría guardada.")
    } else {
      setMessage("❌ Error: " + res.error)
    }
    setIsSaving(false)
  }

  const handleSaveVisual = async () => {
    setIsSavingVisual(true)
    setMessageVisual("")
    const res = await updateAgudezaVisual(eventId, formVisual)
    if (res.success) {
      setMessageVisual("✅ Agudeza Visual guardada.")
    } else {
      setMessageVisual("❌ Error: " + res.error)
    }
    setIsSavingVisual(false)
